const COURSE = {"id":"dev_deep","role":"dev","customization":{"industry":"通用研发场景（无行业属性）","company":"你的项目","product":"待交付功能"},"modules":[{"id":"M0","title":"M0 边界与红线：什么能做、什么绝不能做","dims":["tools","security"],"units":[{"id":"M00U1","tier":"basic","step":"understand","title":"开篇：认识老师与这门课","video":{"dur":"6.4min","script":["欢迎来到 AI Coding 实战","教研底座：真实场景与可带走产出","关于红线：先立规矩再谈效率"]},"ppt":{"method":"四步链路 + 八章地图","case":"从会写提示词到能交付上线，中间隔着工程化这条河","demo":"一张全景图看懂课程结构"},"objective":"说清四步链路、八章地图与学完的验收标准","transfer":"能自己复述这门课的结构，并判断自己应从哪一章开始","deliverable":{"type":"document","name":"学习路线卡","rubric":["起点自评","目标章节"],"acceptance":"一页纸：标出你现在卡在哪一步，以及学完想达到哪一步。"},"task":"看完开刊词，直接进入第一章正课。本章不设课后练习。","rubric":["起点写得具体，不是笼统的「都想学」"],"vslides":[{"t":"开篇 · 主讲老师介绍","n":"大家好，我是陈观，这门课的主讲老师。在正式开始之前，先用一分钟认识一下课程背后的教研团队。起点课堂有 60 多位特聘大厂总监，把他们的一线经验带进课程；12 年沉淀，服务过 3000 多家企业的交付现场；积累了 10000 多道测评题库、7 个行业 200 多个场景案例；还有 2000 多门 AI 课程经过蒸馏评审、持续迭代。这门课就是把这些经验拆成你能照着做、能验收的动作。","s":"","d":99.5},{"t":"欢迎来到 AI Coding 实战","n":"大家好，我是陈观，这门 AI Coding 实战课的主讲老师。在开始之前，我想先说清楚这门课不是什么。它不是一门编程语言课，也不会教你背提示词模板。它只做一件事：把研发工程师每天真实要做的事——拆需求、写代码、审代码、补测试、交交付物——一帧一帧拆开，告诉你 AI 能在每一步替你做什么、你又必须在哪一步亲自把关。学完这门课，你带走的不是一堆截图，而是一套能回工位就用、能被同事复核的工作方法。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"不是语言课\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">不是语言课</tspan></text></g><g data-k=\"不是模板课\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">不是模板课</tspan></text></g><g data-k=\"是可验收的工作方法\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"76.4\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">是可验收的工作</tspan><tspan x=\"326.0\" dy=\"16.900000000000002\">方法</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":46.1},{"t":"教研底座：真实场景与可带走产出","n":"这套课程的每个单元都遵循同一条链路：理解、演示、我要做、陪练。理解环节讲清概念和边界，演示环节看我怎么在真实场景里操作，我要做环节给你一个带验收口径的任务，陪练环节让 AI 扮成产品经理、评审人或安全专家来追问你。每个单元都配一份可以带走、可以交给主管看的产出物。这套结构来自我们对大量研发团队的调研：会背概念的人很多，能把 AI 产出交付上线的人很少，这门课补的就是后面这一段。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"理解\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">理解</tspan></text></g><g data-k=\"演示\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">演示</tspan></text></g><g data-k=\"我要做\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">我要做</tspan></text></g><g data-k=\"陪练\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">陪练</tspan></text></g><g data-k=\"带走产出\"><rect x=\"145.3\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">带走产出</tspan></text></g><g data-k=\"可复核\"><rect x=\"272.7\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">可复核</tspan></text></g></svg>","d":46.6},{"t":"关于红线：先立规矩再谈效率","n":"在一门教人用 AI 写代码的课里，红线必须先讲。这套课程会反复强调三件事：公司代码和数据不出域、AI 的结论必须有人复核、每一个技术判断都要能说清依据。这不是保守，而是让你能长期使用 AI 的前提。接下来的课程里，凡是涉及这三条的地方，我都会停下来提醒。希望学完这门课，你在团队里被人信任的方式不是「他用 AI 很快」，而是「他交付的东西靠得住」。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"数据不出域\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">数据不出域</tspan></text></g><g data-k=\"结论有人复核\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">结论有人复核</tspan></text></g><g data-k=\"判断有依据\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">判断有依据</tspan></text></g></svg>","d":39.1},{"t":"开场：先把地图拿走","n":"欢迎来到 AI Coding 实战。在正式开始之前，先花几分钟把地图拿走。这门课一共八章加一个开篇：M0 讲边界与红线，也就是什么能做、什么绝不能做；M1 到 M3 讲从需求到生成，怎么把一句话变成能跑的代码；M4 和 M5 讲审查与测试，让 AI 产出变得可靠；M6 讲交付与协作，把代码变成别人能接手的交付物；M7 是结业项目，端到端交付一个真实功能。学完这八章，你会走完一个完整的研发闭环。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"M0 红线\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">M0 红线</tspan></text></g><g data-k=\"M1–M3 需求到生成\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"76.4\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">M1–M3 需</tspan><tspan x=\"152.8\" dy=\"16.900000000000002\">求到生成</tspan></text></g><g data-k=\"M4–M5 审查测试\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"76.4\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">M4–M5 审</tspan><tspan x=\"247.2\" dy=\"16.900000000000002\">查测试</tspan></text></g><g data-k=\"M6–M7 交付结业\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"76.4\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">M6–M7 交</tspan><tspan x=\"341.8\" dy=\"16.900000000000002\">付结业</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":49.2},{"t":"怎么学：四步一条线","n":"每个单元你都会走同样的四步：理解、演示、我要做、陪练。理解是看懂概念和边界；演示是看我在真实场景里怎么操作；我要做是你自己动手完成一个带验收口径的任务；陪练是让 AI 扮成产品经理、Reviewer 或安全专家来追问你。四步走完，系统会给你一份可以带走的产出物。这套结构的目的只有一个：让你离开课程之后，能真的把事情做出来，而不是只记得几个术语。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"理解\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">理解</tspan></text></g><g data-k=\"演示\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">演示</tspan></text></g><g data-k=\"我要做\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">我要做</tspan></text></g><g data-k=\"陪练\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">陪练</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":41.2},{"t":"AI Coding 到底改变了什么","n":"先给一个判断：AI 没有改变「代码要正确」这件事，它改变的是代码的产生方式。过去你的时间大量花在查文档、写样板代码、拼测试用例上；现在这些可以交给 AI 起草，你的时间转向定义问题、审查结果、承担判断。角色从「写代码的人」更多变成「定义和验收代码的人」。这不是危言耸听，也不是替代论——它意味着你必须更懂业务、更懂质量，才能对 AI 的产出负责。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"过去：把代码写出来\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">过去：把代码写出来</tspan></text></g><g data-k=\"现在：定义与验收代码\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">现在：定义与验收代码</tspan></text></g></svg>","d":43.1},{"t":"不变的三条红线","n":"无论工具怎么变，三条红线不变。第一，数据不出域：公司代码、客户信息、密钥不能贴进公网 AI。第二，结论有人复核：AI 说「没问题」不等于没问题，最终判断必须由人签字。第三，判断有依据：每个技术结论都要能说清来源和验证方式。这三条会在后面反复出现。记住它们，是你在这门课里获得信任的基础。这三条不是口号，是你在团队里能不能长期用 AI 的通行证。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"数据不出域\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">数据不出域</tspan></text></g><g data-k=\"结论有人复核\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">结论有人复核</tspan></text></g><g data-k=\"判断有依据\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">判断有依据</tspan></text></g></svg>","d":43.8},{"t":"学完的验收标准","n":"这门课怎么算学完？不是看完视频，而是你能独立走完一个闭环：拿到一个模糊需求，拆成可验收任务，准备上下文，让 AI 生成模块，完成三问验收和安全初筛，补齐测试，产出 PR 描述和技术方案，最后把这次经验沉淀成一条团队规范。M7 的结业项目就是这件事的完整演练。每章结束有测验，测验不是考记忆，是考你能不能在具体情境里做出正确判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"拆需求\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">拆需求</tspan></text></g><g data-k=\"备上下文\"><g><circle cx=\"42\" cy=\"71.2\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"75.7\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"75.7\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">备上下文</tspan></text></g><g data-k=\"生成与审查\"><g><circle cx=\"42\" cy=\"100.4\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"104.9\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"104.9\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">生成与审查</tspan></text></g><g data-k=\"补测试\"><g><circle cx=\"42\" cy=\"129.6\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"134.1\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"134.1\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">补测试</tspan></text></g><g data-k=\"交付沉淀\"><g><circle cx=\"42\" cy=\"158.8\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"163.3\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">⑤</text></g><text x=\"70.0\" y=\"163.3\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">交付沉淀</tspan></text></g></svg>","d":37.2},{"t":"给自己定个起点","n":"最后的动作很简单：打开学习路线卡，标出你现在卡在哪一步。如果你还不敢把代码贴给 AI，从 M0 开始；如果你已经在用但产出质量不稳，重点看 M2 和 M4；如果你能生成但交不出去，直接看 M6。起点不同，顺序可以不同，但 M0 的红线模块不可跳过。写下你的起点，我们正式开始。起点不同没关系，顺序可以调，但 M0 的红线不能跳。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"标出当前卡点\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">标出当前卡点</tspan></text></g><g data-k=\"红线 M0 不跳过\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">红线 M0 不跳过</tspan></text></g><g data-k=\"写下目标章节\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写下目标章节</tspan></text></g></svg>","d":39.1}],"quiz":[],"template":"【学习路线卡】\n写下你的结论与依据：\n____________","brief":"【本单元要点】四步链路 + 八章地图\n【为什么重要】从会写提示词到能交付上线，中间隔着工程化这条河\n【看完做一件事】看完开刊词，直接进入第一章正课。本章不设课后练习。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M0U1","tier":"basic","step":"understand","title":"AI Coding 到底改变了什么","video":{"dur":"5.7min","script":["开场：从一句争论说起","AI 擅长的一：起草","AI 擅长的二：检索与解释"]},"ppt":{"method":"AI 强在起草与检索，弱在责任与判断","case":"一个真实场景：AI 十分钟生成一个模块，但没人能确认它符合业务规则","demo":"能做什么与不能做什么的对照图"},"objective":"说清 AI 能做与不能做的三件事","transfer":"下次听到「AI 能不能替代程序员」，能用三段话说清边界","deliverable":{"type":"document","name":"使用边界清单","rubric":["能做三件","不能做三件","一条承诺"],"acceptance":"一页纸：左边列 AI 擅长的三件事，右边列它不能替代你的三件事，底部写一条你的使用承诺。"},"task":"写一份个人 AI Coding 使用边界清单。","rubric":["能做与不能做各三条，互不重复","不能做的一条要涉及责任归属","承诺是可执行的具体动作"],"vslides":[{"t":"开场：从一句争论说起","n":"团队里常听到一句话：AI 是不是要替代程序员了。这个问题太大，我们换个问法：在你今天的工作里，AI 到底能替你做什么、不能替你做什么。把这件事说清楚，比争论替代论有用得多。这一节我们只谈边界，不谈工具，先把坐标系立起来。后面七节都会回到这张坐标系上。这堂课后面每一节都会落回三个词：起草、检索、负责。工具会变、模型会换代，但这三条边界基本不变。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"能起草\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">能起草</tspan></text></g><g data-k=\"能检索\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">能检索</tspan></text></g><g data-k=\"不能负责\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">不能负责</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":41.7},{"t":"AI 擅长的一：起草","n":"第一件擅长的事是起草。样板代码、配置文件、测试用例、正则、接口对接的骨架，这些有固定结构、上下文明确的东西，AI 起草的速度比你手敲快得多，而且质量通常不差。关键是你要给它清楚的规格：输入输出是什么、边界条件有哪些、遵守什么规范。给得越清楚，起草越可用。起草类任务有个简单判据：如果这件事做错了，你能一眼看出错在哪、并且改动成本很低，那就可以先让 AI 出草稿。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"样板代码\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">样板代码</tspan></text></g><g data-k=\"测试用例\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">测试用例</tspan></text></g><g data-k=\"配置正则\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">配置正则</tspan></text></g><g data-k=\"接口骨架\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">接口骨架</tspan></text></g></svg>","d":47.1},{"t":"AI 擅长的二：检索与解释","n":"第二件擅长的事是检索和解释。面对一段陌生代码或一个没用过的库，你可以让 AI 用三句话讲清它的作用、指出可能的坑、给出最小可用示例。这比自己翻文档快得多。但要记住，它给的解释也是「可能正确」的草稿，涉及关键路径时要回到源码或官方文档核对。用它读陌生代码时，记得给它一个明确的问题，而不是「帮我看看这段代码」。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"讲清陌生代码\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">讲清陌生代码</tspan></text></g><g data-k=\"指出可能的坑\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">指出可能的坑</tspan></text></g><g data-k=\"给最小示例\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">给最小示例</tspan></text></g></svg>","d":35.8},{"t":"AI 擅长的三：转译","n":"第三件擅长的事是转译：把口语化需求转成结构化任务，把一段代码转成技术方案，把错误的堆栈信息转成可能的原因清单。转译的本质是换一种表达，而 AI 在表达转换上很强。你仍然要判断转得对不对，但省下的是从零组织的力气。转译最实用的一个场景是把报错信息变成排查清单。把完整堆栈和触发条件贴进去，让它列出三种可能原因和各自的验证方法，你按清单逐一排除，比盯着堆栈猜快得多。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"口语→任务\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">口语→任务</tspan></text></g><g data-k=\"代码→方案\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">代码→方案</tspan></text></g><g data-k=\"报错→原因\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">报错→原因</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":44.3},{"t":"不能做的一：承担责任","n":"第一件不能做的是承担责任。AI 可以给出「这个改动应该没问题」，但线上出了问题，签字的人是你。责任不能被外包给一个模型。所以凡是涉及放行、上线、合并的判定，最终决定必须由人做出，并且留下判断依据。记住：AI 是副驾，不是签字的那个人。签字这件事没有捷径。你可以让 AI 帮你准备签字的材料——列风险、列验证结果、列已知限制——但最后那个「我确认可以上线」必须由人写出来，并且留痕。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"AI 可以建议\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">AI 可以建议</tspan></text></g><g data-k=\"人必须签字\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">人必须签字</tspan></text></g></svg>","d":45.7},{"t":"不能做的二：确定性问题","n":"第二件不能做的是给你确定的业务答案。它不知道你们系统的历史包袱，不知道客户那句「差不多」到底指什么。它能给你一个看起来合理的默认值，但那个默认值未必符合你的业务规则。凡是「必须这样，不能那样」的确定性判断，都要回到需求文档、代码或规则表去核实。它给的默认答案之所以危险，是因为它说得太肯定了。一个看起来合理的默认值，配上你的业务规则，可能完全不成立。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"不知历史包袱\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">不知历史包袱</tspan></text></g><g data-k=\"不懂客户潜台词\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">不懂客户潜台词</tspan></text></g><g data-k=\"默认值需核实\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">默认值需核实</tspan></text></g></svg>","d":41.9},{"t":"不能做的三：替你建立信任","n":"第三件不能做的是替你建立信任。同事信任你，是因为你交付的东西靠得住、出问题能说清原因。如果你把 AI 输出原样提交，一旦出错，损失的是你的信誉。信任只能靠你一次次的复核和承担责任积累起来。AI 可以让你更快，但「靠得住」这三个字必须你自己写。信任还有一个很实际的体现：出了问题你能讲清楚为什么这么改。如果你只会说「AI 建议这么改」，同事下次就不敢让你动了。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"复核\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">复核</tspan></text></g><g data-k=\"担责\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">担责</tspan></text></g><g data-k=\"积累信任\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">积累信任</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":42.7},{"t":"本节小结：把边界写下来","n":"把今天的结论写成一张清单：左边三件能交给 AI 起草的事，右边三件必须由你负责的事，底部写一条你的使用承诺。这张清单不是作业，是你从今天起用 AI 的行为准则。下一步我们会看三种典型的翻车现场，看看越界到底会发生什么。这张清单建议你真的贴到工位上。下次犹豫要不要把一段代码贴进公网 AI 时，花十秒扫一眼：属于哪一类、能不能脱敏、谁来判断。养成这个动作，比记住十条理论都管用。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"能做的三件\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">能做的三件</tspan></text></g><g data-k=\"不能做的三件\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">不能做的三件</tspan></text></g><g data-k=\"一条使用承诺\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">一条使用承诺</tspan></text></g></svg>","d":44.3}],"quiz":[{"q":"下列哪种任务最适合直接交给 AI 起草？","opts":["决定线上事故的责任归属","生成一段带样板结构的单元测试","判断某客户是否符合授信规则","签署代码上线的放行单"],"a":1,"why":"样板结构的测试代码是 AI 擅长的起草类任务；责任、业务判断和放行必须归人。"},{"q":"关于 AI Coding，正确的说法是？","opts":["AI 能完全替代代码审查","AI 生成的结论需要人复核并说清依据","用了 AI 就不用写测试","AI 的判断天然可追溯"],"a":1,"why":"AI 产出必须经人复核、依据可追溯，这是红线之一。"}],"template":"【个人使用边界清单】\nAI 擅长（起草/检索/转译）：\n1. ____\n2. ____\n3. ____\n我必须负责（责任/判断/信任）：\n1. ____","brief":"【本单元要点】AI 强在起草与检索，弱在责任与判断\n【为什么重要】一个真实场景：AI 十分钟生成一个模块，但没人能确认它符合业务规则\n【看完做一件事】写一份个人 AI Coding 使用边界清单。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M0U2","tier":"basic","step":"understand","title":"三种典型翻车现场","video":{"dur":"3.8min","script":["第一类：幻觉依赖","第二类：数据泄密","第三类：质量欠账"]},"ppt":{"method":"翻车都发生在「看起来没问题」的地方","case":"同事用 AI 生成的代码上线后引入了不存在的依赖，构建直接失败","demo":"三类翻车的对照图"},"objective":"识别幻觉依赖、泄密、质量欠账三类翻车","transfer":"拿到 AI 产出时先做三秒检查，而不是直接信任","deliverable":{"type":"document","name":"翻车案例对照卡","rubric":["幻觉","泄密","质量欠账"],"acceptance":"一页表：三类翻车各写一个真实信号、一个后果、一个预防动作。"},"task":"写一张翻车案例对照卡，列出三类翻车的识别信号。","rubric":["三类各有一条识别信号","预防动作是可执行的具体动作"],"vslides":[{"t":"第一类：幻觉依赖","n":"第一类翻车是幻觉。AI 会一本正经地引用一个根本不存在的库、函数或参数，语气还特别肯定。比如它告诉你用某个库的方法做日期格式化，你照着写，构建时才发现这个库里压根没有这个方法。识别信号很明确：凡是第一次见到的 API，都要回到官方文档或本地依赖里核实。不要因为答案写得像模像样就默认它存在。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"不存在的库或函数\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">不存在的库或函数</tspan></text></g><g data-k=\"看起来很肯定\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">看起来很肯定</tspan></text></g><g data-k=\"必须回文档核实\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">必须回文档核实</tspan></text></g></svg>","d":34.4},{"t":"第二类：数据泄密","n":"第二类翻车是泄密。你把一段真实业务代码连同数据库账号、客户字段一起贴进公网 AI，问它「帮我优化一下」。代码确实被优化了，但敏感信息已经离开公司边界。识别信号是粘贴前的那一秒：只要内容里出现真实姓名、手机号、密钥、内网地址、客户数据，就先停下脱敏。这一步省不得，一次泄密的代价远大于优化省下的时间。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"贴真实密钥与客户字段\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">贴真实密钥与客户字段</tspan></text></g><g data-k=\"先脱敏再贴\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">先脱敏再贴</tspan></text></g></svg>","d":36.2},{"t":"第三类：质量欠账","n":"第三类翻车最隐蔽，叫质量欠账。代码能跑，测试也过了，但里面留着硬编码、魔法数字、没有边界判断、错误被吞掉。短期内看不出问题，几个月后改一次就崩一次。识别信号是：你读代码时说不清某个值为什么是这个数、某段异常为什么被忽略。AI 擅长给你「能跑」的版本，但「能维护」要靠你追问和重构。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"能跑 ≠ 能维护\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">能跑 ≠ 能维护</tspan></text></g><g data-k=\"硬编码和魔法数字\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"76.4\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">硬编码和魔法数</tspan><tspan x=\"200.0\" dy=\"16.900000000000002\">字</tspan></text></g><g data-k=\"追问与重构\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">追问与重构</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":35.1},{"t":"三秒检查法","n":"怎么在翻车前拦住它？养成三秒检查。第一秒看来源：它引用的库和方法真实存在吗？第二秒看数据：我贴进去的内容有没有敏感信息？第三秒看质量：这段代码我能不能说清每一行的用意？三秒过了再往下走。这三秒不是形式主义，而是把你从「信任 AI」切换到「验收 AI」的开关。三秒检查法的顺序不能乱：先看来源，确认这段代码或依赖从哪来；","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"看来源\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">看来源</tspan></text></g><g data-k=\"看数据\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">看数据</tspan></text></g><g data-k=\"看质量\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">看质量</tspan></text></g></svg>","d":41.3},{"t":"把信号写进对照卡","n":"把三类翻车各写一个你遇到过的真实信号、一个可能的后果、一个预防动作，汇成一张对照卡。这张卡的价值在于把别人的教训变成你的检查清单。下次看到 AI 给出一个漂亮答案时，你脑子里跳出的不再是「真快」，而是「这三类问题有没有中招」。把这张对照卡填完，你就有了自己的翻车预警器。它不保证你永远不犯错，但能保证你在同样的坑面前不会第二次掉进去——这正是经验和不经验的区别。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"幻觉信号\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">幻觉信号</tspan></text></g><g data-k=\"泄密信号\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">泄密信号</tspan></text></g><g data-k=\"质量信号\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">质量信号</tspan></text></g><g data-k=\"预防动作\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">预防动作</tspan></text></g></svg>","d":41.0},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「三种典型翻车现场」。拿到 AI 产出时先做三秒检查，而不是直接信任把今天最有价值的三点写进产出物「翻车案例对照卡」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：写一张翻车案例对照卡，列出三类翻车的识别信号。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":39.1}],"quiz":[{"q":"AI 生成代码里引用了一个不存在的库，这属于哪类翻车？","opts":["泄密","幻觉依赖","质量欠账","性能问题"],"a":1,"why":"凭空捏造库名或 API 属于典型的幻觉，必须核实依赖真实存在。"},{"q":"预防质量欠账最有效的动作是？","opts":["直接采用 AI 的第一版","跳过测试赶进度","要求生成后做三问验收","把代码贴到公开 AI 求助"],"a":2,"why":"正确性、安全性、可维护性三问验收，是把 AI 草稿变成可靠产出的关键闸门。"}],"template":"【翻车对照卡】\n类型｜识别信号｜后果｜预防动作\n幻觉｜____\n泄密｜____\n质量欠账｜____","brief":"【本单元要点】翻车都发生在「看起来没问题」的地方\n【为什么重要】同事用 AI 生成的代码上线后引入了不存在的依赖，构建直接失败\n【看完做一件事】写一张翻车案例对照卡，列出三类翻车的识别信号。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M0U3","tier":"basic","step":"understand","title":"人机分工：人定义什么、AI 做什么","video":{"dur":"4.0min","script":["分工不是比强弱","人定义：目标、边界、口径","AI 起草：有结构的中间产物"]},"ppt":{"method":"分工的核心不是谁更强，而是谁该负责","case":"同一个需求，把定义权交给 AI 会跑偏，把起草权留给自己会拖慢","demo":"人机分工判定表"},"objective":"给一个任务标出人机分界线","transfer":"接到任务先画分界线，明确哪些交给 AI、哪些自己扛","deliverable":{"type":"document","name":"人机分工判定表","rubric":["人定义","AI 起草","人验收"],"acceptance":"一页表：把一个真实任务拆成若干步骤，每步标注归人还是归 AI，并写明理由。"},"task":"选一个你手头的真实任务，画出人机分界线并填表。","rubric":["至少拆出四步","每一步都有归属与理由","责任类步骤明确归人"],"vslides":[{"t":"分工不是比强弱","n":"很多人纠结「AI 能不能替代我」，其实问错了。正确的问法是：这件事里，哪部分该由我定义和负责，哪部分可以让 AI 起草。分工的依据不是谁更强，而是谁该负责、谁掌握上下文。你掌握业务背景和系统历史，AI 掌握快速生成和海量检索。把各自放在擅长的位置，才是有效分工。很多人把分工理解成「谁更厉害」，其实分工看的是责任归属。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"人：定义与负责\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">人：定义与负责</tspan></text></g><g data-k=\"AI：起草与检索\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">AI：起草与检索</tspan></text></g></svg>","d":34.2},{"t":"人定义：目标、边界、口径","n":"第一步永远由你定义。目标是什么、做到什么程度算好、哪些东西绝对不能碰、验收口径怎么写——这些是 AI 给不了的答案，因为它不知道你的业务。一个真实例子：让 AI「写个登录接口」，它会给你通用版本；但如果你先定义「支持手机号验证码、失败三次锁定、密码不落日志」，它给出的东西才可用。定义越清楚，后面越省心。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"目标\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">目标</tspan></text></g><g data-k=\"边界\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">边界</tspan></text></g><g data-k=\"验收口径\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">验收口径</tspan></text></g></svg>","d":33.4},{"t":"AI 起草：有结构的中间产物","n":"中间那段交给 AI。在规格明确的前提下，让它起草函数、测试、文档、配置、正则。这些有结构、可验证的东西，AI 出得快也不容易跑偏。关键是你给的规格要结构化，而不是一句话。把「写个好用的函数」换成「输入是订单列表，输出是按金额降序的前十笔，金额用分存储，空列表返回空数组」，产出质量会完全不同。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"给结构化规格\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">给结构化规格</tspan></text></g><g data-k=\"AI 起草\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">AI 起草</tspan></text></g><g data-k=\"人验收\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">人验收</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":37.5},{"t":"人验收：三问与签字","n":"最后一步还是你。AI 给的东西要过三问：正确性、安全性、可维护性；过了才合并、才放行。这一步不能省，也不能交给另一个 AI 全权处理。记住一句话：AI 是副驾，方向盘和签字笔都在你手里。分工表上凡是涉及签字、上线、责任的地方，都必须写「人」。验收的三问要按顺序问：先问正确性，再问安全性，最后问可维护性。顺序反了会出现一种情况——代码写得很漂亮，但业务规则是错的。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"正确性\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">正确性</tspan></text></g><g data-k=\"安全性\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">安全性</tspan></text></g><g data-k=\"可维护性\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">可维护性</tspan></text></g></svg>","d":47.6},{"t":"填一张分工判定表","n":"现在选一个你手头的真实任务，把它拆成至少四步，每步标注归人还是归 AI，并写一句理由。你会很快发现：真正该交给 AI 的步骤比你想象的少，但每一步省下的时间都很实在；而该归人的步骤虽然不多，却决定了这件事的成败。这张表就是你未来用 AI 的工作习惯。填这张表的时候，最值得写的是「理由」那一栏。你会发现有些任务你以为该交给 AI，写完理由才发现里面藏着一个业务判断——那种就必须自己扛。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"拆四步\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">拆四步</tspan></text></g><g data-k=\"标归属\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">标归属</tspan></text></g><g data-k=\"写理由\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">写理由</tspan></text></g><g data-k=\"责任归人\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">责任归人</tspan></text></g></svg>","d":45.5},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「人机分工：人定义什么、AI 做什么」。接到任务先画分界线，明确哪些交给 AI、哪些自己扛把今天最有价值的三点写进产出物「人机分工判定表」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：选一个你手头的真实任务，画出人机分界线并填表。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":44.8}],"quiz":[{"q":"下列哪一步最适合交给 AI？","opts":["决定需求优先级","给一段已有规格的函数写测试骨架","拍板是否上线","确认事故责任"],"a":1,"why":"规格明确后写测试骨架属于起草类任务；优先级、上线与责任都归人。"},{"q":"人机分工的根本依据是？","opts":["谁打字更快","谁承担责任、谁掌握上下文","AI 会不会拒绝","代码行数多少"],"a":1,"why":"责任归属和上下文掌握程度决定分工，而不是速度或行数。"}],"template":"【人机分工判定表】\n任务：____\n步骤1｜归属｜理由\n步骤2｜归属｜理由\n步骤3｜归属｜理由\n责任签字人：____","brief":"【本单元要点】分工的核心不是谁更强，而是谁该负责\n【为什么重要】同一个需求，把定义权交给 AI 会跑偏，把起草权留给自己会拖慢\n【看完做一件事】选一个你手头的真实任务，画出人机分界线并填表。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M0U4","tier":"basic","step":"understand","title":"代码红线：绝不外传的五类内容","video":{"dur":"4.7min","script":["第一类：密钥与口令","第二类：客户与个人数据","第三类：内网拓扑与地址"]},"ppt":{"method":"不是所有代码都能贴给 AI，先看它带不带这五样东西","case":"一段看似普通的配置里藏着生产数据库口令","demo":"红线五类自查清单"},"objective":"判断给定代码能否贴进公网 AI","transfer":"粘贴前做一次五类红线扫描","deliverable":{"type":"document","name":"红线自查清单","rubric":["密钥口令","客户数据","内网地址","未公开逻辑","授权凭据"],"acceptance":"五类内容各写一条识别方法与一条处理动作，能贴墙使用。"},"task":"写一份红线自查清单，贴在工位上。","rubric":["覆盖五类","每类有识别与处理","处理动作可执行"],"vslides":[{"t":"第一类：密钥与口令","n":"绝对不能外传的第一类是密钥、口令、令牌、证书。它们常藏在配置文件、环境变量示例、注释里，看起来像普通字符串。一旦贴进公网 AI，等于把钥匙交出去。处理方法不是打码，而是彻底替换成占位符，例如把真实口令写成 YOUR_API_KEY。记住：只要它是用来认证的东西，就不离开公司边界。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"API Key\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">API Key</tspan></text></g><g data-k=\"数据库口令\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">数据库口令</tspan></text></g><g data-k=\"证书令牌\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">证书令牌</tspan></text></g></svg>","d":36.7},{"t":"第二类：客户与个人数据","n":"第二类是客户数据和个人信息：姓名、手机号、身份证、订单明细、账号列表。即使你只是想让 AI 帮忙格式化，也不能原样贴。处理方法是脱敏与最小化：换成虚构值、去掉可识别字段、只留结构。判断标准很简单——这段内容如果泄露出去，会不会定位到具体的人？会，就先脱敏。脱敏不是把名字换成张三就完事。客户编号、订单号、身份证片段、特殊备注，这些组合起来仍能定位到具体客户。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"真实客户名单\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">真实客户名单</tspan></text></g><g data-k=\"脱敏后的结构字段\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">脱敏后的结构字段</tspan></text></g></svg>","d":44.3},{"t":"第三类：内网拓扑与地址","n":"第三类是内网地址、域名、服务名、IP 段。这些看似无害，实际上暴露了公司系统结构。AI 不需要知道你的内网叫什么才能帮你写代码。把内网地址替换成 example.internal 这类占位符，既不影响代码结构，也不泄漏架构信息。凡是要贴一整段配置，先扫一遍有没有内网地址。替换占位符时，记得连注释和日志字符串一起查。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"扫内网地址\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">扫内网地址</tspan></text></g><g data-k=\"替换占位符\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">替换占位符</tspan></text></g><g data-k=\"再贴给 AI\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">再贴给 AI</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":38.0},{"t":"第四类：未公开业务逻辑","n":"第四类是未公开的业务逻辑，比如定价规则、风控策略、独家算法。这些是公司的竞争力，贴进公网 AI 就可能被用于训练或出现在别人的答案里。如果确实需要 AI 帮忙，只描述抽象结构，不写具体规则和数值。例如说「一个按阶梯计费的函数」，而不是把每一档的价格和条件原样贴出。定价规则和风控策略尤其容易被低估。它们看起来只是几行 if-else，却是公司花了真金白银试出来的。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"定价规则\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">定价规则</tspan></text></g><g data-k=\"风控策略\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">风控策略</tspan></text></g><g data-k=\"独家算法\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">独家算法</tspan></text></g></svg>","d":42.4},{"t":"第五类：授权与合同信息","n":"第五类是授权凭据、合同条款、合规文件。这类信息既有保密要求，也常涉及法律责任。它们根本不该出现在代码问答里。如果工作中确实要对这类文本做处理，应使用公司批准的内部工具，而不是公网对话窗口。红线不是限制你用 AI，而是划定哪些事根本不该用公网 AI 做。授权凭据和合同条款有一个共同点：泄露了不会立刻报错，但后果最严重。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"授权凭据\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">授权凭据</tspan></text></g><g data-k=\"合同条款\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">合同条款</tspan></text></g><g data-k=\"合规文件\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">合规文件</tspan></text></g><g data-k=\"内部工具\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">内部工具</tspan></text></g></svg>","d":39.6},{"t":"写一份能贴墙的清单","n":"把五类红线写成一张能贴在工位上的清单：每类一条识别方法、一条处理动作。下次粘贴前扫一眼，几秒钟就能拦住绝大多数事故。这里多花的十秒，可能避免的是一次严重的安全事件。这份清单的价值在于它能被别人执行。写的时候用「看到什么、做什么」的句式，比如「看到 API Key 字样→替换成占位符→再贴」，而不是「注意不要泄密」这种谁都知道但没人会做的话。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"五类齐全\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">五类齐全</tspan></text></g><g data-k=\"识别方法\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">识别方法</tspan></text></g><g data-k=\"处理动作\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">处理动作</tspan></text></g></svg>","d":40.5},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「代码红线：绝不外传的五类内容」。粘贴前做一次五类红线扫描把今天最有价值的三点写进产出物「红线自查清单」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：写一份红线自查清单，贴在工位上。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":38.4}],"quiz":[{"q":"下面哪一类内容可以贴进公网 AI？","opts":["生产数据库口令","脱敏后的结构字段说明","客户手机号名单","内网服务地址"],"a":1,"why":"去掉个人信息、只保留结构字段的说明可脱敏后使用；其余四类都属于红线。"},{"q":"发现代码里含密钥时，正确的处理是？","opts":["直接贴给 AI 让它优化","删掉密钥相关信息后再贴","先脱敏并改用占位符，必要时不用公网 AI","把密钥打码后照贴"],"a":2,"why":"密钥应彻底替换为占位符；涉敏场景应避免公网 AI，而不是简单打码。"}],"template":"【红线自查清单】\n1 密钥口令：识别____ 处理____\n2 客户数据：识别____ 处理____\n3 内网地址：识别____ 处理____\n4 未公开逻辑：识别____ 处理____\n5 授权合同：识别____ 处理____","brief":"【本单元要点】不是所有代码都能贴给 AI，先看它带不带这五样东西\n【为什么重要】一段看似普通的配置里藏着生产数据库口令\n【看完做一件事】写一份红线自查清单，贴在工位上。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M0U5","tier":"basic","step":"understand","title":"工具地图：按场景选对工具","video":{"dur":"5.0min","script":["先看场景，再看工具","场景一：行内补全","场景二：对话式重构"]},"ppt":{"method":"工具没有最好，只有最合适这个场景","case":"同一个团队里，补全、改代码、做架构的人用的工具往往不同","demo":"工具选型对照表"},"objective":"按场景选工具，不迷信单一工具","transfer":"面对新任务先判断场景，再选 AI 编码工具","deliverable":{"type":"document","name":"工具选型对照表","rubric":["补全","对话重构","命令行代理"],"acceptance":"一页表：三类场景各选一个工具，写明选用理由与一条使用注意。"},"task":"写一份工具选型对照表，按你的三类高频场景选工具。","rubric":["覆盖三类场景","理由与场景匹配","有安全注意"],"vslides":[{"t":"先看场景，再看工具","n":"市面上 AI 编码工具很多，选型的第一步不是比较排行榜，而是问自己：我现在要做的是什么。是写的时候顺手补全、是把一段代码整体重构、还是让一个代理在命令行里连续执行多步？场景不同，合适的工具形态完全不同。先定场景，再挑工具，顺序不能反。选工具时先问自己：这个任务是多步跨文件，还是单文件内的局部改动？前者才需要代理类工具，后者用行内补全或对话就够。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"定场景\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">定场景</tspan></text></g><g data-k=\"选工具\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">选工具</tspan></text></g><g data-k=\"验产出\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">验产出</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":42.2},{"t":"场景一：行内补全","n":"第一种场景是行内补全。你在 IDE 里写代码，工具根据上下文实时给出下一行或下一段建议，按 Tab 接受。它适合样板代码、重复结构、明显模式的补全，优势是几乎不打断你的思路。注意点是：接受之后一定要扫一眼，不要把没看懂的代码直接留在文件里。接受行内补全前扫一眼，重点是变量名和边界判断。补全工具最容易出现的问题不是语法错，而是它按「最常见写法」补全，恰好绕过了你这段业务必须处理的特殊情况。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"样板代码\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">样板代码</tspan></text></g><g data-k=\"重复结构\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">重复结构</tspan></text></g><g data-k=\"实时建议\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">实时建议</tspan></text></g><g data-k=\"接受后扫一眼\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">接受后扫一眼</tspan></text></g></svg>","d":48.7},{"t":"场景二：对话式重构","n":"第二种场景是对话式重构。你选中一段代码，让 AI 解释、改写、补测试或找问题。它适合处理局部但复杂的改动，比如把一个函数改成可测试的形式。关键是你给的任务要具体，说清输入输出和约束；模糊的「帮我优化一下」通常只会得到泛泛的改写。对话式重构的任务要写得像验收单：「把这个函数改成先判空再取值，函数名不变，补一条空值用例」。模糊的「帮我优化一下」，得到的往往是风格调整而不是你要的改动。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"解释代码\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">解释代码</tspan></text></g><g data-k=\"改写函数\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">改写函数</tspan></text></g><g data-k=\"补测试\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">补测试</tspan></text></g><g data-k=\"任务要具体\"><g><circle cx=\"30\" cy=\"154\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 154 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"158.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">任务要具体</tspan></text></g></svg>","d":43.6},{"t":"场景三：命令行代理","n":"第三种场景是命令行代理。你给它一个目标，它在终端里读取文件、修改代码、运行测试，循环推进。它适合跨文件的多步任务，比如加一个完整功能。但它权限最大、风险也最高：必须限定作用范围，盯着它的每一步，涉及删除和提交的动作要人工确认。命令行代理最需要的是边界。开始前先说清楚「只改这三个文件、不要动配置、每改一处先告诉我」，过程中盯住它列出的改动清单。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"跨文件多步任务\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">跨文件多步任务</tspan></text></g><g data-k=\"必须限定范围并盯全程\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">必须限定范围并盯全程</tspan></text></g></svg>","d":41.7},{"t":"数据边界决定能不能用","n":"无论哪种工具，都要过一次数据边界这关。工具是否会把你的代码用于训练、数据是否留在公司可接受的范围内、涉敏项目是否允许使用公网工具——这些问题要先有答案。很多团队不是禁止 AI，而是规定了「哪类项目用哪档工具」。把这条规则写进你的选型表，比只写工具名更有价值。数据边界这一格填不出来，就说明这个工具你暂时不能用，不是「先用着再说」。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"看数据处理政策\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">看数据处理政策</tspan></text></g><g data-k=\"看项目敏感度\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">看项目敏感度</tspan></text></g><g data-k=\"定可用工具\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">定可用工具</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":40.3},{"t":"写一页选型表","n":"把你的高频工作分成三类场景，各选一个工具，写清选用理由和一条使用注意，再加一行数据边界规则。这张表会让你在新工具层出不穷时保持清醒：你不是在追新，而是在为每个场景挑合适的帮手。这张选型表建议每个项目存一份。新人入职时直接给他这张表，比口头交代\"注意别乱贴\"有效得多——规则只有写下来并附带判断标准，才会被执行。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"补全\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">补全</tspan></text></g><g data-k=\"重构\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">重构</tspan></text></g><g data-k=\"代理\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">代理</tspan></text></g><g data-k=\"数据边界\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">数据边界</tspan></text></g></svg>","d":39.3},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「工具地图：按场景选对工具」。面对新任务先判断场景，再选 AI 编码工具把今天最有价值的三点写进产出物「工具选型对照表」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：写一份工具选型对照表，按你的三类高频场景选工具。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":45.0}],"quiz":[{"q":"需要快速补全一段样板代码，最适合的工具类型是？","opts":["IDE 内补全插件","通用聊天窗口","命令行代理","文档检索工具"],"a":0,"why":"IDE 内补全在写代码的当下给出建议，延迟最低，最适合样板补全。"},{"q":"选 AI 编码工具时，最重要的依据是？","opts":["哪个工具名气最大","当前任务的场景与数据边界","哪个工具最便宜","同事用哪个"],"a":1,"why":"场景决定工具形态，数据边界决定能否使用，这两点比名气和价格重要。"}],"template":"【工具选型对照表】\n场景｜工具｜理由｜注意\n补全｜____\n重构｜____\n代理｜____\n数据边界规则：____","brief":"【本单元要点】工具没有最好，只有最合适这个场景\n【为什么重要】同一个团队里，补全、改代码、做架构的人用的工具往往不同\n【看完做一件事】写一份工具选型对照表，按你的三类高频场景选工具。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M0U6","tier":"basic","step":"understand","title":"第一个 30 分钟：跑通一个真实小任务","video":{"dur":"4.2min","script":["选一个够小又真实的任务","写一条结构化指令","审查：三问加运行"]},"ppt":{"method":"第一件事要小到能完成，真实到有价值","case":"选了一个真实的小 bug 修复作为第一个 AI Coding 任务","demo":"首 task 记录卡"},"objective":"独立跑完一次生成、审查、提交","transfer":"拿到小任务能在半小时内走完生成到提交的完整闭环","deliverable":{"type":"document","name":"首 task 记录卡","rubric":["任务","指令","审查","提交"],"acceptance":"一页记录：写清你选的任务、给 AI 的指令、你的审查动作、最终提交结果。"},"task":"完成一个真实小任务，并填写首 task 记录卡。","rubric":["任务是真实的","记录了原始指令","有审查动作与结论"],"vslides":[{"t":"选一个够小又真实的任务","n":"第一件事的选择决定你能否建立信心。不要一上来就重构整个系统，也不要选一个没有验收标准的探索任务。最合适的是边界清晰、结果可验证的真实小任务，比如补一个边界判断、修一个明确的小 bug、给一个函数补测试。它小到半小时能完成，又真实到值得提交。选任务时有个反常识的建议：宁可选一个你完全懂的小任务，也不要选一个你不懂的大任务。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"边界清晰\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">边界清晰</tspan></text></g><g data-k=\"结果可验证\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">结果可验证</tspan></text></g><g data-k=\"半小时内可完成\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">半小时内可完成</tspan></text></g></svg>","d":38.4},{"t":"写一条结构化指令","n":"把任务写成结构化指令：背景是什么、要改哪个文件、输入输出是什么、约束有哪些、怎么算完成。比如「给用户注册函数增加手机号格式校验，手机号必须是 11 位数字，非法输入返回明确错误，补三条测试覆盖合法、非法、空值」。这样的指令一次就能得到可用草稿，比你来回追问十次都高效。结构化指令里，「约束」那一栏最容易被漏掉。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"背景\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">背景</tspan></text></g><g data-k=\"目标\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">目标</tspan></text></g><g data-k=\"约束\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">约束</tspan></text></g><g data-k=\"验收\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">验收</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":37.2},{"t":"审查：三问加运行","n":"拿到草稿先别高兴。问正确性：逻辑对不对，边界有没有漏；问安全性：有没有引入注入、硬编码、越权；问可维护性：命名和结构能不能被同事看懂。然后运行测试，让它真的跑一遍。审查不是挑刺，而是把「看起来对」变成「确认对」。运行测试这一步别省。AI 给的代码看着再合理，也要跑一遍你写的验收用例。这一轮你练的正是「不靠肉眼判断」，跑测试是成本最低、最可靠的验证方式。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"正确性\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">正确性</tspan></text></g><g data-k=\"安全性\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">安全性</tspan></text></g><g data-k=\"可维护性\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">可维护性</tspan></text></g><g data-k=\"跑测试\"><g><circle cx=\"30\" cy=\"154\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 154 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"158.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">跑测试</tspan></text></g></svg>","d":50.6},{"t":"提交：留下可追溯记录","n":"确认没问题后再提交。提交信息里写清改了什么、为什么改、验证了什么。如果是第一次用 AI 辅助，也可以注明使用了 AI 起草、由你审查——这在很多团队里是透明的做法。提交这一步的意义是把这次实践固化下来，让它成为可追溯的产出，而不是一次性的试验。提交记录里「为什么」比「改了什么」更重要。改了什么看 diff 就知道，但为什么这么改——参考了哪条规则、排除了什么方案——只有你当时说得清。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"写清改了什么\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">写清改了什么</tspan></text></g><g data-k=\"写清为什么\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">写清为什么</tspan></text></g><g data-k=\"写清验证方式\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">写清验证方式</tspan></text></g></svg>","d":39.4},{"t":"填写首 task 记录卡","n":"最后填一张记录卡：任务是什么、你给的原始指令、你做了哪些审查、最终结果如何。这四个字段会让你的第一次实践从「做过」变成「学会」。下次遇到类似任务，这张卡就是你的起点模板。这张记录卡是你后面所有实战的模板。它逼你回答四个问题：任务选得对不对、指令写得清不清、审查有没有漏、提交留没留痕。四个都答得上来，第一次闭环就算真正跑通了。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"任务\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">任务</tspan></text></g><g data-k=\"指令\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">指令</tspan></text></g><g data-k=\"审查\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">审查</tspan></text></g><g data-k=\"提交\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">提交</tspan></text></g></svg>","d":39.8},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「第一个 30 分钟：跑通一个真实小任务」。拿到小任务能在半小时内走完生成到提交的完整闭环把今天最有价值的三点写进产出物「首 task 记录卡」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：完成一个真实小任务，并填写首 task 记录卡。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":43.6}],"quiz":[{"q":"第一个 AI Coding 任务最适合选？","opts":["重构整个系统","一个边界清晰、能验证的真实小任务","没有验收标准的探索","一个你完全不懂的大模块"],"a":1,"why":"小而真实、边界清晰、结果可验证的任务，最适合第一次跑通闭环。"},{"q":"生成代码后，正确的下一步是？","opts":["直接提交","审查并运行测试通过后再提交","截图保存就结束","再让 AI 生成一遍"],"a":1,"why":"必须经过审查与测试验证，才能进入提交环节。"}],"template":"【首 task 记录卡】\n任务：____\n原始指令：____\n审查动作：____\n提交结果：____","brief":"【本单元要点】第一件事要小到能完成，真实到有价值\n【为什么重要】选了一个真实的小 bug 修复作为第一个 AI Coding 任务\n【看完做一件事】完成一个真实小任务，并填写首 task 记录卡。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M0U7","tier":"basic","step":"todo","title":"建立一个能复用的个人规则文件","video":{"dur":"4.5min","script":["为什么要写规则文件","写风格约定","写目录与命名约定"]},"ppt":{"method":"规则文件是把「每次都要说」变成「说一次就记住」","case":"同一团队新人写的 AI 代码风格混乱，因为没有人给 AI 统一规则","demo":"个人规则文件 .cursorrules 初版"},"objective":"写出含风格、目录、命名约定的规则文件","transfer":"把个人偏好固化成 AI 可读的规则，减少每次重复交代","deliverable":{"type":"document","name":".cursorrules 初版","rubric":["风格约定","目录约定","命名约定","红线约束"],"acceptance":"一份AI可读的规则文件：至少含风格、目录、命名三类约定，外加三条红线。"},"task":"写出你的个人规则文件初版，并请一位同事试用反馈。","rubric":["三类约定齐全","有红线约束","规则写成可执行的祈使句"],"vslides":[{"t":"为什么要写规则文件","n":"你有没有发现，每次让 AI 写代码都要重复交代：用驼峰命名、别用魔法数字、错误处理要显式。这些话说了十遍，第十一遍还得说。规则文件就是把这些反复交代的约定写一次，让工具每次自动读取。它不复杂，却是个人效率提升最大的一步。规则文件最大的价值是把「每次都要交代一遍」变成「一次写好自动生效」。写的时候想想你过去三周重复说过哪些话——那些就是规则文件的第一条、第二条。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"重复交代\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">重复交代</tspan></text></g><g data-k=\"写成规则\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">写成规则</tspan></text></g><g data-k=\"自动生效\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">自动生效</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":43.8},{"t":"写风格约定","n":"第一部分是风格约定。包括命名风格、缩进、注释语言、错误处理方式、是否允许简写。关键是写成可判定的祈使句，而不是形容词。不要写「代码要清晰」，要写「函数命名用动词开头的驼峰；超过三行的条件判断要抽取为具名函数」。可判定的规则 AI 才能执行，你才能验收。风格约定要写成可判定的句子。「代码要清晰」没法判定，「函数超过 40 行要考虑拆分」可以。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"命名风格\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">命名风格</tspan></text></g><g data-k=\"注释语言\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">注释语言</tspan></text></g><g data-k=\"错误处理\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">错误处理</tspan></text></g><g data-k=\"可判定表述\"><g><circle cx=\"30\" cy=\"154\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 154 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"158.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">可判定表述</tspan></text></g></svg>","d":45.0},{"t":"写目录与命名约定","n":"第二部分是目录和命名约定。源文件、测试文件、配置文件各放哪里；测试文件怎么命名；组件或模块的前缀是什么。这部分直接决定项目能不能被新人快速接手。把你当前项目里已经形成的习惯写下来，如果还没有习惯，就定一个简单一致的，先执行起来。目录与命名这一节，最容易漏的是「例外情况」。比如测试文件放哪里、生成代码放哪里、临时脚本放哪里。把例外写清楚，AI 才不会每次都按默认习惯放到错的位置。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"源码目录\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">源码目录</tspan></text></g><g data-k=\"测试目录\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">测试目录</tspan></text></g><g data-k=\"命名前缀\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">命名前缀</tspan></text></g><g data-k=\"文件后缀\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">文件后缀</tspan></text></g></svg>","d":46.5},{"t":"写红线约束","n":"第三部分是红线，而且是必须写的部分。把 M0 学过的红线固化进去：不得在代码中硬编码密钥，不得输出真实客户数据，引用第三方库前先标注需核实。这样即使某次你忘了提醒，工具也会按红线约束生成。规则文件里的红线，是你长期安全使用 AI 的护栏。红线约束里要写明「找不到真实值时怎么办」。不是让它猜一个，而是让它用占位符并标注需人工核实。这条规则会直接影响后面所有生成任务的安全性。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"硬编码密钥与真实数据\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">硬编码密钥与真实数据</tspan></text></g><g data-k=\"占位符与需核实标注\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">占位符与需核实标注</tspan></text></g></svg>","d":44.6},{"t":"请同事试用并迭代","n":"规则文件初版写完，别急着定稿。发给同组一位同事，请他用你的规则跑一个小任务，然后问三个问题：哪条规则看不懂、哪条规则他做不到、哪条他觉得多余。根据反馈改一版。规则文件不是一个人的偏好宣言，而是要能被团队读懂和执行的约定。请同事试用时，别问「你觉得怎么样」，让他真的拿一个任务跑一遍，然后把 AI 没遵守的地方圈出来。规则文件是给人用的，只有别人用得动，才算写对了。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"写完初版\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">写完初版</tspan></text></g><g data-k=\"请同事试用\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">请同事试用</tspan></text></g><g data-k=\"按反馈迭代\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">按反馈迭代</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":42.5},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「建立一个能复用的个人规则文件」。把个人偏好固化成 AI 可读的规则，减少每次重复交代把今天最有价值的三点写进产出物「.cursorrules 初版」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：写出你的个人规则文件初版，并请一位同事试用反馈。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":46.0}],"quiz":[{"q":"规则文件的主要作用是？","opts":["替代代码审查","把常用约定固定下来，减少重复交代","自动生成需求","隐藏业务逻辑"],"a":1,"why":"规则文件让 AI 在生成时遵循你的风格与约束，避免每次重复说明。"},{"q":"下面哪条规则写法最有效？","opts":["代码要写好一点","尽量规范一些","函数命名用驼峰，测试文件与源文件同目录","按通常做法处理"],"a":2,"why":"具体、可判定的规则才能被 AI 执行；「写好一点」这类模糊表述无效。"}],"template":"【个人规则文件初版】\n风格：____\n目录：____\n命名：____\n红线：1____ 2____ 3____","brief":"【本单元要点】规则文件是把「每次都要说」变成「说一次就记住」\n【为什么重要】同一团队新人写的 AI 代码风格混乱，因为没有人给 AI 统一规则\n【看完做一件事】写出你的个人规则文件初版，并请一位同事试用反馈。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M0U8","tier":"basic","step":"understand","title":"M0 通关测验：红线情境判断","video":{"dur":"4.2min","script":["通关说明","情境一：能不能贴","情境二：信不信"]},"ppt":{"method":"过关不是背下三条红线，而是遇到情境能判对","case":"给出一段含密钥与真实客户数据的代码，问能否贴给公网 AI","demo":"M0 通关标记"},"objective":"在情境题里正确识别红线与分工","transfer":"把红线判断从记忆变成条件反射","deliverable":{"type":"document","name":"通关标记","rubric":["情境判断","红线识别","分工判断"],"acceptance":"测验全部答对即获得通关标记，可解锁 M1 及后续章节。"},"task":"完成通关测验，全部情境判断正确。","rubric":["情境判断全部正确"],"vslides":[{"t":"通关说明","n":"这一节是 M0 的通关测验。题目全部是情境题，不是让你背三条红线，而是给一个真实场景，判断该怎么做。全部答对就拿到通关标记，可以进入 M1。答错也不要紧，系统会告诉你错在哪，回去看对应单元再来。红线模块不可跳过，这是这门课唯一的硬性要求。通关测验故意用情境题而不是概念题，因为真实工作里没人问你「红线有哪五类」，只会给你一段代码问「能不能贴」。练情境判断，才是把知识变成动作。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"全部情境题\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">全部情境题</tspan></text></g><g data-k=\"答错可重来\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">答错可重来</tspan></text></g><g data-k=\"红线不可跳过\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">红线不可跳过</tspan></text></g></svg>","d":45.0},{"t":"情境一：能不能贴","n":"第一类题判断能不能贴给公网 AI。判断口诀是：凡是密钥、客户数据、内网地址、未公开逻辑、授权合同，一律不贴；脱敏后的结构字段和通用问题可以。遇到不确定的，按不能贴处理。宁可少用一次 AI，也不要冒一次泄密的风险。情境一的关键不是记住五类名称，而是形成条件反射：先问「里面有没有真实数据或凭据」，再问「脱敏后结构还能不能用」。两问都过了，才谈得上贴给 AI。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"五类红线：不贴\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">五类红线：不贴</tspan></text></g><g data-k=\"脱敏结构：可用\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">脱敏结构：可用</tspan></text></g></svg>","d":46.4},{"t":"情境二：信不信","n":"第二类题判断能不能直接采信 AI 结论。答案永远是：不能直接采信。无论是代码、解释还是建议，都要经过人复核，并说清依据。特别是第一次见到的 API 和库，必须核实存在性。把「看起来对」和「确认对」区分开，是这一章最重要的能力。情境二里，正确的路径永远是「生成→核实→复核→采用」四步。跳过核实直接采用，是大多数人第一次用 AI 时最常犯的错；它不会被立刻发现，但会在某个上线夜里找上门。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"生成\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">生成</tspan></text></g><g data-k=\"核实\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">核实</tspan></text></g><g data-k=\"复核\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">复核</tspan></text></g><g data-k=\"采用\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">采用</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":49.0},{"t":"情境三：谁来负责","n":"第三类题判断责任归属。凡是签字、上线、放行、定责这类动作，都归人，不归 AI。AI 可以给建议，但承担后果的一定是人。记住副驾的比喻：AI 帮你开车，但方向盘和签字笔在你手里。谁来负责这道题的答案永远是人。你可以列出 AI 参与了多少、给了什么建议，但签字的那一行只能写人的名字。这个原则没有例外，也不需要例外。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"签字归人\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">签字归人</tspan></text></g><g data-k=\"上线归人\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">上线归人</tspan></text></g><g data-k=\"定责归人\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">定责归人</tspan></text></g></svg>","d":37.7},{"t":"拿到通关标记","n":"全部答对后，你会拿到 M0 的通关标记。这标志着你已经建立了这门课最重要的基础：知道什么能做、什么不能做、谁该负责。接下来进入 M1，我们开始讲怎么把一句模糊的需求拆成可执行的任务。带着红线意识往前走，后面所有技巧才有意义。拿到通关标记后，别急着冲 M1。把这五道题的场景抄进你的红线清单，下次遇到真实情况时对照着判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"识别红线\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">识别红线</tspan></text></g><g data-k=\"分清责任\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">分清责任</tspan></text></g><g data-k=\"进入 M1\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">进入 M1</tspan></text></g></svg>","d":36.6},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「M0 通关测验：红线情境判断」。把红线判断从记忆变成条件反射把今天最有价值的三点写进产出物「通关标记」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：完成通关测验，全部情境判断正确。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":38.9}],"quiz":[{"q":"同事说「AI 只是帮忙写个测试，不用想那么多」，正确回应是？","opts":["同意，测试不涉及红线","即使写测试也要看数据是否脱敏、依赖是否真实","只有生产代码才需要审查","测试跑过就行"],"a":1,"why":"测试代码同样可能含真实数据或幻觉依赖，红线适用于所有 AI 产出。"},{"q":"下面哪种情况可以用公网 AI？","opts":["含生产密钥的配置","含客户手机号的名单","脱敏后的结构描述与通用算法问题","未公开的定价规则"],"a":2,"why":"脱敏后的结构描述和通用问题是可接受的；其余都触及红线。"},{"q":"AI 给出的技术结论，正确的处理是？","opts":["直接采信","由人复核并说清依据后才采用","换个模型再问一遍就可信","只要答案长就可信"],"a":1,"why":"AI 结论必须经人复核并能说清依据，这是三条红线之一。"}],"template":"【M0 通关承诺】\n我已理解：数据不出域、结论有人复核、判断有依据。\n签名：____","brief":"【本单元要点】过关不是背下三条红线，而是遇到情境能判对\n【为什么重要】给出一段含密钥与真实客户数据的代码，问能否贴给公网 AI\n【看完做一件事】完成通关测验，全部情境判断正确。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"}]},{"id":"M1","title":"M1 需求拆解：把模糊变成可执行","dims":["prompt","content"],"units":[{"id":"M1U1","tier":"core","step":"understand","title":"一句话需求为什么做不出来","video":{"dur":"5.3min","script":["从一句话开始","缺口一：谁用","缺口二：什么场景"]},"ppt":{"method":"需求越模糊，AI 产出的偏差越大","case":"「做个用户反馈功能」这句话，十个人能做出十个样子","demo":"模糊需求五类缺口图"},"objective":"指出模糊需求的五类缺口","transfer":"拿到一句话需求先查五类缺口，再决定动手","deliverable":{"type":"document","name":"需求缺口 checklist","rubric":["用户缺口","场景缺口","输入缺口","输出缺口","算好缺口"],"acceptance":"一页清单：五类缺口各写一句判断问题，并用它检查一句真实需求。"},"task":"拿一句真实模糊需求，标出它的五类缺口。","rubric":["五类缺口齐全","每类有可复用的判断问题","用真实需求演练过"],"vslides":[{"t":"从一句话开始","n":"需求最常以一句话出现：「做个用户反馈功能」「加个导出按钮」。这种话人能靠上下文猜，AI 猜不了——它不知道谁用、什么场景、输入什么、输出什么、怎么算做好。结果就是它给你一个通用版本，你改到怀疑人生。这一节我们把模糊需求的缺口拆开看。这五类缺口不是理论分类，是你每次拿到需求时按顺序要问的五个问题。问完还答不上来的那一栏，就是这轮沟通必须补的东西——带着缺口去问人，比自己猜一个答案安全得多。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"一句话需求\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">一句话需求</tspan></text></g><g data-k=\"五类缺口\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">五类缺口</tspan></text></g><g data-k=\"可执行的任务\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">可执行的任务</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":45.0},{"t":"缺口一：谁用","n":"第一类缺口是用户没说清。是内部运营还是外部客户？是新手还是专家？用户的身份决定了权限、交互复杂度和错误提示的写法。给 AI 的指令里缺了这一项，它就只能按通用用户假设，产出往往不对味。补法是先写一句「这个功能的使用者是……」。「谁用」这一问要问到具体角色和权限。同一个功能，管理员看到的东西和普通用户不一样，熟练用户和第一次用的人路径也不一样。把使用者说清楚，后面的场景和验收才有落点。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"使用者身份\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">使用者身份</tspan></text></g><g data-k=\"权限差异\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">权限差异</tspan></text></g><g data-k=\"熟练度\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">熟练度</tspan></text></g></svg>","d":52.1},{"t":"缺口二：什么场景","n":"第二类缺口是场景。用户在什么情况下用它，是偶尔还是高频，是手机还是电脑，网络好不好。同一个功能在不同场景下设计完全不同。比如反馈功能在移动端要考虑输入简短，在后台管理里则可能要支持批量。场景不说，AI 只能选最常见的那种。场景这一栏最容易被省略，却最常导致返工。问清触发时机——用户是每天用一次还是出了事才用、是在办公室还是手机上、网络稳不稳定。这些条件会直接决定功能的形态。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"使用频率\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">使用频率</tspan></text></g><g data-k=\"设备形态\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">设备形态</tspan></text></g><g data-k=\"网络条件\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">网络条件</tspan></text></g><g data-k=\"触发时机\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">触发时机</tspan></text></g></svg>","d":49.0},{"t":"缺口三与四：输入与输出","n":"第三、四类缺口是输入和输出。输入是什么格式、来自哪里、有哪些字段；输出是什么形态、去到哪里、格式如何。这两项是 AI 生成代码最需要的硬信息。缺了它们，函数签名都是猜的。补法是把输入输出写成具体的结构，比如「输入订单 ID 列表，输出按金额排序的订单对象数组」。输入和输出要说清「结构」而不只是「有」。输入有哪些字段、从哪个系统来、格式是什么；","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"输入结构\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">输入结构</tspan></text></g><g data-k=\"数据来源\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">数据来源</tspan></text></g><g data-k=\"输出结构\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">输出结构</tspan></text></g><g data-k=\"去向\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">去向</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":45.0},{"t":"缺口五：怎么算好","n":"第五类缺口是验收标准，也是最常被跳过的一类。什么情况下这个功能算做完了？有哪些必须满足的条件？没有它，你无法判断 AI 的产出是否合格，只能靠感觉。补法是写出两到三条可判定的验收条件，比如「非法输入返回明确错误码」「列表为空时返回空数组不报错」。「怎么算好」要用能测的话写。「登录要快」不是标准，「输入正确密码后 2 秒内进入首页」才是。把形容词换成数字或可观察的行为，这一栏才算填完。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"可判定条件\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">可判定条件</tspan></text></g><g data-k=\"边界情况\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">边界情况</tspan></text></g><g data-k=\"必须符合项\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">必须符合项</tspan></text></g></svg>","d":47.8},{"t":"用清单查一句真实需求","n":"现在拿一句你工作里真实出现过的模糊需求，用这五类缺口逐条检查。你会发现大多数一句话需求至少缺三类。把补出来的信息写成一个结构化描述，再交给 AI，产出质量会有质变。这一步花五分钟，省的是后面五小时的返工。拿一句你今天真实收到的需求来填这张表。填完你会发现，原来以为「说清楚了」的需求，往往缺了两三栏——这正是它做不出来的原因。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"谁用\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">谁用</tspan></text></g><g data-k=\"场景\"><g><circle cx=\"42\" cy=\"71.2\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"75.7\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"75.7\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">场景</tspan></text></g><g data-k=\"输入\"><g><circle cx=\"42\" cy=\"100.4\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"104.9\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"104.9\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">输入</tspan></text></g><g data-k=\"输出\"><g><circle cx=\"42\" cy=\"129.6\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"134.1\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"134.1\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">输出</tspan></text></g><g data-k=\"算好\"><g><circle cx=\"42\" cy=\"158.8\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"163.3\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">⑤</text></g><text x=\"70.0\" y=\"163.3\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">算好</tspan></text></g></svg>","d":40.2},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「一句话需求为什么做不出来」。拿到一句话需求先查五类缺口，再决定动手把今天最有价值的三点写进产出物「需求缺口 checklist」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：拿一句真实模糊需求，标出它的五类缺口。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":37.7}],"quiz":[{"q":"「做个用户反馈功能」最主要的问题是什么？","opts":["技术栈没说","缺少用户、场景、输入、输出、算好这些关键约束","字数太少","没指定 AI 工具"],"a":1,"why":"这正是需求五问要补齐的核心缺口，与工具或技术栈无关。"},{"q":"需求缺口越多，AI 的产出会怎样？","opts":["越准确","偏差越大，返工越多","完全不变","自动补全"],"a":1,"why":"AI 只能基于你给的上下文生成，缺口越大它只能靠猜，偏差和返工随之增加。"}],"template":"【需求缺口 checklist】\n需求原句：____\n谁用____ 场景____ 输入____ 输出____ 算好____","brief":"【本单元要点】需求越模糊，AI 产出的偏差越大\n【为什么重要】「做个用户反馈功能」这句话，十个人能做出十个样子\n【看完做一件事】拿一句真实模糊需求，标出它的五类缺口。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M1U2","tier":"core","step":"understand","title":"需求五问：把一句话补全","video":{"dur":"5.3min","script":["五问是最小的补全工具","问一：谁用","问二：在什么场景"]},"ppt":{"method":"五问是最小的需求补全工具","case":"把「导出订单」用五问补全后，AI 一次给出了正确的实现","demo":"需求五问卡"},"objective":"用五问补全一句模糊需求","transfer":"拿到需求能用五问模板在五分钟内补全","deliverable":{"type":"document","name":"需求五问卡","rubric":["谁用","何场景","输入","输出","算好"],"acceptance":"一页卡：五问各写一句具体答案，合成一段可直接交给 AI 的结构化需求。"},"task":"用五问模板补全一句你真实的模糊需求。","rubric":["五问答案具体","合成为结构化描述","可被直接用作 AI 指令"],"vslides":[{"t":"五问是最小的补全工具","n":"上一节我们看了模糊需求的五类缺口，这一节给一个工具把它们一次补齐，叫需求五问：谁用、在什么场景、输入什么、输出什么、怎么算好。五问的价值在于它足够小，五分钟就能填完，又足够全，覆盖了 AI 生成代码最需要的信息。五问是一个最小的补全工具，小到你随时能在纸上画出来。它不追求把需求写成正式文档，只保证你在开工前把关键假设都摊开——假设摊开了，AI 才不会替你做错误的默认。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"谁用\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">谁用</tspan></text></g><g data-k=\"场景\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">场景</tspan></text></g><g data-k=\"输入\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">输入</tspan></text></g><g data-k=\"输出\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">输出</tspan></text></g><g data-k=\"算好\"><rect x=\"145.3\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">算好</tspan></text></g></svg>","d":44.1},{"t":"问一：谁用","n":"第一问是使用者的身份和权限。写清楚「谁」的时候，要具体到角色，而不是「用户」。比如「后台运营人员，只有查看权限，不能修改订单」。身份决定交互，权限决定代码里要不要做鉴权分支。这一问答得越具体，后面越少返工。问「谁用」时，别接受「用户」这种答案。追问到具体的岗位、他在这个功能里的权限、他对系统熟不熟。答案越具体，后面写验收标准时越容易判断「做得对不对」。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"具体角色\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">具体角色</tspan></text></g><g data-k=\"权限范围\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">权限范围</tspan></text></g><g data-k=\"熟练程度\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">熟练程度</tspan></text></g></svg>","d":44.6},{"t":"问二：在什么场景","n":"第二问是场景。写清楚这个需求在什么情况下被触发、用得多不多、在什么设备上。场景会影响技术选型和交互设计。比如「运营每天上午在电脑端批量导出上月订单，单次数据量约一万条」。有了这句，AI 就知道要考虑分页或异步处理。场景要问到触发条件和使用频率。一个每天用几十次的功能，和一个一年用一次的审批功能，对性能和交互的要求完全不同。频率决定了值不值得为它做优化。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"触发时机\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">触发时机</tspan></text></g><g data-k=\"使用频率\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">使用频率</tspan></text></g><g data-k=\"设备\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">设备</tspan></text></g><g data-k=\"数据规模\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">数据规模</tspan></text></g></svg>","d":45.0},{"t":"问三与问四：输入与输出","n":"第三问输入，第四问输出。输入写清字段、格式、来源；输出写清形态、字段、去向。这两问要尽量用结构化的语言，甚至直接写出字段清单。比如输入是「订单 ID 数组，每个 ID 为 18 位字符串」，输出是「订单对象数组，含金额、状态、创建时间」。输入和输出写成字段清单：字段名、类型、是否必填、从哪来、到哪去。这张清单本身就是后面写规格和测试用例的直接素材，花五分钟写它，能省后面一轮返工。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"输入字段\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">输入字段</tspan></text></g><g data-k=\"输入格式\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">输入格式</tspan></text></g><g data-k=\"输出字段\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">输出字段</tspan></text></g><g data-k=\"输出去向\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">输出去向</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":55.2},{"t":"问五：怎么算好","n":"第五问验收。写出两到三条可判定的完成条件，包括至少一条边界情况。比如「输入为空数组时返回空列表且不报错」「导出的 CSV 能被 Excel 正常打开」「单次一万条在三十秒内完成」。这些条件既是给 AI 的约束，也是你验收的尺子。「怎么算好」这一问要落到可判定。把「体验好」「响应快」这类词划掉，换成具体数字或具体行为。如果写不出来，说明你对这个需求的理解还没到位，需要回去再问一轮。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"可判定\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">可判定</tspan></text></g><g data-k=\"含边界\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">含边界</tspan></text></g><g data-k=\"可量化\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">可量化</tspan></text></g></svg>","d":45.2},{"t":"合成一段结构化需求","n":"把五问的答案合成一段话，就是可以直接交给 AI 的结构化需求。对比一下你原来的那一句，你会发现信息密度完全不同。以后每次接到模糊需求，先花五分钟填五问，再动手。这是从「让 AI 猜」到「让 AI 做对」的关键转变。把五问的答案串成一段话，就是给 AI 的结构化需求。这段话可以直接作为后面所有指令的开头——背景清楚了，后面的拆解、生成、测试才不会各说各的。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"填五问\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">填五问</tspan></text></g><g data-k=\"合成一段\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">合成一段</tspan></text></g><g data-k=\"交给 AI\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">交给 AI</tspan></text></g></svg>","d":41.9},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「需求五问：把一句话补全」。拿到需求能用五问模板在五分钟内补全把今天最有价值的三点写进产出物「需求五问卡」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：用五问模板补全一句你真实的模糊需求。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":43.6}],"quiz":[{"q":"需求五问不包括下列哪一项？","opts":["谁用","何场景","输入输出","用什么 AI 工具"],"a":3,"why":"五问是用户、场景、输入、输出、算好，工具选择不是需求要素。"},{"q":"五问补全后的需求应该是什么形态？","opts":["更长的一句话","可直接交给 AI 的结构化描述","一段代码","一张截图"],"a":1,"why":"补全的目标是形成结构清晰、AI 可直接执行的需求描述。"}],"template":"【需求五问卡】\n谁用：____\n场景：____\n输入：____\n输出：____\n算好：____\n合成需求：____","brief":"【本单元要点】五问是最小的需求补全工具\n【为什么重要】把「导出订单」用五问补全后，AI 一次给出了正确的实现\n【看完做一件事】用五问模板补全一句你真实的模糊需求。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M1U3","tier":"core","step":"understand","title":"让 AI 把口语拆成任务清单","video":{"dur":"4.4min","script":["从需求到任务","写拆解指令","检查任务粒度"]},"ppt":{"method":"拆任务的指令越结构化，清单越能直接用","case":"把「做个反馈功能」拆成六条可验收任务","demo":"任务拆解指令模板"},"objective":"生成可执行、可验收的任务列表","transfer":"能把口语化需求转成 AI 可执行任务清单","deliverable":{"type":"document","name":"任务拆解清单","rubric":["任务条目","依赖关系","验收口径"],"acceptance":"一份任务清单：至少五条任务，每条含产出与验收口径。"},"task":"用指令模板把一句口语需求拆成任务清单。","rubric":["任务条目具体","每条有验收口径","标注了依赖关系"],"vslides":[{"t":"从需求到任务","n":"补全后的需求还是一段描述，AI 不能直接按段落写代码。你需要把它拆成任务清单：一条任务对应一个可独立验证的小产出。拆任务的目的是让每一步都能被单独检查，出了问题能定位到具体任务，而不是面对一大坨代码无从下手。从需求到任务，中间隔着的不是翻译，是判断。同样一句需求，不同人拆出来的任务粒度完全不同。这一节练的就是把「一大块」切成「一条条能单独验收」的能力。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"需求描述\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">需求描述</tspan></text></g><g data-k=\"任务清单\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">任务清单</tspan></text></g><g data-k=\"逐条实现\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">逐条实现</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":44.1},{"t":"写拆解指令","n":"拆解指令要明确四件事：输入是什么、拆成什么粒度、每条任务要包含哪些字段、输出成什么格式。比如「把下面的需求拆成任务清单，每条包含任务描述、产出物、验收口径、依赖任务，用表格输出」。这样的指令一次就能得到结构化清单。拆解指令里四个明确缺一不可：输入明确、粒度明确、字段明确、格式明确。你越是把输出的样子描述清楚，AI 给你的清单越接近能直接用；含糊的指令只会得到含糊的列表。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"输入明确\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">输入明确</tspan></text></g><g data-k=\"粒度明确\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">粒度明确</tspan></text></g><g data-k=\"字段明确\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">字段明确</tspan></text></g><g data-k=\"格式明确\"><g><circle cx=\"30\" cy=\"154\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 154 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"158.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">格式明确</tspan></text></g></svg>","d":45.2},{"t":"检查任务粒度","n":"拆完先看粒度。太粗的任务比如「实现反馈功能」等于没拆；太细的任务比如「定义一个字符串变量」又太碎。合适的粒度是一个任务能在半小时内完成、能被独立验证。判断标准：你能不能为这条任务单独写一条验收条件？能，粒度就对了。判断粒度的标准是「能不能独立验收」。一条任务如果必须依赖另一条才能验证，就拆得不够；如果一条任务小到只是改一个变量名，就拆得太碎。合适粒度是一条任务有明确产出、能单独跑通。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"太粗\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">太粗</tspan></text></g><g data-k=\"合适\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">合适</tspan></text></g><g data-k=\"太碎\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">太碎</tspan></text></g><g data-k=\"可独立验收\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">可独立验收</tspan></text></g></svg>","d":47.4},{"t":"为每条任务写验收口径","n":"清单里最关键的一列是验收口径。它必须是可判定的，比如「提交后页面显示成功提示，反馈内容可在后台列表查到」。避免写「功能正常」「体验良好」这类无法判定的词。验收口径既指导 AI 生成，也指导你自己检查。写验收口径时，把「功能正常」这类话全部划掉。改成「提交后列表能查到这条记录，且状态显示为待处理」——能观察、能验证、有明确结果，这才叫验收口径。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"功能正常（模糊）\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">功能正常（模糊）</tspan></text></g><g data-k=\"提交后列表可查（可判定）\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"94.8\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">提交后列表可查（可判定</tspan><tspan x=\"295.0\" dy=\"15.600000000000001\">）</tspan></text></g></svg>","d":45.2},{"t":"标注依赖关系","n":"最后标注任务之间的依赖。哪些任务必须先做，哪些可以并行。比如数据结构定义要先于接口实现，接口实现要先于前端对接。有了依赖关系，你就能安排顺序，也能在任务卡住时知道会影响到谁。依赖关系要标出来，因为它决定执行顺序。定义数据结构在前，实现接口在中，前端对接在后，联调验证收尾。标清依赖，你才知道哪条任务卡住了会影响全局。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"定义结构\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">定义结构</tspan></text></g><g data-k=\"实现接口\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">实现接口</tspan></text></g><g data-k=\"前端对接\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">前端对接</tspan></text></g><g data-k=\"联调验证\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">联调验证</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":38.2},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「让 AI 把口语拆成任务清单」。能把口语化需求转成 AI 可执行任务清单把今天最有价值的三点写进产出物「任务拆解清单」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：用指令模板把一句口语需求拆成任务清单。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":43.8}],"quiz":[{"q":"让 AI 拆任务时，最有效的指令是？","opts":["帮我拆一下","把这个功能拆成任务，每条写清产出、验收口径和依赖","随便列几条","按你想法做"],"a":1,"why":"明确要求产出、验收口径和依赖，才能得到可直接执行的任务清单。"},{"q":"好的任务清单，每条任务应该包含？","opts":["只有一个动词","产出和验收口径","开发者的心情","AI 的名字"],"a":1,"why":"可验收是任务可执行的前提，每条都要写清产出与判定标准。"}],"template":"【任务拆解清单】\n任务｜产出｜验收口径｜依赖\n1 ____\n2 ____\n3 ____","brief":"【本单元要点】拆任务的指令越结构化，清单越能直接用\n【为什么重要】把「做个反馈功能」拆成六条可验收任务\n【看完做一件事】用指令模板把一句口语需求拆成任务清单。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M1U4","tier":"core","step":"understand","title":"验收标准怎么写","video":{"dur":"4.2min","script":["为什么验收这么重要","标准一：可判定","标准二：覆盖边界"]},"ppt":{"method":"验收标准是把「差不多」变成「过或不过」","case":"用「功能基本可用」验收，导致返工三次","demo":"验收标准表"},"objective":"写出可测、可判的验收口径","transfer":"能为任务写出可判定的验收标准","deliverable":{"type":"document","name":"验收标准表","rubric":["可判定","有边界","可量化"],"acceptance":"一张表：三条验收标准，每条都能明确判断通过或不通过。"},"task":"为一个真实任务写三条可判定验收标准。","rubric":["每条可明确判定","至少一条涉及边界","避免模糊形容词"],"vslides":[{"t":"为什么验收这么重要","n":"AI 生成完，你怎么判断它做对了？如果标准是「功能基本可用」，那每个人都能说可用，也能说不可用，争吵就开始了。验收标准的作用是把主观感受变成客观判定：过就是过，不过就是不过。它既是给 AI 的约束，也是给你自己的尺子。验收标准之所以重要，是因为它是你和 AI 之间唯一的「完成定义」。没有它，AI 会说「已完成」，你会觉得「还差得远」，双方对同一个词理解不同，返工就从这个缝隙里长出来。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"功能基本可用\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">功能基本可用</tspan></text></g><g data-k=\"输入空值返回空数组不报错\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"94.8\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">输入空值返回空数组不报</tspan><tspan x=\"295.0\" dy=\"15.600000000000001\">错</tspan></text></g></svg>","d":45.5},{"t":"标准一：可判定","n":"第一条原则是每条标准都必须能用一句话判定真假。「返回状态码 200」「列表按金额降序排列」「错误信息包含字段名」都是可判定的；「体验好」「代码优雅」不是。写验收标准时问自己：能不能设计一个测试来直接验证它？能，就合格。可判定的标准是能设计出一个测试来验证它。问自己一句：「这条标准，我能写出一个用例来证明它成立吗？」写不出来，说明它还是感觉而不是标准，需要继续改。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"能设计测试验证\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">能设计测试验证</tspan></text></g><g data-k=\"真假明确\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">真假明确</tspan></text></g><g data-k=\"无主观形容词\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">无主观形容词</tspan></text></g></svg>","d":42.2},{"t":"标准二：覆盖边界","n":"第二条原则是要覆盖边界情况。正常路径人人都测，问题常出在边界：空输入、超长输入、非法格式、并发、重复提交。一条好的验收标准里至少有一条针对边界。比如「重复提交同一订单号只创建一条记录」。这一条往往最能体现你是否真的想过这个需求。边界常常是 bug 的藏身处。空输入、超长输入、非法格式、重复提交——这四类至少各写一条。用户不会按你的理想路径使用功能，验收标准要提前替他们把意外情况想一遍。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"空输入\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">空输入</tspan></text></g><g data-k=\"超长输入\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">超长输入</tspan></text></g><g data-k=\"非法格式\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">非法格式</tspan></text></g><g data-k=\"重复提交\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">重复提交</tspan></text></g></svg>","d":51.3},{"t":"标准三：可量化","n":"第三条原则是尽量量化。能用数字说清的就不用形容词：不说「响应快」，说「单次请求在 500 毫秒内返回」；不说「支持大量数据」，说「单次处理一万条记录不超时」。量化让验收没有争议，也让 AI 在生成时有了明确目标。可量化就是把形容词换成数字。「响应要快」改成「在正常数据量下 2 秒内返回」，「不能出错」改成「异常输入返回明确错误码且不崩溃」。有数字，才谈得上验收。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"找形容词\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">找形容词</tspan></text></g><g data-k=\"换成数字\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">换成数字</tspan></text></g><g data-k=\"写进标准\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">写进标准</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":40.2},{"t":"写一页验收标准表","n":"为一个你手头的真实任务写三条验收标准：一条正常路径、一条边界、一条性能或格式要求。每条都用可判定的语言。写完读一遍，如果哪条你觉得「大概算通过吧」，就说明还不够具体，继续改到非黑即白。把这张表写完，你会发现它同时是后面测试用例的素材。验收标准和测试用例本来就是一件事的两种写法——前者写给评审看，后者写给机器跑。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"正常路径\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">正常路径</tspan></text></g><g data-k=\"边界情况\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">边界情况</tspan></text></g><g data-k=\"量化要求\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">量化要求</tspan></text></g></svg>","d":38.2},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「验收标准怎么写」。能为任务写出可判定的验收标准把今天最有价值的三点写进产出物「验收标准表」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：为一个真实任务写三条可判定验收标准。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":37.2}],"quiz":[{"q":"下面哪条是合格的验收标准？","opts":["功能要好用","界面美观","输入为空时返回空数组且不抛异常","代码尽量优雅"],"a":2,"why":"这条标准可明确判定通过与否；其余都是主观形容词。"},{"q":"验收标准最重要的特性是？","opts":["写得长","可判定","用词专业","包含背景故事"],"a":1,"why":"验收标准的价值在于能明确判断通过或不通过，而不是长度或文采。"}],"template":"【验收标准表】\n任务：____\n1 ____\n2 ____\n3 ____","brief":"【本单元要点】验收标准是把「差不多」变成「过或不过」\n【为什么重要】用「功能基本可用」验收，导致返工三次\n【看完做一件事】为一个真实任务写三条可判定验收标准。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M1U5","tier":"core","step":"understand","title":"边界条件与异常场景清单","video":{"dur":"4.3min","script":["正常之外的世界","第一类：正常用例","第二类：边界用例"]},"ppt":{"method":"AI 最容易漏的，是正常路径之外的世界","case":"AI 生成的函数在正常输入下正确，遇到空值直接崩溃","demo":"三类用例清单"},"objective":"列出正常、边界、异常三类用例","transfer":"写需求时能主动列出三类用例","deliverable":{"type":"document","name":"边界用例清单","rubric":["正常","边界","异常"],"acceptance":"一张清单：三类用例各至少三条，含输入与预期结果。"},"task":"为一个功能列出正常、边界、异常三类用例。","rubric":["三类齐全","每类有输入与预期","含至少一个真实异常"],"vslides":[{"t":"正常之外的世界","n":"AI 生成代码时，默认按最常见的路径写：输入合法、数据齐全、调用成功。但真实世界不是这样。用户会传空值，接口会超时，数据会有重复。这一节教你把正常路径之外的世界补齐，写进用例清单，作为 AI 生成和验收的输入。大多数人写用例只写正常路径，因为那是自己想象中的使用方式。真实用户会空着提交、会重复点击、会输入超长字符串。这一节就是把「正常之外的世界」系统性地列出来。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"正常\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">正常</tspan></text></g><g data-k=\"边界\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">边界</tspan></text></g><g data-k=\"异常\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">异常</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":45.5},{"t":"第一类：正常用例","n":"正常用例是功能按预期工作的情况。比如输入合法订单号返回订单详情，输入正确的用户名密码登录成功。这部分 AI 通常能覆盖得不错，你要做的是列出代表性的输入和预期输出，作为基线。别把所有正常情况都列上，挑能代表不同分支的几条即可。正常用例要选有代表性的输入，不是随便挑一个能跑通的。挑那些覆盖主要分支的输入——比如一个正常订单、一个带优惠的订单、一个跨部门的订单。代表性比数量重要。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"代表性输入\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">代表性输入</tspan></text></g><g data-k=\"预期输出\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">预期输出</tspan></text></g><g data-k=\"覆盖主要分支\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">覆盖主要分支</tspan></text></g></svg>","d":44.3},{"t":"第二类：边界用例","n":"边界用例是合法但极端的情况：空数组、最大值、最小值、超长字符串、刚好的临界点。比如「输入空数组返回空列表」「金额为 0 时不报错」「字符串长度正好等于上限时通过」。边界用例是 AI 最容易漏的，也是上线后最常出问题的地方，必须人肉补齐。边界用例的重点是临界值。数量限制是 100，就测 99、100、101；长度限制是 20，就测 19、20、21。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"空值\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">空值</tspan></text></g><g data-k=\"临界值\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">临界值</tspan></text></g><g data-k=\"超长\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">超长</tspan></text></g><g data-k=\"重复\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">重复</tspan></text></g></svg>","d":45.6},{"t":"第三类：异常用例","n":"异常用例是错误和意外：输入格式非法、依赖服务超时、网络中断、权限不足、并发冲突。对每一类异常，要写清期望系统怎么反应：返回明确错误码、给用户友好提示、记录日志、不泄漏内部信息。异常场景的处理最能体现代码是否专业。异常用例要确认系统在异常时「返回明确错误且不泄漏内部信息」。崩溃是最容易发现的坏结果，更隐蔽的是把数据库结构或堆栈打给用户看——那既是质量问题也是安全问题。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"异常时崩溃或泄漏\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">异常时崩溃或泄漏</tspan></text></g><g data-k=\"返回明确错误且不泄漏\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">返回明确错误且不泄漏</tspan></text></g></svg>","d":45.2},{"t":"把清单交给 AI","n":"三类用例齐了，把它们作为上下文交给 AI：请根据这些用例生成实现，并为每条用例生成对应测试。你会发现产出质量明显提升，因为 AI 终于知道了那些它原本猜不到的边界和异常。这张清单也成了你的验收表，一举两得。把清单交给 AI 时，附上接口定义和验收标准，让它同时生成实现和测试。它生成的用例可能不全面，你拿这张清单核对一遍，缺什么补什么，比从零写快得多。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"列用例\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">列用例</tspan></text></g><g data-k=\"交给 AI\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">交给 AI</tspan></text></g><g data-k=\"生成实现与测试\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">生成实现与测试</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":39.1},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「边界条件与异常场景清单」。写需求时能主动列出三类用例把今天最有价值的三点写进产出物「边界用例清单」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：为一个功能列出正常、边界、异常三类用例。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":39.8}],"quiz":[{"q":"下面哪一项属于边界用例？","opts":["输入合法订单号","输入空数组","服务器断电","用户正常提交"],"a":1,"why":"空数组是典型的边界输入；断电属于异常场景，合法输入是正常路径。"},{"q":"为什么要专门列异常场景？","opts":["让文档更长","AI 生成常只覆盖正常路径，异常需人补齐","为了好看","AI 会自动处理"],"a":1,"why":"AI 通常按最常见的路径生成，异常场景需要你显式补充，否则上线后容易崩。"}],"template":"【边界用例清单】\n正常：1____ 2____\n边界：1____ 2____\n异常：1____ 2____\n预期处理：____","brief":"【本单元要点】AI 最容易漏的，是正常路径之外的世界\n【为什么重要】AI 生成的函数在正常输入下正确，遇到空值直接崩溃\n【看完做一件事】为一个功能列出正常、边界、异常三类用例。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M1U6","tier":"core","step":"understand","title":"生成前的自检三问","video":{"dur":"4.3min","script":["为什么要自检","第一问：信息齐不齐","第二问：边界清不清"]},"ppt":{"method":"生成前多问三句，生成后少改三轮","case":"需求没自检就让 AI 生成，结果整版返工","demo":"开工自检卡"},"objective":"动手前判断需求是否够清楚","transfer":"按三问自检，不把模糊需求交给 AI","deliverable":{"type":"document","name":"开工自检卡","rubric":["信息齐吗","边界清吗","能验收吗"],"acceptance":"一页卡：三个自检问题各写一句判断结论，未通过则先补需求。"},"task":"用三问自检一个你即将交给 AI 的任务。","rubric":["三问齐全","有明确通过/不通过结论","未通过项有补法"],"vslides":[{"t":"为什么要自检","n":"很多返工不是 AI 的问题，而是需求没想清楚就交出去了。生成前的三问自检，就是一道闸门：信息齐不齐、边界清不清、能不能验收。三问都过了再动手，能省掉大量来回。这三问只需要一分钟，是这一章里性价比最高的习惯。自检三问是一个止损动作。需求不够清楚就开工，后面每一轮都会为这个模糊买单：生成出来不对、改了还是不对、最后发现是需求本身没说清。开工前花两分钟，省的是后面两小时。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"信息齐\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">信息齐</tspan></text></g><g data-k=\"边界清\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">边界清</tspan></text></g><g data-k=\"能验收\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">能验收</tspan></text></g><g data-k=\"再生成\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">再生成</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":44.3},{"t":"第一问：信息齐不齐","n":"对照需求五问，检查用户、场景、输入、输出、算好这五项是不是都有答案。缺任何一项，AI 都得靠猜。不要觉得「大概能猜到」就够了——你脑子里有上下文，AI 没有。把缺的那项补上，哪怕只写一句话，产出都会更准。第一问信息齐不齐，逐项对照五问卡：用户、场景、输入、输出、算好。缺哪一项就补哪一项，不要用「应该是这样吧」给自己填坑。假设可以验证，但不能假装它是事实。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"用户\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用户</tspan></text></g><g data-k=\"场景\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">场景</tspan></text></g><g data-k=\"输入输出\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">输入输出</tspan></text></g><g data-k=\"算好\"><g><circle cx=\"30\" cy=\"154\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 154 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"158.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">算好</tspan></text></g></svg>","d":42.9},{"t":"第二问：边界清不清","n":"检查你有没有想过边界和异常：空值怎么办、超长怎么办、重复提交怎么办、依赖失败怎么办。如果这些你都没想过，AI 更不会替你想。花两分钟列一页边界用例清单，或者直接把关键边界写进指令。这一问决定你的代码上线后会不会崩。第二问边界清不清，重点看空值、超长、重复、失败这四种情况有没有说法。需求文档里没写的边界，AI 会用自己的默认习惯填——而它的习惯未必符合你的业务。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"空值\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">空值</tspan></text></g><g data-k=\"超长\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">超长</tspan></text></g><g data-k=\"重复\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">重复</tspan></text></g><g data-k=\"失败\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">失败</tspan></text></g></svg>","d":44.3},{"t":"第三问：能不能验收","n":"检查你有没有可判定的验收标准。如果你描述完需求后，自己都说不清怎么算做完，那 AI 也做不到。写出至少两三条可判定的条件，最好包含一条边界。验收标准不只是检查工具，更是帮 AI 明确目标。第三问能不能验收，判断标准是「先写验收标准，再动手」。如果你的标准是「做完再看」，那等于没有标准，做完之后你会很难说清到底算不算完成。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"做完再说（模糊）\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">做完再说（模糊）</tspan></text></g><g data-k=\"先写验收标准\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">先写验收标准</tspan></text></g></svg>","d":40.1},{"t":"三问不过就先补","n":"把三问写成一张自检卡，每次生成前过一遍。任何一问不通过，就先回去补需求，不要将就。你会慢慢发现，真正花时间的不是写代码，而是想清楚要写什么。想清楚了，AI 一次就能给对；想不清楚，改十遍还是不对。三问不过就先补，这不是拖延而是纪律。把缺的几项补齐再开工，你会发现后面的生成一次就能用，返工次数明显下降——这是这一节最值得带走的工作习惯。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"信息齐\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">信息齐</tspan></text></g><g data-k=\"边界清\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">边界清</tspan></text></g><g data-k=\"能验收\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">能验收</tspan></text></g><g data-k=\"动手\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">动手</tspan></text></g></svg>","d":41.2},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「生成前的自检三问」。按三问自检，不把模糊需求交给 AI把今天最有价值的三点写进产出物「开工自检卡」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：用三问自检一个你即将交给 AI 的任务。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":42.4}],"quiz":[{"q":"自检三问不包括？","opts":["信息齐不齐","边界清不清","能不能验收","工具流不流行"],"a":3,"why":"自检关注需求本身的质量，与工具流行度无关。"},{"q":"自检发现需求不够清楚时，正确做法是？","opts":["先补需求再生成","直接生成再说","换个 AI 工具","降低验收标准"],"a":0,"why":"补齐需求再生成，比生成后返工更省时。"}],"template":"【开工自检卡】\n信息齐吗：____\n边界清吗：____\n能验收吗：____\n结论：通过 / 先补需求","brief":"【本单元要点】生成前多问三句，生成后少改三轮\n【为什么重要】需求没自检就让 AI 生成，结果整版返工\n【看完做一件事】用三问自检一个你即将交给 AI 的任务。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M1U7","tier":"core","step":"spar","title":"陪练：产品经理追问你的需求卡","video":{"dur":"4.4min","script":["陪练说明","第一轮：为什么","第二轮：边界"]},"ppt":{"method":"陪练不是让你过关，是替你在上线前把坑踩一遍","case":"产品经理追问「这个字段为什么要收集」，你答不上来","demo":"追问复盘记录"},"objective":"顶住三轮追问并补全缺口","transfer":"面对产品经理的追问能用依据补全需求","deliverable":{"type":"document","name":"追问复盘记录","rubric":["被问倒的点","补上的依据","下次准备"],"acceptance":"一页复盘：写下被问倒的问题、后来补的依据、下次要提前准备什么。"},"task":"完成三轮追问，补全需求卡并写复盘。","rubric":["至少记录一个被问倒的点","补上有依据","有下次改进"],"vslides":[{"t":"陪练说明","n":"接下来进入陪练。你的对手是产品经理，他的职责不是让你过，而是找出你需求卡里的漏洞。他会围绕三个方向追问：这个字段为什么要收集、边界情况怎么处理、怎么知道做完了。你不需要回答得完美，但每个回答都要有依据，不能只说「我觉得」。这一轮陪练里，AI 扮产品经理，专门追问你需求卡里的漏洞。它的目的不是为难你，而是模拟真实评审会上最常出现的三个问题：为什么做、边界怎么办、怎么算完成。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"为什么做\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">为什么做</tspan></text></g><g data-k=\"边界怎么办\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">边界怎么办</tspan></text></g><g data-k=\"怎么验收\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">怎么验收</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":43.2},{"t":"第一轮：为什么","n":"第一轮追问为什么。产品经理会挑一个字段或一个功能问你：为什么要它，谁提的，不做的后果是什么。如果你答不上来，说明这个需求里有「别人都这么做」的成分。应对方法是回到业务目标：这个字段支撑了哪个决策、影响了哪个指标。第一轮追问「为什么」，你要说出需求是谁提的、支撑什么决策、不做的后果是什么。答不上来，说明你还没理解这个需求的业务价值，后面所有设计都可能跑偏。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"谁提的\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">谁提的</tspan></text></g><g data-k=\"支撑什么决策\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">支撑什么决策</tspan></text></g><g data-k=\"不做什么后果\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">不做什么后果</tspan></text></g></svg>","d":40.5},{"t":"第二轮：边界","n":"第二轮追问边界。他会问：空值怎么办、超 long 怎么办、重复提交怎么办、并发时谁优先。这些问题你在自检卡里应该想过。回答时给出具体的处理规则，而不是「应该不会吧」。如果确实没想过，大方承认并现场补一条规则，这比硬撑强得多。第二轮追问边界，空值、超长、重复、并发四类至少答出两类的处理办法。答不上来不要硬编，诚实说「这里还没想清楚，我回去补」，然后真的补进需求卡。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"空值\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">空值</tspan></text></g><g data-k=\"超长\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">超长</tspan></text></g><g data-k=\"重复\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">重复</tspan></text></g><g data-k=\"并发\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">并发</tspan></text></g></svg>","d":47.1},{"t":"第三轮：怎么验收","n":"第三轮追问验收。他会问：怎么知道这件事做完了、谁来判断、用什么数据判断。你要拿出可判定的验收标准，最好带数字。比如「上线后一周内，反馈提交成功率不低于 99%，可由后台报表验证」。有数据、有来源、有判定人，这一轮就稳了。第三轮追问验收，「感觉做完了」不算答案。要给出可观察的结果，比如「一周内成功率不低于 99%，报表可查」。数字和验证方式缺一不可。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"感觉做完了\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">感觉做完了</tspan></text></g><g data-k=\"一周内成功率≥99%，报表验证\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"94.8\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">一周内成功率≥99%，报</tspan><tspan x=\"295.0\" dy=\"15.600000000000001\">表验证</tspan></text></g></svg>","d":46.6},{"t":"通过标准与复盘","n":"通过的标准是：三轮追问中至少两轮给出有依据的回答，且没有任何一轮答非所问。结束后写一份复盘：哪个问题把你问倒了、你后来补了什么依据、下次要提前准备什么。被问倒不是失败，而是发现了一个本来会在上线后爆炸的坑。通过标准是两轮有依据、一轮被问倒也诚实记录。被问倒不是失败，反而是这轮陪练最有价值的产出——它精确告诉你需求卡还缺哪一块，回去补上就是进步。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"两轮有依据\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">两轮有依据</tspan></text></g><g data-k=\"记录被问倒\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">记录被问倒</tspan></text></g><g data-k=\"补全依据\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">补全依据</tspan></text></g></svg>","d":44.5},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「陪练：产品经理追问你的需求卡」。面对产品经理的追问能用依据补全需求把今天最有价值的三点写进产出物「追问复盘记录」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：完成三轮追问，补全需求卡并写复盘。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":44.6}],"quiz":[{"q":"陪练里被问倒时，正确的做法是？","opts":["坚持己见","承认不确定并回去补依据","换个话题","降低需求范围"],"a":1,"why":"承认不确定、补充依据，正是陪练要训练的能力；硬撑只会把问题带到上线后。"},{"q":"陪练追问的主要价值是？","opts":["让你背下话术","在上线前暴露需求缺口","证明 AI 比人强","减少代码量"],"a":1,"why":"陪练通过角色追问，把需求漏洞提前暴露出来，避免上线后返工。"}],"template":"【追问复盘记录】\n被问倒的问题：____\n后来补的依据：____\n下次提前准备：____","brief":"【本单元要点】陪练不是让你过关，是替你在上线前把坑踩一遍\n【为什么重要】产品经理追问「这个字段为什么要收集」，你答不上来\n【看完做一件事】完成三轮追问，补全需求卡并写复盘。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M1U8","tier":"core","step":"todo","title":"M1 实战：拆一个真实需求","video":{"dur":"4.2min","script":["实战任务说明","第一步：补全五问","第二步：拆任务清单"]},"ppt":{"method":"把一章的方法用在一个真实需求上，才算学会","case":"学员用自己项目里的真实需求完成了完整拆解","demo":"完整演示从一句模糊需求到需求包的拆解过程"},"objective":"交付完整的需求到任务到验收包","transfer":"独立完成一次从模糊需求到可执行任务包的转换","deliverable":{"type":"document","name":"需求包","rubric":["五问卡","任务清单","验收标准"],"acceptance":"一份完整需求包：含结构化需求、任务清单、验收标准三部分。"},"task":"从你真实工作里选一个需求，拆成完整需求包","rubric":["三部分齐全","需求来自真实工作","验收标准可判定"],"vslides":[{"t":"实战任务说明","n":"这一节是 M1 的实战。请从你真实的工作里选一个还没做的需求，最好是那种「一句话说不清」的。你要用这一章学的方法，把它拆成一份完整的需求包：先补全五问，再拆成任务清单，最后写出可判定的验收标准。整个过程不用写代码，但要能交给 AI 直接开工。这一节的实战是把前面七节串起来：选一个真实需求，补五问、拆任务、写验收，最后合成一个完整需求包。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"选真实需求\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"76.4\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">选真实需</tspan><tspan x=\"58.2\" dy=\"16.900000000000002\">求</tspan></text></g><g data-k=\"补五问\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">补五问</tspan></text></g><g data-k=\"拆任务\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">拆任务</tspan></text></g><g data-k=\"写验收\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">写验收</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":41.0},{"t":"第一步：补全五问","n":"先写结构化需求。谁用、什么场景、输入什么、输出什么、怎么算好，五问各写一句具体答案，然后合成一段描述。记住具体优于笼统：写「后台运营每天导出上月订单约一万条」比写「用户要导出功能」有用得多。这一步的质量决定后面所有步骤。补五问时答案要具体。「用户是运营」不够，要写到「负责活动配置的运营，只有查看和编辑自己活动的权限」。具体程度决定后面拆解的质量。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"五问齐全\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">五问齐全</tspan></text></g><g data-k=\"答案具体\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">答案具体</tspan></text></g><g data-k=\"合成描述\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">合成描述</tspan></text></g></svg>","d":44.2},{"t":"第二步：拆任务清单","n":"把结构化需求交给 AI，用拆解指令生成任务清单。每条任务要有产出物、验收口径和依赖关系。拆完自己检查粒度：每条能不能独立验证、能不能在半小时内完成。太粗的再拆，太细的合并。最后按依赖排好顺序。拆任务清单时，每条都要有产出物和验收口径，并标出依赖关系。你会发现有些任务看着独立，其实卡在另一条的产出上——提前发现这个，能避免执行时卡住。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"产出物\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">产出物</tspan></text></g><g data-k=\"验收口径\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">验收口径</tspan></text></g><g data-k=\"依赖关系\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">依赖关系</tspan></text></g><g data-k=\"粒度合适\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">粒度合适</tspan></text></g></svg>","d":42.6},{"t":"第三步：写验收标准","n":"为整个需求包写三到五条验收标准，覆盖正常路径、边界情况和性能或格式要求。每条都用可判定的语言，避免「好用」「美观」这类词。写完后自己扮演验收人，逐条判断能不能明确说通过或不通过。写验收标准时，把「功能基本可用」换成可判定的句子。比如「空数组输入时返回空列表，不抛异常」。一条具体标准，胜过十句模糊描述。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"功能基本可用\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">功能基本可用</tspan></text></g><g data-k=\"空数组返回空列表不报错\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">空数组返回空列表不报错</tspan></text></g></svg>","d":38.9},{"t":"交付与自检","n":"把三部分合成一份需求包，用自检三问过一遍：信息齐不齐、边界清不清、能不能验收。都通过就交付。这份需求包可以直接作为下一个模块的输入，也可以发给同事或主管评审。它本身就是这一章最有价值的产出。交付前用三问自检：信息齐不齐、边界清不清、能不能验收。三问都过了，这个需求包就可以直接作为后面生成任务的输入——它本身就是这一章最值钱的产出物。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"合包\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">合包</tspan></text></g><g data-k=\"三问自检\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">三问自检</tspan></text></g><g data-k=\"交付\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">交付</tspan></text></g></svg>","d":41.7},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「M1 实战：拆一个真实需求」。独立完成一次从模糊需求到可执行任务包的转换把今天最有价值的三点写进产出物「需求包」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：从你真实工作里选一个需求，拆成完整需求包做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":41.7}],"quiz":[{"q":"M1 实战要交付的最终产物是？","opts":["一段代码","完整需求包：需求+任务+验收","一张截图","一份会议纪要"],"a":1,"why":"M1 聚焦需求拆解，交付物是完整的需求包而不是代码。"},{"q":"验收标准在需求包里的作用是？","opts":["凑字数","作为 AI 生成和学员验收的共同尺子","替代任务清单","给主管看的装饰"],"a":1,"why":"验收标准既约束 AI 生成，也用于检查产出是否合格，是共同的判定依据。"}],"template":"【M1 需求包】\n一、结构化需求：____\n二、任务清单：____\n三、验收标准：____\n自检结论：____","brief":"【本单元要点】把一章的方法用在一个真实需求上，才算学会\n【为什么重要】学员用自己项目里的真实需求完成了完整拆解\n【看完做一件事】从你真实工作里选一个需求，拆成完整需求包\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"}]},{"id":"M2","title":"M2 上下文工程：让 AI 读懂你的代码库","dims":["prompt","tools"],"units":[{"id":"M2U1","tier":"core","step":"understand","title":"上下文不是越多越好","video":{"dur":"4.1min","script":["一个反直觉的现象","原则一：相关","原则二：最小"]},"ppt":{"method":"喂得越多不等于答得越好，关键是喂对","case":"把整个代码库贴给 AI，反而得到了更泛泛的回答","demo":"上下文取舍原则卡"},"objective":"说明最小必要上下文原则","transfer":"给 AI 喂上下文前先做取舍","deliverable":{"type":"document","name":"上下文取舍原则卡","rubric":["相关","最小","结构化"],"acceptance":"一页卡：三条取舍原则各写一句判断方法，附一个反例。"},"task":"写一份上下文取舍原则卡。","rubric":["三条原则清晰","有判断方法","有反例"],"vslides":[{"t":"一个反直觉的现象","n":"很多人以为给 AI 的信息越多越好，于是把整个文件甚至整个代码库贴进去。结果往往适得其反：回答变得更泛泛，因为它要从海量文本里找重点；成本也上去了。这一节讲最小必要上下文原则：只给与当前任务相关、AI 确实需要的信息。上下文不是越多越好，这个现象反直觉但很真实：把整库代码贴进去，AI 反而给出更泛泛的答案，还更贵。原因很简单——无关信息稀释了关键信号，它分不清哪段代码和当前任务有关。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"整库粘贴：泛泛而贵\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">整库粘贴：泛泛而贵</tspan></text></g><g data-k=\"最小必要：准而省\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">最小必要：准而省</tspan></text></g></svg>","d":46.2},{"t":"原则一：相关","n":"第一原则是相关性。只给和当前任务直接相关的文件与信息。判断方法是问自己：如果删掉这份材料，AI 还能正确完成任务吗？能，就删掉。比如改一个函数，通常只需要这个函数、它的调用方和相关类型定义，不需要整个项目。「相关」的判断标准很硬：删掉这段，生成结果会不会变？不会变，就别贴。按函数或模块为单位选，不要按文件整块贴——一个文件里真正相关的往往只有一两个函数。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"与任务直接相关\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">与任务直接相关</tspan></text></g><g data-k=\"删掉会影响结果才留\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">删掉会影响结果才留</tspan></text></g><g data-k=\"按函数为单位选\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">按函数为单位选</tspan></text></g></svg>","d":45.0},{"t":"原则二：最小","n":"第二原则是最小。相关还不够，要在相关的里面挑最少。能用一个函数说清的，不要贴整个文件；能用接口定义说清的，不要贴实现细节。最小不只是省钱，更重要的是减少干扰，让 AI 聚焦在真正要改的地方。「最小」是一个逐级收缩的过程：整库→整文件→相关函数→最小片段。每收缩一级，问一次「还能再删吗」。删到不能再删，就是你要投喂的量。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"整库\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">整库</tspan></text></g><g data-k=\"整文件\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">整文件</tspan></text></g><g data-k=\"相关函数\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">相关函数</tspan></text></g><g data-k=\"最小片段\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">最小片段</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":40.3},{"t":"原则三：结构化","n":"第三原则是结构化。给上下文时要有组织：先说任务目标，再说关键文件，再说约束和验收。不要一股脑粘贴代码。结构化的上下文让 AI 分清哪些是任务、哪些是参考、哪些是硬约束，产出更可控。「结构化」是把选出来的片段整理成固定格式：任务目标、关键文件、约束、验收标准。同样是这些材料，无序堆放和分区呈现，AI 的理解质量差别很大。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"任务目标\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">任务目标</tspan></text></g><g data-k=\"关键文件\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">关键文件</tspan></text></g><g data-k=\"约束\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">约束</tspan></text></g><g data-k=\"验收标准\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">验收标准</tspan></text></g></svg>","d":39.8},{"t":"写一张取舍卡","n":"把三条原则写成一张卡：相关、最小、结构化，各配一句判断方法和一个反例。以后每次给 AI 喂上下文前扫一眼，养成取舍习惯。你会很快发现，喂得准比喂得多重要得多。写下这张取舍卡，下次准备投喂前先扫一眼。它会把「我觉得都挺重要」的直觉，换成「这段删掉不影响结果」的判断——这个转变是上下文工程的核心。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"相关\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">相关</tspan></text></g><g data-k=\"最小\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">最小</tspan></text></g><g data-k=\"结构化\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">结构化</tspan></text></g><g data-k=\"再喂\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">再喂</tspan></text></g></svg>","d":36.3},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「上下文不是越多越好」。给 AI 喂上下文前先做取舍把今天最有价值的三点写进产出物「上下文取舍原则卡」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：写一份上下文取舍原则卡。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":38.4}],"quiz":[{"q":"关于上下文，正确的说法是？","opts":["越多越好","只给与任务相关的最小必要信息","把所有文件都贴进去","完全不用给"],"a":1,"why":"最小必要上下文能提升准确性、降低成本与污染风险。"},{"q":"上下文过多可能导致？","opts":["回答更准确","关键信息被淹没、成本上升","自动过滤无关内容","完全没有影响"],"a":1,"why":"无关信息会稀释关键上下文，还会增加 token 成本和会话污染。"}],"template":"【上下文取舍卡】\n相关：判断____ 反例____\n最小：判断____ 反例____\n结构化：判断____","brief":"【本单元要点】喂得越多不等于答得越好，关键是喂对\n【为什么重要】把整个代码库贴给 AI，反而得到了更泛泛的回答\n【看完做一件事】写一份上下文取舍原则卡。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M2U2","tier":"core","step":"understand","title":"给 AI 喂代码：选文件、定顺序、标重点","video":{"dur":"4.4min","script":["投喂不是粘贴","动作一：选文件","动作二：定顺序"]},"ppt":{"method":"投喂的质量决定生成的质量","case":"同一任务，挑对三个文件一次成功，乱贴十个文件反复返工","demo":"上下文投喂清单"},"objective":"为一任务挑对最少必要文件","transfer":"能为一个具体任务准备投喂清单","deliverable":{"type":"document","name":"上下文投喂清单","rubric":["目标文件","依赖文件","重点标注"],"acceptance":"一页清单：列出要投喂的文件及顺序，标出每个文件需要重点看的部分。"},"task":"为一个真实任务写出投喂清单。","rubric":["文件数量最少","有明确顺序","标出重点"],"vslides":[{"t":"投喂不是粘贴","n":"给 AI 喂代码有个误区：把文件复制进去就完事。其实投喂是一个设计动作——你要决定给哪些文件、按什么顺序、重点标在哪。设计得好，AI 一次就懂；设计不好，贴再多它也抓不住重点。这一节把投喂拆成三个动作。投喂不是把代码复制进对话框。真正的动作是三步：选文件、定顺序、标重点。这三步做对了，同样的代码库能生成质量高得多的结果；做错了，再多材料也只是在制造噪音。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"选文件\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">选文件</tspan></text></g><g data-k=\"定顺序\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">定顺序</tspan></text></g><g data-k=\"标重点\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">标重点</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":46.6},{"t":"动作一：选文件","n":"从任务出发选文件。先选要改的目标文件，再选它直接依赖的文件（类型定义、接口、被调用函数），最后选会影响它的调用方。每层只选必要的。用「删掉它还能完成任务吗」逐个筛。经验上，一个函数级任务通常两到四个文件就够了。选文件时按「目标文件→直接依赖→调用方」逐层筛。先看要改的文件，再看它直接引用的定义，最后看谁在调用它。三层之外的内容，除非任务明确需要，否则先不贴。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"目标文件\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">目标文件</tspan></text></g><g data-k=\"直接依赖\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">直接依赖</tspan></text></g><g data-k=\"调用方\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">调用方</tspan></text></g><g data-k=\"逐层筛选\"><g><circle cx=\"30\" cy=\"154\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 154 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"158.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">逐层筛选</tspan></text></g></svg>","d":47.9},{"t":"动作二：定顺序","n":"顺序影响 AI 的理解。推荐的顺序是：先给任务目标，再给目标文件，再给依赖文件，最后给约束和验收。让 AI 先知道要做什么，再看要改的东西，再看支撑信息，最后记住边界。这个顺序和人读需求的方式一致，AI 理解得也更好。定顺序时把任务目标放在最前，然后是目标文件、依赖文件、约束和验收。AI 对开头的信息权重更高——把最重要的上下文放前面，比堆在末尾有效。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"任务目标\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">任务目标</tspan></text></g><g data-k=\"目标文件\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">目标文件</tspan></text></g><g data-k=\"依赖文件\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">依赖文件</tspan></text></g><g data-k=\"约束验收\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">约束验收</tspan></text></g></svg>","d":45.7},{"t":"动作三：标重点","n":"在投喂时显式标出重点。比如用注释说明「重点看这个函数的错误处理」「这段逻辑不要改」「遵循这里的命名风格」。重点标注能引导 AI 的注意力，避免它在无关代码上浪费精力。标注要简短具体，一两句话就够。标重点用一句话就够：「重点看错误处理部分，接口签名不要改」。有了这句，AI 知道哪些地方要细看、哪些地方不能动；没有这句，它会平均用力，该改的没改、不该动的动了。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"一大段无标注代码\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">一大段无标注代码</tspan></text></g><g data-k=\"重点看错误处理，勿改接口\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"94.8\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">重点看错误处理，勿改接</tspan><tspan x=\"295.0\" dy=\"15.600000000000001\">口</tspan></text></g></svg>","d":45.0},{"t":"写一页投喂清单","n":"为一个你真实的任务写投喂清单：列出要投喂的文件、顺序和每个文件的重点。写完数一数文件数量，如果超过五个，回头看看能不能再删。清单可以复用——同类任务用同一份清单，效率会越来越高。这一页投喂清单是给下次用的。把这次选了哪些文件、按什么顺序、标了什么重点记下来，同类任务再来时直接复用，既省时间又保证质量稳定。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"目标文件\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">目标文件</tspan></text></g><g data-k=\"依赖文件\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">依赖文件</tspan></text></g><g data-k=\"顺序\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">顺序</tspan></text></g><g data-k=\"重点\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">重点</tspan></text></g></svg>","d":38.2},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「给 AI 喂代码：选文件、定顺序、标重点」。能为一个具体任务准备投喂清单把今天最有价值的三点写进产出物「上下文投喂清单」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：为一个真实任务写出投喂清单。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":40.7}],"quiz":[{"q":"给 AI 喂代码时，正确的顺序是？","opts":["随便贴","按任务目标→关键文件→依赖→约束的顺序","先贴最远的","按文件名排序"],"a":1,"why":"结构化、有层次的投喂顺序帮助 AI 分清主次，提升产出质量。"},{"q":"判断某个文件要不要投喂，最实用的问题是？","opts":["文件大不大","删掉它 AI 还能完成任务吗","文件名好不好听","是不是最新的"],"a":1,"why":"「删掉是否影响结果」是判断必要性的有效方法。"}],"template":"【上下文投喂清单】\n任务：____\n1 文件____ 重点____\n2 文件____ 重点____\n3 文件____ 重点____","brief":"【本单元要点】投喂的质量决定生成的质量\n【为什么重要】同一任务，挑对三个文件一次成功，乱贴十个文件反复返工\n【看完做一件事】为一个真实任务写出投喂清单。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M2U3","tier":"core","step":"understand","title":"规则文件进阶：项目级约束","video":{"dur":"4.6min","script":["从个人到项目","第一类：技术栈约束","第二类：结构与命名约束"]},"ppt":{"method":"项目规则让 AI 产出在团队内保持一致","case":"同一个项目里，不同人用 AI 生成的风格完全不同","demo":"项目规则文件"},"objective":"写出团队可共用的项目规则文件","transfer":"能把个人规则升级为项目级约束","deliverable":{"type":"document","name":"项目规则文件","rubric":["技术栈","结构约定","禁止项","验收要求"],"acceptance":"一份项目规则文件：含技术栈、目录结构、禁止项、验收要求四类约束。"},"task":"写出一份项目级规则文件初版。","rubric":["四类约束齐全","写成可执行规则","可被团队共用"],"vslides":[{"t":"从个人到项目","n":"M0U7 你写了个人规则文件，解决的是「我怎么让 AI 懂我」。项目规则要解决的是「团队怎么让 AI 懂同一个项目」。当多个人用 AI 在同一个代码库上工作时，没有统一规则，产出风格就会四分五裂，最后合并成一锅粥。个人规则解决一个人的习惯，项目规则解决整个团队的一致性。同一份代码，不同人写出来的风格如果差很远，AI 就会在几种风格之间摇摆——项目规则就是给它一个明确答案。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"个人规则\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">个人规则</tspan></text></g><g data-k=\"项目规则\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">项目规则</tspan></text></g><g data-k=\"团队一致\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">团队一致</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":43.6},{"t":"第一类：技术栈约束","n":"写清项目用的语言、框架、版本和关键库。比如「后端 Python 3.11 + FastAPI，测试用 pytest，ORM 用 SQLAlchemy」。AI 知道了技术栈，就不会给你一个 Node.js 的方案。版本也要写，因为不同版本的 API 差别很大。技术栈约束要写到版本。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"语言\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">语言</tspan></text></g><g data-k=\"框架\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">框架</tspan></text></g><g data-k=\"版本\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">版本</tspan></text></g><g data-k=\"关键库\"><g><circle cx=\"30\" cy=\"154\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 154 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"158.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">关键库</tspan></text></g></svg>","d":26.2},{"t":"第二类：结构与命名约束","n":"写清目录结构、模块划分、命名规范、文件放置规则。比如「接口在 api/，业务逻辑在 services/，测试文件与源文件同目录，后缀 _test」。这部分直接决定项目能不能被新人快速接手，也让 AI 生成的文件放在正确的位置。结构与命名约束要写清「什么文件放哪里」。模块怎么划分、测试放哪个目录、配置文件叫什么名字。写清楚这些，AI 生成的代码才不会每次都落在你找不到的地方。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"目录结构\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">目录结构</tspan></text></g><g data-k=\"模块划分\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">模块划分</tspan></text></g><g data-k=\"命名规范\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">命名规范</tspan></text></g><g data-k=\"文件放置\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">文件放置</tspan></text></g></svg>","d":47.4},{"t":"第三类：禁止项","n":"明确列出禁止事项，这是规则里最有约束力的一部分。比如「禁止硬编码密钥和配置值」「禁止直接返回数据库异常给用户」「禁止引入未评估的新依赖」。禁止项用否定句写清楚，AI 在生成时会主动避开。禁止项里最重要的一条是「密钥一律走环境变量，不许硬编码」。把这条写进规则文件，等于给每次生成都加了一道自动闸门——它会在你没注意的时候替你拦住最危险的问题。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"禁止硬编码密钥\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">禁止硬编码密钥</tspan></text></g><g data-k=\"密钥一律走环境变量\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">密钥一律走环境变量</tspan></text></g></svg>","d":41.9},{"t":"第四类：验收要求","n":"写清产出必须满足的验收要求：必须附带测试、必须通过 lint、关键逻辑必须有注释说明依据。这把 M1 学的验收方法固化到项目层面。四类约束合起来，就是一份团队可共用的项目规则文件。验收要求这一节写的是「生成完必须满足什么」。比如「必须通过现有测试」「新增代码要有对应用例」。把它写进规则，AI 在生成时就会把这些当成任务的一部分。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"技术栈\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">技术栈</tspan></text></g><g data-k=\"结构命名\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">结构命名</tspan></text></g><g data-k=\"禁止项\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">禁止项</tspan></text></g><g data-k=\"验收要求\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">验收要求</tspan></text></g></svg>","d":40.3},{"t":"初版与迭代","n":"写完初版发给团队试用，收集「哪条做不到、哪条有歧义」的反馈，迭代一版。规则文件不是一次写死的宪法，而是随项目演进的活文档。把它放进代码库，让每个人和 AI 都能读到，才真正发挥作用。规则文件初版不用追求完美，写完就让团队试用一周，把大家反馈的「AI 又没遵守」逐条补进去。规则是长出来的，不是一次写对的——持续迭代比完美初版更有用。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"写初版\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">写初版</tspan></text></g><g data-k=\"团队试用\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">团队试用</tspan></text></g><g data-k=\"按反馈迭代\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"76.4\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">按反馈迭</tspan><tspan x=\"247.2\" dy=\"16.900000000000002\">代</tspan></text></g><g data-k=\"入代码库\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">入代码库</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":39.1},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「规则文件进阶：项目级约束」。能把个人规则升级为项目级约束把今天最有价值的三点写进产出物「项目规则文件」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：写出一份项目级规则文件初版。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":36.0}],"quiz":[{"q":"项目规则相对个人规则，新增的重点是？","opts":["更深奥的术语","团队一致性约束","更长的篇幅","更多的工具名"],"a":1,"why":"项目级规则的核心是让团队成员用 AI 时产出风格一致、可互相接手。"},{"q":"项目规则里最该写清的是？","opts":["开发者的个人喜好","技术栈、目录、禁止项、验收要求","公司的历史沿革","AI 工具的价格"],"a":1,"why":"这些是可执行、可判定的团队约束，真正影响 AI 产出的可用性。"}],"template":"【项目规则文件】\n技术栈：____\n结构命名：____\n禁止项：1____ 2____\n验收要求：____","brief":"【本单元要点】项目规则让 AI 产出在团队内保持一致\n【为什么重要】同一个项目里，不同人用 AI 生成的风格完全不同\n【看完做一件事】写出一份项目级规则文件初版。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M2U4","tier":"core","step":"understand","title":"会话管理：什么时候该开新会话","video":{"dur":"4.1min","script":["会话不是无限记忆","信号一：开始串味","信号二：重复交代"]},"ppt":{"method":"会话是有限记忆，不是永久档案","case":"在同一个会话里改了五个任务，AI 开始把前几个任务的要求混在一起","demo":"会话管理检查卡"},"objective":"判断污染会话并主动重置","transfer":"识别会话污染信号并知道何时重置","deliverable":{"type":"document","name":"会话管理检查卡","rubric":["污染信号","重置时机","上下文交接"],"acceptance":"一页卡：列出三种污染信号、重置的判断标准、重置时的上下文交接要点。"},"task":"写一份会话管理检查卡。","rubric":["污染信号具体","重置标准明确","有交接要点"],"vslides":[{"t":"会话不是无限记忆","n":"和 AI 的对话有一个窗口，装不下无限内容。当对话变长，早期的信息会被稀释甚至挤出。更麻烦的是，不同任务的要求会互相串味——你第三个任务里还在遵守第一个任务的约束。这就是会话污染。这一节教你识别信号、及时重置。会话不是无限记忆。聊得越久，早期的重要约定越容易被后面的对话稀释，AI 开始把不同任务的信息混在一起——这就是「串味」。识别串味信号，是保持输出质量的关键。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"长会话：信息稀释串味\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">长会话：信息稀释串味</tspan></text></g><g data-k=\"新会话：干净聚焦\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">新会话：干净聚焦</tspan></text></g></svg>","d":44.5},{"t":"信号一：开始串味","n":"第一个污染信号是 AI 把不同任务的要求混在一起。比如你让它按 A 规范写新模块，它却套用了上一个任务的 B 规范。这时不要继续纠正，纠正越多污染越深。正确做法是开新会话，干净地重新开始。信号一是开始串味：它把两个不同任务的要求混着答，或者你反复纠正同一个点它还是照旧。出现这种迹象，别再纠正了，纠正的成本已经超过重开一次。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"混淆不同任务\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">混淆不同任务</tspan></text></g><g data-k=\"反复纠正无效\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">反复纠正无效</tspan></text></g><g data-k=\"该开新会话\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">该开新会话</tspan></text></g></svg>","d":38.5},{"t":"信号二：重复交代","n":"第二个信号是你发现自己在一遍遍重复同样的背景和约束。这说明当前会话里的上下文已经不够清晰，AI 没有稳定地抓住重点。与其继续在同一会话里补，不如重置，把关键背景一次性写清楚。信号二是重复交代：你得把项目背景、约束再说一遍，甚至说第三遍。这说明当前会话已经装不下这些信息，继续硬撑只会让回答越来越偏。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"重复背景\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">重复背景</tspan></text></g><g data-k=\"重复约束\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">重复约束</tspan></text></g><g data-k=\"反复解释\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">反复解释</tspan></text></g><g data-k=\"重置\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">重置</tspan></text></g></svg>","d":38.4},{"t":"信号三：任务切换","n":"第三个信号是任务性质变了。比如从「写功能」转到「写测试」再到「做审查」，每个阶段的关注点不同。与其在一个会话里来回切换，不如每个阶段一个会话，开头用一段摘要交接上一阶段的结论。信号三是任务切换：从写功能切到写测试、再切到做审查。不同任务需要不同上下文，把它们塞进一个会话，等于让 AI 同时记住三套规则——它做不到。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"写功能\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">写功能</tspan></text></g><g data-k=\"写测试\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">写测试</tspan></text></g><g data-k=\"做审查\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">做审查</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":40.3},{"t":"重置时怎么交接","n":"开新会话不等于从零开始。正确的交接是写一段最小上下文摘要：项目是什么、当前任务是什么、已经定了哪些约定、要遵守哪些红线。把这段摘要放在新会话开头，既保持了连续性，又甩掉了旧会话的污染。重置会话时别直接从头开始，先写一段交接：项目背景、当前任务、已定约定、红线清单。把这四样贴进新会话，它立刻接上状态，比你在旧会话里反复纠正干净得多。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"项目背景\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">项目背景</tspan></text></g><g data-k=\"当前任务\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">当前任务</tspan></text></g><g data-k=\"已定约定\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">已定约定</tspan></text></g><g data-k=\"红线\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">红线</tspan></text></g></svg>","d":44.5},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「会话管理：什么时候该开新会话」。识别会话污染信号并知道何时重置把今天最有价值的三点写进产出物「会话管理检查卡」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：写一份会话管理检查卡。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":41.0}],"quiz":[{"q":"下面哪个是会话污染的信号？","opts":["AI 回答变快","AI 开始混淆之前任务的要求","代码变短","测试通过"],"a":1,"why":"混淆不同任务的要求是典型的会话污染，说明上下文相互干扰。"},{"q":"开新会话时，正确的做法是？","opts":["什么也不说重新开始","带上必要的上下文摘要再开始","把整个旧会话复制过去","换个工具"],"a":1,"why":"新会话需要带最小必要的上下文摘要，避免从零开始又避免污染。"}],"template":"【会话管理检查卡】\n污染信号：1____ 2____ 3____\n重置标准：____\n交接摘要要点：____","brief":"【本单元要点】会话是有限记忆，不是永久档案\n【为什么重要】在同一个会话里改了五个任务，AI 开始把前几个任务的要求混在一起\n【看完做一件事】写一份会话管理检查卡。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M2U5","tier":"core","step":"understand","title":"让 AI 先复述再动手","video":{"dur":"3.9min","script":["一个小动作，省一轮返工","复述什么","加一个确认问题"]},"ppt":{"method":"让 AI 先说它理解了什么，再让它做","case":"AI 复述后发现它把「按时间排序」理解成了「按金额排序」，及时纠正","demo":"复述确认模板"},"objective":"用复述确认理解一致再生成","transfer":"在生成前加一道复述确认工序","deliverable":{"type":"document","name":"复述确认模板","rubric":["任务复述","关键约束","确认提问"],"acceptance":"一份模板：让 AI 复述任务、列出关键约束、提出一个确认问题。"},"task":"写一份复述确认模板并试用一次。","rubric":["含任务复述","含关键约束","含确认提问"],"vslides":[{"t":"一个小动作，省一轮返工","n":"很多时候 AI 给出的东西不对，不是它能力不行，而是它理解错了你的需求。与其等它写完一大段再推翻，不如在动手前加一道工序：让它先复述它理解了什么。这一步只要十几秒，却能拦住大部分方向性错误。让 AI 先复述再做，是一个成本极低、收益极高的动作。多花一轮对话，换掉的是「它理解错了、你验收时才发现」的整轮返工——尤其在任务复杂、约束多的时候。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"给指令\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">给指令</tspan></text></g><g data-k=\"AI 复述\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">AI 复述</tspan></text></g><g data-k=\"确认\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">确认</tspan></text></g><g data-k=\"再生成\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">再生成</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":37.9},{"t":"复述什么","n":"让 AI 复述三件事：任务目标、它会产出什么、它理解的关键约束。这三件事如果对，方向就对了。特别要让它把约束逐条列出来，因为约束最容易在长指令里被忽略。复述要具体，不要满足于「我明白了」这种空话。复述要覆盖三样：任务目标、产出形态、关键约束。只让它复述目标不够，因为它可能在约束上理解错；三样都复述一遍，偏差基本能在这一轮暴露出来。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"任务目标\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">任务目标</tspan></text></g><g data-k=\"产出形态\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">产出形态</tspan></text></g><g data-k=\"关键约束\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">关键约束</tspan></text></g></svg>","d":42.0},{"t":"加一个确认问题","n":"更进一步，让 AI 针对最不确定的地方提一个确认问题。比如「这个排序是按创建时间还是更新时间」。它问出来，你回答，误解就消除了。这个设计很巧妙：把 AI 从被动执行者变成主动确认者，让它在不确定时先问，而不是先猜。再加一个确认问题效果更好：「有哪一点你不确定的，先问我」。这一句把主动权交给 AI，让它把模糊处说出来，而不是自己猜一个答案往下做。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"先猜后做（易错）\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">先猜后做（易错）</tspan></text></g><g data-k=\"先问后做（准确）\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">先问后做（准确）</tspan></text></g></svg>","d":40.5},{"t":"什么时候必须用","n":"三种情况一定要用复述确认：任务复杂、涉及多个约束、之前理解出现过偏差。简单任务比如「把这行改成驼峰」就不用。判断标准是：如果这个任务做错了返工代价大，就值得先复述。什么时候必须用？任务复杂、约束多、之前出过偏差、返工代价大的时候。反过来，一个简单的小改动就不用绕这一轮——纪律也要用在值得的地方。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"任务复杂\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">任务复杂</tspan></text></g><g data-k=\"多约束\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">多约束</tspan></text></g><g data-k=\"曾偏差\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">曾偏差</tspan></text></g><g data-k=\"返工代价大\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">返工代价大</tspan></text></g></svg>","d":36.8},{"t":"写一页模板","n":"把复述确认写成一段可复用的指令前缀：「在动手前，请先复述你对任务的理解，列出你将遵守的关键约束，并针对最不确定的一点向我提一个问题。等我确认后再开始。」存起来，下次复杂任务直接粘贴。把复述确认写成可复用模板，下次遇到复杂任务直接套。模板固定了，这个动作才不会被赶进度的时候跳过——而它恰恰是最不该跳的那一步。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"复述理解\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">复述理解</tspan></text></g><g data-k=\"列约束\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">列约束</tspan></text></g><g data-k=\"提问题\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">提问题</tspan></text></g><g data-k=\"等确认\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">等确认</tspan></text></g></svg>","d":37.0},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「让 AI 先复述再动手」。在生成前加一道复述确认工序把今天最有价值的三点写进产出物「复述确认模板」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：写一份复述确认模板并试用一次。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":38.2}],"quiz":[{"q":"让 AI 先复述的主要目的是？","opts":["让回答更长","在动手前发现理解偏差","节省 token","替代测试"],"a":1,"why":"复述能在生成前暴露理解偏差，避免整版返工。"},{"q":"复述确认里最有效的做法是？","opts":["让 AI 说「好的」","让 AI 列出关键约束并提出一个确认问题","让 AI 直接开始写","让 AI 猜用户意图"],"a":1,"why":"列约束和提确认问题能真正检验 AI 是否理解到位。"}],"template":"【复述确认模板】\n在动手前请：\n1 复述任务：____\n2 列出关键约束：____\n3 提出一个确认问题：____\n等我确认后再开始。","brief":"【本单元要点】让 AI 先说它理解了什么，再让它做\n【为什么重要】AI 复述后发现它把「按时间排序」理解成了「按金额排序」，及时纠正\n【看完做一件事】写一份复述确认模板并试用一次。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M2U6","tier":"core","step":"understand","title":"代码库地图：让 AI 快速定位模块","video":{"dur":"4.1min","script":["为什么需要地图","地图一：模块清单","地图二：关键入口"]},"ppt":{"method":"一张地图，让 AI 和人都能快速找到该改哪里","case":"新人靠代码库地图十分钟定位到要改的模块","demo":"代码库地图"},"objective":"生成一份可复用的代码库摘要","transfer":"能为项目生成并维护一份代码库地图","deliverable":{"type":"document","name":"代码库地图","rubric":["模块清单","职责说明","关键入口","依赖关系"],"acceptance":"一份代码库摘要：含主要模块、职责、关键入口和依赖关系。"},"task":"为你的项目生成一份代码库地图。","rubric":["覆盖主要模块","职责说明清晰","标出关键入口"],"vslides":[{"t":"为什么需要地图","n":"让 AI 改代码，它得先知道项目里有什么、每个模块负责什么、要去哪里找。如果没有地图，你只能每次现场描述，费时且容易漏。代码库地图就是一份压缩摘要：让 AI（和新人）在几十秒内建立项目全局认知。代码库地图是给 AI 的快速定位系统。没有它，AI 只能靠你每次临时贴几段代码猜全貌；有了它，它知道模块怎么分、入口在哪、依赖怎么走，生成的东西更容易落在正确位置。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"项目全貌\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">项目全貌</tspan></text></g><g data-k=\"模块职责\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">模块职责</tspan></text></g><g data-k=\"快速定位\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">快速定位</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":44.5},{"t":"地图一：模块清单","n":"第一部分列出主要模块或目录，每个一句话说明职责。比如「api/ 对外接口层，只做参数校验和转发」「services/ 业务逻辑」「models/ 数据模型」。职责要写清楚「负责什么」和「不负责什么」，边界越清越好。地图一是模块清单，每个模块写两件事：负责什么、不负责什么。「不负责什么」这一栏经常被漏掉，但它恰恰能防止 AI 把别的模块的逻辑塞进来。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"模块名\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">模块名</tspan></text></g><g data-k=\"负责什么\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">负责什么</tspan></text></g><g data-k=\"不负责什么\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">不负责什么</tspan></text></g></svg>","d":39.8},{"t":"地图二：关键入口","n":"第二部分标出关键入口：主函数、路由注册、主要类的构造入口、配置文件位置。这些是理解项目启动和调用链的起点。 AI 知道了入口，就能顺着调用关系找到要改的地方，而不是在整个代码库里瞎找。地图二是关键入口：主函数、路由注册、配置入口、调用链起点。这些是理解一个系统的把手，AI 知道从哪进，就能顺着调用关系找到要改的地方。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"主函数\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">主函数</tspan></text></g><g data-k=\"路由注册\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">路由注册</tspan></text></g><g data-k=\"配置入口\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">配置入口</tspan></text></g><g data-k=\"调用链起点\"><g><circle cx=\"30\" cy=\"154\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 154 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"158.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">调用链起点</tspan></text></g></svg>","d":38.0},{"t":"地图三：依赖关系","n":"第三部分说明模块间的依赖：谁调用谁、数据怎么流、哪些是公共基础模块。这部分最能帮助判断改动影响范围——改一个基础模块会影响哪些上层模块。依赖关系可以用简单的列表或箭头图表示。地图三是依赖关系：哪些是基础模块、哪些是业务模块、哪些是接口层。标清依赖，AI 才知道改底层会影响谁，哪类改动需要同步改调用方。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"基础模块\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">基础模块</tspan></text></g><g data-k=\"业务模块\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">业务模块</tspan></text></g><g data-k=\"接口层\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">接口层</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":39.6},{"t":"生成与维护","n":"让 AI 生成地图初版：给它项目结构（目录树和关键文件），请它按模块清单、关键入口、依赖关系输出摘要。生成后人工校准，然后在每次项目结构大改时更新。地图不需要事无巨细，抓住主干就够。地图先让 AI 根据目录树生成初稿，再由人工校准——它容易把模块职责猜错。校准完放进代码库，每次结构有变动就更新一次，这份地图会越用越准。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"给目录树\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">给目录树</tspan></text></g><g data-k=\"AI 生成\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">AI 生成</tspan></text></g><g data-k=\"人工校准\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">人工校准</tspan></text></g><g data-k=\"定期更新\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">定期更新</tspan></text></g></svg>","d":42.0},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「代码库地图：让 AI 快速定位模块」。能为项目生成并维护一份代码库地图把今天最有价值的三点写进产出物「代码库地图」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：为你的项目生成一份代码库地图。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":40.5}],"quiz":[{"q":"代码库地图的主要作用是？","opts":["替代源代码","帮助 AI 和人快速定位该改哪里","隐藏实现细节","增加文件数量"],"a":1,"why":"地图提供项目结构和职责概览，帮助快速定位目标模块。"},{"q":"好的代码库地图应该包含？","opts":["只有文件名","模块职责、关键入口、依赖关系","开发者的评价","所有代码全文"],"a":1,"why":"这些结构化信息才能让读者理解项目布局与模块关联。"}],"template":"【代码库地图】\n模块｜职责｜不负责\n关键入口：____\n依赖关系：____","brief":"【本单元要点】一张地图，让 AI 和人都能快速找到该改哪里\n【为什么重要】新人靠代码库地图十分钟定位到要改的模块\n【看完做一件事】为你的项目生成一份代码库地图。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M2U7","tier":"core","step":"spar","title":"陪练：AI 扮新人，你讲清项目结构","video":{"dur":"3.7min","script":["陪练说明","第一分钟：讲全貌","第二分钟：讲职责与边界"]},"ppt":{"method":"讲得清，才是真的懂","case":"新人听完你的讲解后仍能问倒你，说明你还没讲透","demo":"讲解复盘记录"},"objective":"用三分钟讲清一个陌生项目","transfer":"能在三分钟内把项目结构讲给新人听","deliverable":{"type":"document","name":"讲解复盘记录","rubric":["讲清的点","被问倒的点","补讲的话"],"acceptance":"一页复盘：写下讲得清楚的部分、被问倒的部分、补讲时是怎么说清的。"},"task":"完成三分钟讲解，写复盘。","rubric":["有被问倒的点","补讲有具体说法"," Reflect 出改进"],"vslides":[{"t":"陪练说明","n":"这一轮陪练，AI 扮成刚入职的新人，你要在三分钟内把项目结构讲给他听。这不是背文档，而是检验你是否真的理解了项目。新人会问很基础的问题：这个模块是干什么的、为什么要这样分、我改一处会影响哪里。能答上来，说明你掌握了；答不上来，说明你只是熟悉局部。这一轮陪练里，AI 扮新人，要你在三分钟内讲清一个项目。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"讲模块\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">讲模块</tspan></text></g><g data-k=\"讲职责\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">讲职责</tspan></text></g><g data-k=\"讲依赖\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">讲依赖</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":34.7},{"t":"第一分钟：讲全貌","n":"先用一分钟讲项目是做什么的、解决什么问题、有哪些主要模块。用比喻更好，比如「这个项目像一个订单处理流水线，api 是收件口，services 是分拣中心，models 是货架」。全貌讲清，新人才能挂住后面的细节。第一分钟讲全貌：项目解决什么问题、有哪些主要模块、能不能用一个比喻让人快速建立印象。比喻不是花架子，它能帮对方先有个框架，后面的细节才挂得住。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"项目目标\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">项目目标</tspan></text></g><g data-k=\"主要模块\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">主要模块</tspan></text></g><g data-k=\"一个比喻\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">一个比喻</tspan></text></g></svg>","d":38.9},{"t":"第二分钟：讲职责与边界","n":"第二分钟逐个模块讲职责和边界。重点讲「为什么这么分」而不是「里面有什么代码」。比如「把校验放在 api 层，是为了让业务逻辑不用关心格式问题」。讲清设计意图，新人才能做对改动。第二分钟讲职责与边界：每个模块负责什么、当初为什么这么设计、它不管什么。讲清「不负责什么」，新人就不会把功能放错模块——这是最实用的一分钟。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"模块职责\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">模块职责</tspan></text></g><g data-k=\"设计意图\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">设计意图</tspan></text></g><g data-k=\"边界\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">边界</tspan></text></g></svg>","d":35.2},{"t":"第三分钟：讲改动影响","n":"最后一分钟讲依赖关系和改动影响：改基础模块会影响谁、新功能应该加在哪、哪里是历史包袱要小心。这部分最能体现你的经验。讲完如果新人还在追问，说明你留了钩子；如果他点头了，说明你讲透了。第三分钟讲改动影响：别说「代码在这个文件」，要说「改这里要同步改这两个调用方，还要跑那组用例」。能讲清影响范围，才说明你真的懂这个项目的结构。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"只讲代码在哪\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">只讲代码在哪</tspan></text></g><g data-k=\"讲清改哪里、影响谁\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">讲清改哪里、影响谁</tspan></text></g></svg>","d":42.9},{"t":"复盘与改进","n":"结束后写复盘：哪些部分你讲得清楚、哪里被问倒、补讲时是怎么说清的。被问倒的地方往往是你理解最薄弱的地方，回去补上。这个练习的价值不在于表演，而在于发现你「以为懂了其实没懂」的部分。复盘时记下三样：讲清楚的点、被问倒的点、下次要补的说法。被问倒的地方就是你对项目理解最薄的地方，回去补上，下次讲得更稳。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"讲清的点\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">讲清的点</tspan></text></g><g data-k=\"被问倒\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">被问倒</tspan></text></g><g data-k=\"补讲说法\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">补讲说法</tspan></text></g></svg>","d":35.2},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「陪练：AI 扮新人，你讲清项目结构」。能在三分钟内把项目结构讲给新人听把今天最有价值的三点写进产出物「讲解复盘记录」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：完成三分钟讲解，写复盘。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":38.1}],"quiz":[{"q":"陪练中 AI 扮新人的主要目的是？","opts":["考验你的记忆力","检验你能否把项目讲清楚","让 AI 学习代码","减少代码量"],"a":1,"why":"能把项目结构讲给新人听，说明你真正理解了它，而不是只记得局部。"},{"q":"被新人问倒时，最好的反应是？","opts":["回避问题","诚实承认并用更基础的方式补讲","责怪问题太难","结束讲解"],"a":1,"why":"用更基础的方式补讲，既检验理解也锻炼表达能力。"}],"template":"【讲解复盘记录】\n讲清的点：____\n被问倒的点：____\n补讲时怎么说清：____","brief":"【本单元要点】讲得清，才是真的懂\n【为什么重要】新人听完你的讲解后仍能问倒你，说明你还没讲透\n【看完做一件事】完成三分钟讲解，写复盘。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M2U8","tier":"core","step":"todo","title":"M2 实战：用规则文件生成正确模块","video":{"dur":"4.2min","script":["实战任务说明","第一步：准备上下文","第二步：复述确认"]},"ppt":{"method":"把上下文功夫用在一次真实的生成上","case":"学员用规则文件和投喂清单，一次生成了符合规范的模块","demo":"完整演示从准备上下文到生成验收的全过程"},"objective":"让 AI 一次生成符合规范的代码","transfer":"综合上下文方法，一次生成符合项目规范的代码","deliverable":{"type":"document","name":"生成结果对照表","rubric":["规则文件","投喂清单","复述确认","生成结果"],"acceptance":"一份对照表：记录你用了哪些上下文手段、生成结果是否符合规范。"},"task":"从你的项目选一个小模块，用全套方法一次生成","rubric":["用到了规则与投喂","生成结果符合规范","有对照结论"],"vslides":[{"t":"实战任务说明","n":"这一节把 M2 的方法串起来用一次。选一个你项目里真实的小模块任务，目标是：让 AI 一次生成符合项目规范的代码，不需要大幅返工。你会用到规则文件、投喂清单、复述确认和代码库地图。做完填一张对照表，看看哪些手段真正起了作用。这一节的实战把上下文工程的五步串成一条线：备规则、备地图、投喂、复述、生成。用你真实的项目跑一遍，比看十页理论更能建立手感。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"备规则\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">备规则</tspan></text></g><g data-k=\"备地图\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">备地图</tspan></text></g><g data-k=\"投喂\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">投喂</tspan></text></g><g data-k=\"复述\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">复述</tspan></text></g><g data-k=\"生成\"><rect x=\"145.3\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">生成</tspan></text></g></svg>","d":42.2},{"t":"第一步：准备上下文","n":"把项目规则文件准备好，确保技术栈、命名、禁止项、验收要求都在里面。生成一份代码库地图摘要。为当前任务写投喂清单，挑出最少必要文件，标出重点。这三样准备好了，生成质量就有了基础。准备上下文时，规则文件、代码库地图、投喂清单三样缺一不可。规则定标准，地图给全貌，清单定这次具体贴什么——三者合起来，AI 才有足够且不过量的信息。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"规则文件\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">规则文件</tspan></text></g><g data-k=\"代码库地图\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">代码库地图</tspan></text></g><g data-k=\"投喂清单\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">投喂清单</tspan></text></g></svg>","d":41.9},{"t":"第二步：复述确认","n":"在正式生成前，让 AI 复述任务理解、列出关键约束、提出一个确认问题。等它确认无误再让它动手。这一步能拦住方向性错误，避免你得到一个漂亮但完全不对的东西。复述确认这一步别跳。先让它讲一遍它理解的任务和约束，你确认无误再让它生成。跳这一步省下的是三十秒，赔上的可能是整轮返工。把它变成固定动作，复杂任务才不会因为赶进度被跳过。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"直接生成（易偏）\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">直接生成（易偏）</tspan></text></g><g data-k=\"复述确认后再生成\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">复述确认后再生成</tspan></text></g></svg>","d":40.8},{"t":"第三步：生成与验收","n":"让 AI 生成代码，然后按验收标准逐条检查：正确性、安全性、可维护性，加上你写的具体验收条件。运行测试，确认真的能跑。如果发现偏差，记录是哪里没交代清楚，这比直接改代码更有价值。生成后做三问验收，跑测试，并把 AI 的实际偏差记录下来。偏差记录是下一步优化的素材：它告诉你规则文件还缺哪条、地图哪里写得不准。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"生成\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">生成</tspan></text></g><g data-k=\"三问验收\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">三问验收</tspan></text></g><g data-k=\"跑测试\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">跑测试</tspan></text></g><g data-k=\"记录偏差\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">记录偏差</tspan></text></g></svg>","d":44.5},{"t":"填对照表","n":"把这次实践写成对照表：你用了哪些上下文手段、每个手段带来了什么、生成结果是否符合规范、哪里还需要改进。这张表是你 M2 方法的复盘，也是下次类似任务的模板。上下文工程是练出来的，不是看会的。填对照表时，四栏都要写实：用了什么手段、它起了什么作用、结果如何、下次怎么改。这张表是这一章最有价值的产出，因为它记录的是你自己验证过的方法。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"手段\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">手段</tspan></text></g><g data-k=\"作用\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">作用</tspan></text></g><g data-k=\"结果\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">结果</tspan></text></g><g data-k=\"改进\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">改进</tspan></text></g></svg>","d":38.9},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「M2 实战：用规则文件生成正确模块」。综合上下文方法，一次生成符合项目规范的代码把今天最有价值的三点写进产出物「生成结果对照表」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：从你的项目选一个小模块，用全套方法一次生成做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":44.3}],"quiz":[{"q":"M2 实战的核心目标是？","opts":["写出最长的指令","一次生成符合项目规范的代码","用完所有 AI 工具","复制最多文件"],"a":1,"why":"实战检验的是上下文工程的综合效果：能否让 AI 一次生成符合规范的代码。"},{"q":"下列哪一项最能提升生成质量？","opts":["模糊的需求","规则文件+最小必要上下文+复述确认","尽可能多的文件","跳过验收"],"a":1,"why":"这三者是 M2 的核心方法，组合使用效果最好。"}],"template":"【生成结果对照表】\n手段｜作用｜效果\n规则文件____\n投喂清单____\n复述确认____\n结论：____","brief":"【本单元要点】把上下文功夫用在一次真实的生成上\n【为什么重要】学员用规则文件和投喂清单，一次生成了符合规范的模块\n【看完做一件事】从你的项目选一个小模块，用全套方法一次生成\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"}]},{"id":"M3","title":"M3 生成与补全：从片段到模块","dims":["prompt","dev"],"units":[{"id":"M3U1","tier":"core","step":"understand","title":"生成代码的三种粒度","video":{"dur":"5.0min","script":["为什么粒度重要","粒度一：片段","粒度二：函数"]},"ppt":{"method":"粒度选错，是生成失败最常见的原因","case":"让 AI 一次生成整个模块，结果处处对不上","demo":"粒度选择表"},"objective":"区分片段、函数、模块三种生成粒度","transfer":"按任务范围选对生成粒度，不一次要太多","deliverable":{"type":"document","name":"粒度选择表","rubric":["片段","函数","模块"],"acceptance":"一张表：三类粒度各写一个适用场景、一个不适用场景、一条指令要点。"},"task":"从片段、函数、模块三类任务中各举一个你的真实例子。","rubric":["三类齐全","场景与粒度匹配","有指令要点"],"vslides":[{"t":"为什么粒度重要","n":"很多人让 AI 生成失败，不是工具不行，而是一次要得太多。你让它「写个用户系统」，它给你一个看似完整但处处需要改的框架。问题不在质量，而在粒度。这一节把生成粒度分成片段、函数、模块三级，教你按任务范围选对级别。粒度选错是生成质量不稳定的头号原因。让 AI 一次生成一个系统，它只能给你一个空壳；让它改一个变量名，又浪费了一次交互。选对粒度，等于给这次任务划好了合适的边界。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"片段\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">片段</tspan></text></g><g data-k=\"函数\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">函数</tspan></text></g><g data-k=\"模块\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">模块</tspan></text></g><g data-k=\"系统\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">系统</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":44.4},{"t":"粒度一：片段","n":"片段是最小的生成单位：一段正则、一个配置、一段 SQL、一个错误提示文案。它适合随时补全，验证成本极低。片段级任务不需要太多上下文，一句话说清用途就行。日常编码中，片段级使用频率最高，也最不容易出错。片段级适合那些独立、短小、容易验证的东西：正则表达式、配置片段、SQL 语句、提示文案。它们不牵扯上下文，生成完一眼能看出对错，最适合拿来建立第一次成功体验。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"正则\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">正则</tspan></text></g><g data-k=\"配置\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">配置</tspan></text></g><g data-k=\"SQL\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">SQL</tspan></text></g><g data-k=\"文案\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">文案</tspan></text></g></svg>","d":42.2},{"t":"粒度二：函数","n":"函数级是主力粒度。一个函数有明确输入输出、能被单独测试，是 AI 生成的最佳单位。给它规格化指令：输入是什么、输出是什么、边界怎么处理、遵守什么规范。函数级生成质量通常很高，因为边界清楚、验证容易。函数级是最好用的粒度：输入明确、输出明确、边界可测。给 AI 一个函数规格，它生成的东西你能用一个测试文件完整验证——可验证性正是和模块级相比最大的优势。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"输入明确\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">输入明确</tspan></text></g><g data-k=\"输出明确\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">输出明确</tspan></text></g><g data-k=\"边界可测\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">边界可测</tspan></text></g><g data-k=\"有验收条件\"><g><circle cx=\"30\" cy=\"154\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 154 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"158.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">有验收条件</tspan></text></g></svg>","d":44.7},{"t":"粒度三：模块","n":"模块级是多个函数的组合，比如一个完整的接口处理流程。它适合在你已经熟悉模式、且能通过测试整体验证时使用。模块级生成要提供更完整的上下文：规则文件、相关类型、调用关系。风险比函数级高，因为问题更难定位。模块级适合上下文已经准备充分的情况。你有规则文件、有代码库地图、有明确的接口约定时，让它一次生成一个模块才靠谱；缺了这些，模块级生成只会把错误放大。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"函数级：边界清楚易验证\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">函数级：边界清楚易验证</tspan></text></g><g data-k=\"模块级：上下文全但难定位\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"94.8\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">模块级：上下文全但难定</tspan><tspan x=\"295.0\" dy=\"15.600000000000001\">位</tspan></text></g></svg>","d":44.5},{"t":"从小到大的策略","n":"安全的策略是从小到大：先让 AI 生成函数并验证通过，再让它把几个函数组合成模块，最后才让它处理跨模块流程。每一步都建立在上一步验证过的基础上。这样即使出问题，你也能定位到具体是哪一层出的。从小到大的策略不是保守，是风险管理。先用片段和函数验证 AI 在这个项目里的表现，确认它遵守你的规范，再逐步放大到模块。信任是靠一次次小范围验证建立起来的。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"片段\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">片段</tspan></text></g><g data-k=\"函数\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">函数</tspan></text></g><g data-k=\"模块\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">模块</tspan></text></g><g data-k=\"系统\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">系统</tspan></text></g></svg>","d":43.3},{"t":"写一页粒度选择表","n":"为你工作中的三类典型任务各选一个合适的粒度，写清适用场景、不适用场景和指令要点。以后接到任务先查表定粒度，再动手写指令。选对粒度，生成成功率会明显提升。写一页粒度选择表，把「什么情况用哪一级」记下来。下次拿到任务先查表再决定粒度，能省掉大量「生成出来发现太大改不动」的返工。表上再写一句「什么时候不用 AI、直接手改」，会更完整。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"片段\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">片段</tspan></text></g><g data-k=\"函数\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">函数</tspan></text></g><g data-k=\"模块\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">模块</tspan></text></g><g data-k=\"指令要点\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">指令要点</tspan></text></g></svg>","d":38.4},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「生成代码的三种粒度」。按任务范围选对生成粒度，不一次要太多把今天最有价值的三点写进产出物「粒度选择表」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：从片段、函数、模块三类任务中各举一个你的真实例子。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":40.3}],"quiz":[{"q":"第一次让 AI 生成复杂功能，最稳妥的粒度是？","opts":["一次生成整个系统","从函数级开始，验证后再组合","只生成注释","不生成只手工写"],"a":1,"why":"从函数级开始便于验证，验证通过后再组合成模块，成功率更高。"},{"q":"决定生成粒度的主要依据是？","opts":["AI 的心情","任务范围与你能验证的边界","代码行数要求","工具的默认设置"],"a":1,"why":"粒度应匹配任务范围，且以你能独立验证为边界。"}],"template":"【粒度选择表】\n片段｜适用____ 不适用____\n函数｜适用____ 不适用____\n模块｜适用____ 不适用____","brief":"【本单元要点】粒度选错，是生成失败最常见的原因\n【为什么重要】让 AI 一次生成整个模块，结果处处对不上\n【看完做一件事】从片段、函数、模块三类任务中各举一个你的真实例子。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M3U2","tier":"core","step":"understand","title":"让 AI 写第一个函数","video":{"dur":"4.4min","script":["从一句话到规格","写清输入与输出","写清边界与约束"]},"ppt":{"method":"同一件事，说清楚和说模糊，产出天差地别","case":"把「写个校验函数」改成规格化指令后一次生成正确","demo":"函数代码与指令记录"},"objective":"用规格化指令生成可用函数","transfer":"能写出规格化指令并生成通过测试的函数","deliverable":{"type":"document","name":"函数代码 + 指令记录","rubric":["规格化指令","生成代码","测试结果"],"acceptance":"一份记录：写清你的完整指令、AI 生成的代码、测试结果。"},"task":"用规格化指令生成一个真实函数，并附上你的指令。","rubric":["指令含输入输出与边界","代码通过测试","记录了完整指令"],"vslides":[{"t":"从一句话到规格","n":"「写个校验手机号的函数」是最常见的模糊指令。AI 会给你一个看似合理的版本，但你要的格式、错误提示、边界它可能都不知道。规格化指令就是把这类话变成结构化描述：背景、输入、输出、边界、约束、验收。「写个校验函数」和「写一个校验手机号的函数，输入字符串，只接受 11 位数字，非法输入返回明确错误」，得到的输出完全不是一回事。规格化的第一步，就是把形容词换成可观察的条件。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"写个校验函数\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">写个校验函数</tspan></text></g><g data-k=\"输入为字符串，11位数字，非法返回明确错误\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"94.8\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">输入为字符串，11位数字</tspan><tspan x=\"295.0\" dy=\"15.600000000000001\">，非法返回明确错误</tspan></text></g></svg>","d":42.8},{"t":"写清输入与输出","n":"先写输入：类型、格式、取值范围、来源。再写输出：类型、字段、错误时返回什么。这两项最好写成具体的结构，比如「输入：手机号字符串；输出：合法返回 true，非法返回 {valid:false, reason:具体原因}」。输入和输出要写到类型和格式。输入是字符串还是数字、什么格式算合法；输出是布尔值还是结构对象、错误时返回什么。这些写清楚，AI 不需要猜，生成的代码才对得上你的调用方。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"输入类型格式\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">输入类型格式</tspan></text></g><g data-k=\"输出结构\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">输出结构</tspan></text></g><g data-k=\"错误返回\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">错误返回</tspan></text></g></svg>","d":50.2},{"t":"写清边界与约束","n":"接着写边界：空值、超长、特殊字符、非字符串输入怎么处理。再写约束：不硬编码、不打印敏感信息、遵循项目命名风格。边界和约束是 AI 最容易忽略的部分，必须显式写出来。边界与约束那一栏，至少写清空值、超长、特殊字符三种情况怎么处理，以及命名要遵守什么规范。你会发现这些正是 AI 最容易按自己习惯处理、而你的项目恰好不允许的地方。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"空值\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">空值</tspan></text></g><g data-k=\"超长\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">超长</tspan></text></g><g data-k=\"特殊字符\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">特殊字符</tspan></text></g><g data-k=\"命名约束\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">命名约束</tspan></text></g></svg>","d":42.4},{"t":"附上验收条件","n":"最后附上验收条件：列出三到五条测试用例及预期结果。比如「13800138000 返回 true」「空字符串返回 false 且 reason 说明原因」。有验收条件，AI 生成时就知道目标，你验收时也有尺子。附上验收条件是一个关键动作：把你准备用来验证的用例写进指令里。AI 看到验收条件，会主动照顾这些情况——这比生成完再改，效率高出一个量级。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"给规格\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">给规格</tspan></text></g><g data-k=\"生成\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">生成</tspan></text></g><g data-k=\"跑验收测试\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">跑验收测试</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":40.3},{"t":"生成与记录","n":"把完整指令交给 AI，拿到代码后逐条跑验收测试。全部通过就记录：你的指令原文、生成的代码、测试结果。如果没通过，看是规格没写清还是代码有 bug，针对性修正。这份记录是函数的成长档案。生成后别急着关掉会话，把「规格、生成结果、测试结果、偏差」四样都记下来。积累三五条之后，你就能看出 AI 在这个项目里稳定的强项和弱项，后面的指令会越写越准。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"写规格\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">写规格</tspan></text></g><g data-k=\"生成\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">生成</tspan></text></g><g data-k=\"测试\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">测试</tspan></text></g><g data-k=\"记录\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">记录</tspan></text></g></svg>","d":43.3},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「让 AI 写第一个函数」。能写出规格化指令并生成通过测试的函数把今天最有价值的三点写进产出物「函数代码 + 指令记录」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：用规格化指令生成一个真实函数，并附上你的指令。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":42.4}],"quiz":[{"q":"规格化指令不包含下列哪一项？","opts":["输入结构","输出结构","边界处理","你今天的心情"],"a":3,"why":"规格化指令要写清输入输出、边界和约束，与情绪无关。"},{"q":"生成函数后，验证其可用的最好方式是？","opts":["看代码长度","运行你写的验收测试","看注释多少","问另一个 AI"],"a":1,"why":"运行针对验收标准写的测试，是验证代码可用的可靠方法。"}],"template":"【函数指令记录】\n我的完整指令：____\n生成代码：____\n验收测试结果：____","brief":"【本单元要点】同一件事，说清楚和说模糊，产出天差地别\n【为什么重要】把「写个校验函数」改成规格化指令后一次生成正确\n【看完做一件事】用规格化指令生成一个真实函数，并附上你的指令。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M3U3","tier":"core","step":"understand","title":"生成后的三问验收法","video":{"dur":"4.4min","script":["为什么要三问","第一问：正确性","第二问：安全性"]},"ppt":{"method":"AI 说没问题，不等于真没问题","case":"一段 AI 生成的查询接口通过了功能测试，却有注入风险","demo":"三问验收卡"},"objective":"逐项检查正确性、安全性、可维护性","transfer":"对任何 AI 产出执行三问验收","deliverable":{"type":"document","name":"三问验收卡","rubric":["正确性","安全性","可维护性"],"acceptance":"一张卡：三问各写两条检查项，并用它验收一段真实代码。"},"task":"用三问验收一段 AI 生成的代码。","rubric":["三问齐全","每问有检查项","验收了真实代码"],"vslides":[{"t":"为什么要三问","n":"AI 生成的代码常常「能跑」，但能跑只是最低标准。它可能漏了边界、藏了安全问题、写得没人能维护。三问验收就是把它从「能跑」提升到「可交付」的闸门：正确性、安全性、可维护性，缺一不可。「能跑」是最低标准，不是交付标准。一段代码跑通了你写的那个用例，可能仍有边界没覆盖、有注入风险、有难以维护的结构。三问验收就是把「能跑」拆成三个可检查的维度。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"能跑\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">能跑</tspan></text></g><g data-k=\"正确性\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">正确性</tspan></text></g><g data-k=\"安全性\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">安全性</tspan></text></g><g data-k=\"可维护性\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">可维护性</tspan></text></g><g data-k=\"可交付\"><rect x=\"145.3\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">可交付</tspan></text></g></svg>","d":43.1},{"t":"第一问：正确性","n":"正确性问的是：逻辑对不对？边界考虑了没有？异常路径处理了吗？对照你在 M1 写的验收标准逐条检查，尤其是边界和异常。不要只看正常输入的结果，把空值、超长、非法格式都试一遍。正确性是最基本的一问。第一问正确性，要对照需求逐条核：逻辑是否符合业务规则、边界是否覆盖、异常路径是否处理。特别注意 AI 有没有把「通常情况」当成「所有情况」——它在这一点上出错最隐蔽。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"逻辑正确\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">逻辑正确</tspan></text></g><g data-k=\"边界覆盖\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">边界覆盖</tspan></text></g><g data-k=\"异常路径\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">异常路径</tspan></text></g></svg>","d":45.7},{"t":"第二问：安全性","n":"安全性问的是：有没有注入风险？有没有硬编码密钥？权限判断有没有漏？敏感信息会不会被写进日志或返回给用户？这一问最容易被忽略，因为安全问题在正常测试里不会暴露。但它一旦出问题，代价最大。第二问安全性，重点扫四类：注入风险、硬编码密钥、权限判断、日志泄漏。这四类不会让功能失效，但一旦出问题就是大事。所以它们要单独过一遍，不能混在功能检查里顺带看。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"注入风险\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">注入风险</tspan></text></g><g data-k=\"硬编码密钥\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">硬编码密钥</tspan></text></g><g data-k=\"权限判断\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">权限判断</tspan></text></g><g data-k=\"日志泄漏\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">日志泄漏</tspan></text></g></svg>","d":48.5},{"t":"第三问：可维护性","n":"可维护性问的是：命名能不能看懂？结构有没有超过合理长度？魔法数字有没有抽出来？关键逻辑有没有说明依据？AI 生成的代码常常堆在一个函数里，短期能用，长期难改。可维护性决定了这段代码是资产还是负债。第三问可维护性，判断标准是下一个人接手要花多久。一堆魔法数字和超长函数，改一处要读半天；换成具名常量和清晰结构，谁来都能接。可维护性差的产出，成本会在几周后显现。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"一堆魔法数字和长函数\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">一堆魔法数字和长函数</tspan></text></g><g data-k=\"具名常量与清晰结构\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">具名常量与清晰结构</tspan></text></g></svg>","d":44.7},{"t":"把三问做成清单","n":"把三问各写两条检查项，做成一张验收卡，贴在每次生成之后。任何一问不通过就回去改，不要抱着「先这样后面再说」的心态。三问验收是整门课反复出现的动作，也是你从「用 AI 写代码」到「交付可靠代码」的分水岭。把三问做成清单并在每次生成后逐条打勾。清单的价值在于它不依赖你的状态——再累的时候，照着勾一遍也能挡住大部分问题。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"正确性\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">正确性</tspan></text></g><g data-k=\"安全性\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">安全性</tspan></text></g><g data-k=\"可维护性\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">可维护性</tspan></text></g><g data-k=\"通过\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">通过</tspan></text></g></svg>","d":39.4},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「生成后的三问验收法」。对任何 AI 产出执行三问验收把今天最有价值的三点写进产出物「三问验收卡」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：用三问验收一段 AI 生成的代码。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":39.8}],"quiz":[{"q":"三问验收不包括下列哪一问？","opts":["正确性","安全性","可维护性","代码的颜色"],"a":3,"why":"三问是正确性、安全性、可维护性，与代码显示颜色无关。"},{"q":"AI 说「这段代码没问题」时，正确做法是？","opts":["直接相信","自己按三问验收","再问一次 AI","看代码行数"],"a":1,"why":"AI 的结论必须经人按标准复核，三问就是可操作的复核框架。"}],"template":"【三问验收卡】\n正确性：1____ 2____\n安全性：1____ 2____\n可维护性：1____ 2____\n结论：____","brief":"【本单元要点】AI 说没问题，不等于真没问题\n【为什么重要】一段 AI 生成的查询接口通过了功能测试，却有注入风险\n【看完做一件事】用三问验收一段 AI 生成的代码。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M3U4","tier":"core","step":"understand","title":"让 AI 自己解释生成的代码","video":{"dur":"3.9min","script":["解释是最便宜的检查","怎么让 AI 解释","听什么：关键假设"]},"ppt":{"method":"让生成者解释自己，是发现问题的捷径","case":"AI 解释时暴露出它误解了业务规则","demo":"代码解释记录"},"objective":"用解释发现隐藏问题","transfer":"能用解释指令发现代码里的隐藏问题","deliverable":{"type":"document","name":"代码解释记录","rubric":["解释指令","暴露问题","修正动作"],"acceptance":"一份记录：写清你的解释指令、AI 解释中暴露的问题、你的修正动作。"},"task":"让 AI 解释一段它生成的代码，并记录你的发现。","rubric":["用了解释指令","至少发现一个问题","有修正动作"],"vslides":[{"t":"解释是最便宜的检查","n":"生成完代码，除了自己读，还有一个便宜的检查手段：让 AI 自己解释。解释会让它的思路外显，你就能看到它到底是怎么理解你的需求的。很多时候你会发现「原来它把这里理解错了」，这种问题靠读代码未必看得出来。让 AI 解释自己生成的代码，是成本最低的一次检查。同一段代码，你看结果只能看到「写了什么」，看解释才能看到「当时怎么想的」——而错误往往藏在想法里，不在语法里。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"只看到结果代码\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">只看到结果代码</tspan></text></g><g data-k=\"看到生成时的思路\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">看到生成时的思路</tspan></text></g></svg>","d":40.9},{"t":"怎么让 AI 解释","n":"不要用「说说这段代码」这种模糊指令。好的解释指令要具体：逐行解释意图、指出你做的关键假设、标出你不确定的地方、说明为什么这样处理边界。特别是「关键假设」这一项，最能让隐藏问题浮出水面。解释要问四样：逐行意图、关键假设、不确定之处、边界处理的理由。尤其是不确定之处，AI 通常会诚实标出来，那些地方就是你接下来要重点验证的清单。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"逐行意图\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">逐行意图</tspan></text></g><g data-k=\"关键假设\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">关键假设</tspan></text></g><g data-k=\"不确定处\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">不确定处</tspan></text></g><g data-k=\"边界理由\"><g><circle cx=\"30\" cy=\"154\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 154 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"158.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">边界理由</tspan></text></g></svg>","d":41.0},{"t":"听什么：关键假设","n":"解释里最值得注意的是「假设」。AI 会说「假设输入总是合法的」「假设这个字段不为空」。每一个假设都是潜在的漏洞点——如果真实情况不符合，代码就会出问题。把它记下来，逐条确认现实是否满足。听关键假设时，重点核对四类：输入假设、数据假设、依赖假设、并发假设。AI 默认单线程、默认数据干净、默认依赖可用——这些默认值在真实系统里往往是错的。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"输入假设\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">输入假设</tspan></text></g><g data-k=\"数据假设\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">数据假设</tspan></text></g><g data-k=\"依赖假设\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">依赖假设</tspan></text></g><g data-k=\"并发假设\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">并发假设</tspan></text></g></svg>","d":39.6},{"t":"听什么：不一致","n":"第二种要听的是不一致。如果 AI 的解释和你的需求对不上，比如你说按时间排序，它解释成按金额排序，那说明生成方向就错了。这种问题越早发现越省事，解释正好能把它在验收前暴露出来。对照需求听不一致，是最有效的一类发现。比如需求说「重复提交要幂等」，解释里却说「每次都新建记录」——这种话如果只看代码不容易发现，听它自己讲出来反而清楚。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"对照需求\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">对照需求</tspan></text></g><g data-k=\"发现不一致\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">发现不一致</tspan></text></g><g data-k=\"当场纠正\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">当场纠正</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":39.1},{"t":"记录与修正","n":"把解释暴露的问题记下来，逐条修正。修正后让 AI 重新生成相关部分，再解释一遍，直到解释和需求完全一致。这份记录既是这一节的产出，也是你理解「AI 如何思考」的一手材料。把解释中的假设和不一致记下来，当场要求修正。这份记录后面还能复用：它告诉你这个项目里 AI 最容易做错哪类假设，下次指令里可以直接提前堵住。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"解释\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">解释</tspan></text></g><g data-k=\"找假设\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">找假设</tspan></text></g><g data-k=\"找不一致\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">找不一致</tspan></text></g><g data-k=\"修正\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">修正</tspan></text></g></svg>","d":36.7},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「让 AI 自己解释生成的代码」。能用解释指令发现代码里的隐藏问题把今天最有价值的三点写进产出物「代码解释记录」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：让 AI 解释一段它生成的代码，并记录你的发现。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":39.6}],"quiz":[{"q":"让 AI 解释生成代码的主要价值是？","opts":["让代码变长","暴露生成时的理解偏差","替代测试","证明 AI 很聪明"],"a":1,"why":"解释能让 AI 的思路外显，从而发现它对需求或逻辑的误解。"},{"q":"下面哪条解释指令更有效？","opts":["说说这段代码","逐行解释这段代码的意图，指出你做的关键假设和可能有问题的地方","这段代码好吗","解释得简单点"],"a":1,"why":"要求指出关键假设和潜在问题，才能有效暴露隐藏风险。"}],"template":"【代码解释记录】\n解释指令：____\n暴露的问题：____\n修正动作：____","brief":"【本单元要点】让生成者解释自己，是发现问题的捷径\n【为什么重要】AI 解释时暴露出它误解了业务规则\n【看完做一件事】让 AI 解释一段它生成的代码，并记录你的发现。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M3U5","tier":"core","step":"understand","title":"迭代优化：从能跑到跑得好","video":{"dur":"4.0min","script":["第一版只是起点","第一轮：先修正确性问题","第二轮：改善可维护性"]},"ppt":{"method":"第一版不是终点，迭代才是常态","case":"AI 第一版能跑但慢，三轮优化后性能提升明显","demo":"优化前后对照"},"objective":"用多轮指令完成一次优化","transfer":"能用多轮对话把初版优化成可用版本","deliverable":{"type":"document","name":"优化前后对照","rubric":["初版","优化指令","优化结果"],"acceptance":"一页对照：写清初版问题、每轮优化指令、最终改进点。"},"task":"对一个初版做三轮优化，记录前后对照。","rubric":["至少三轮优化","每轮有明确目标","记录改进点"],"vslides":[{"t":"第一版只是起点","n":"别指望 AI 一次给出完美版本。第一版通常是「能跑」的水平，接下来要靠迭代把它打磨到「好用」。迭代不是反复说「再优化一下」，而是每轮针对一个明确问题，给出具体指令，验证改进效果。第一版只是起点，不是成品。AI 生成的初版通常能跑通主路径，边界和维护性要靠后续几轮打磨。把「生成完成」当成开始而不是结束，是这一节要建立的预期。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"初版\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">初版</tspan></text></g><g data-k=\"问题定位\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">问题定位</tspan></text></g><g data-k=\"定向优化\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">定向优化</tspan></text></g><g data-k=\"验证\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">验证</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":43.6},{"t":"第一轮：先修正确性问题","n":"第一轮优先修正确性和安全问题，比如漏掉的边界、写错的逻辑、硬编码的密钥。这些问题影响功能和安全，必须最先处理。指令要具体：「在手机号校验里增加空值处理，返回明确错误」。第一轮只修正确性问题：边界缺失、逻辑错误、安全问题。不要在正确性问题还没解决时去调格式或命名——把不正确的代码美化得再漂亮，也仍然是错的。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"边界缺失\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">边界缺失</tspan></text></g><g data-k=\"逻辑错误\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">逻辑错误</tspan></text></g><g data-k=\"安全问题\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">安全问题</tspan></text></g></svg>","d":36.1},{"t":"第二轮：改善可维护性","n":"第二轮处理结构和可读性：拆分过长的函数、提取魔法数字、改善命名、补充关键注释。这一轮不改行为，只改结构，最好有测试保证行为不变。指令示例：「把这个函数里超过三层的嵌套拆成两个具名函数」。第二轮改善可维护性：拆长函数、提取常量、改命名、补关键注释。这一轮的目标是让下一个人能看懂，也让下一轮改动更容易——好的结构本身就是后续迭代的加速器。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"拆长函数\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">拆长函数</tspan></text></g><g data-k=\"提常量\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">提常量</tspan></text></g><g data-k=\"改命名\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">改命名</tspan></text></g><g data-k=\"补注释\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">补注释</tspan></text></g></svg>","d":45.5},{"t":"第三轮：性能与体验","n":"第三轮才考虑性能和体验：减少不必要的重复计算、优化查询、改善错误提示。这一轮要靠数据说话，比如「这个接口响应 2 秒，目标降到 500 毫秒内」。没有量化目标的优化很难判断效果。第三轮才轮到性能和体验，而且指令要具体。「优化一下」得到的往往是无关调整；「接口响应从 2 秒降到 500 毫秒内」才能让 AI 有针对性地找瓶颈。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"vague 优化\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">vague 优化</tspan></text></g><g data-k=\"接口响应从2秒降到500毫秒内\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"94.8\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">接口响应从2秒降到500</tspan><tspan x=\"295.0\" dy=\"15.600000000000001\">毫秒内</tspan></text></g></svg>","d":39.6},{"t":"记录前后对照","n":"每一轮都记录：你指出了什么问题、给了什么指令、结果改了什么、是否通过验证。三轮下来，你会看到清晰的改进轨迹。这份对照表不仅证明优化有效，也让你逐渐掌握「什么样的指令能带来什么样的改进」。每一轮都记录前后对照：改了什么、为什么改、验证结果。三轮下来，这份记录就是一次完整迭代的复盘——它比最终代码更能说明你的判断过程。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"修正确性\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">修正确性</tspan></text></g><g data-k=\"改可维护性\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">改可维护性</tspan></text></g><g data-k=\"提性能\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">提性能</tspan></text></g><g data-k=\"记录\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">记录</tspan></text></g></svg>","d":37.5},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「迭代优化：从能跑到跑得好」。能用多轮对话把初版优化成可用版本把今天最有价值的三点写进产出物「优化前后对照」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：对一个初版做三轮优化，记录前后对照。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":40.1}],"quiz":[{"q":"多轮优化的正确方式是？","opts":["每轮说「再优化一下」","每轮针对一个明确问题给出指令","一次提所有要求","让 AI 自己决定"],"a":1,"why":"每轮聚焦一个明确问题，AI 才能针对性改进，你也才能验证效果。"},{"q":"迭代优化的前提是？","opts":["有可对比的验收标准","代码越长越好","没有测试更快","跳过审查"],"a":0,"why":"有验收标准才能判断优化是否真的变好，而不是自我感觉。"}],"template":"【优化前后对照】\n初版问题：____\n第1轮：指令____ 结果____\n第2轮：指令____ 结果____\n第3轮：指令____ 结果____","brief":"【本单元要点】第一版不是终点，迭代才是常态\n【为什么重要】AI 第一版能跑但慢，三轮优化后性能提升明显\n【看完做一件事】对一个初版做三轮优化，记录前后对照。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M3U6","tier":"core","step":"understand","title":"识别幻觉 API 与不存在的依赖","video":{"dur":"4.0min","script":["什么是幻觉 API","核实方法一：查官方文档","核实方法二：查本地依赖"]},"ppt":{"method":"AI 最危险的错误，是编造一个不存在的东西","case":"AI 引用了一个不存在的库方法，构建直接失败","demo":"幻觉排查清单"},"objective":"验证 AI 引用的库与函数真实存在","transfer":"对 AI 引用的每个新 API 做存在性核实","deliverable":{"type":"document","name":"幻觉排查清单","rubric":["查文档","查本地依赖","查版本","跑最小验证"],"acceptance":"一张清单：四类核实方法各写一条操作，并用它核实三个新 API。"},"task":"写一份幻觉排查清单并核实三个新 API。","rubric":["四类方法齐全","核实了三个真实 API","有结论"],"vslides":[{"t":"什么是幻觉 API","n":"AI 有时会凭空生成一个看起来很真实的函数名、参数或整个库。它写得如此自然，你很容易直接照抄。结果构建时报错「找不到这个方法」，或者更糟——运行时才发现行为不对。这一节教你系统性地核实。幻觉 API 指的是 AI 一本正经引用根本不存在的库、函数或参数。它不会报错提示「我编的」，反而说得很肯定——这正是它危险的原因：你按它的写法去调，运行时才发现根本没有这个方法。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"不存在的函数\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">不存在的函数</tspan></text></g><g data-k=\"不存在的参数\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">不存在的参数</tspan></text></g><g data-k=\"不存在的库\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">不存在的库</tspan></text></g></svg>","d":45.1},{"t":"核实方法一：查官方文档","n":"第一个方法是查官方文档。把 AI 给出的库名和方法名拿到官方文档里搜。如果文档里找不到这个方法，或者参数签名对不上，就是幻觉。注意版本：不同版本的 API 差别很大，要查你实际使用的那个版本。核实第一站是官方文档：查库名、方法名、参数签名、版本。特别注意版本——一个在最新版里存在的方法，你项目锁定的旧版本里未必有。查文档时把版本号一起确认。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"库名\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">库名</tspan></text></g><g data-k=\"方法名\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">方法名</tspan></text></g><g data-k=\"参数签名\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">参数签名</tspan></text></g><g data-k=\"版本\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">版本</tspan></text></g></svg>","d":41.0},{"t":"核实方法二：查本地依赖","n":"第二个方法是查本地依赖。打开已安装的包，看它实际导出了哪些方法；或者在 IDE 里看自动补全有没有这个方法。本地依赖是你项目真实可用的东西，比任何说法都可靠。核实第二站是本地依赖：直接看你项目里装的包有没有这个方法。比查文档更可靠，因为它是你实际运行的环境。命令行的自动补全能给你最直接的答案。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"AI 说有这个方法\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">AI 说有这个方法</tspan></text></g><g data-k=\"本地依赖里实际存在吗\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">本地依赖里实际存在吗</tspan></text></g></svg>","d":34.4},{"t":"核实方法三：跑最小验证","n":"第三个方法最直接：写一个最小的调用示例跑一下。能跑通、返回值符合预期，就确认了。这个方法成本略高，但最可靠，特别适合关键路径上的新 API。核实第三站是跑最小验证：写三五行最小示例，运行，看返回值。这是最慢但最确定的一招。凡是要进核心路径的依赖调用，都值得花这几分钟换一个确定答案。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"写最小示例\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"76.4\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">写最小示</tspan><tspan x=\"58.2\" dy=\"16.900000000000002\">例</tspan></text></g><g data-k=\"运行\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">运行</tspan></text></g><g data-k=\"看返回值\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">看返回值</tspan></text></g><g data-k=\"确认\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">确认</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":37.5},{"t":"写幻觉排查清单","n":"把四类核实方法写成清单：查文档、查本地依赖、查版本、跑最小验证。以后每次 AI 引用了你不熟悉的 API，就按清单过一遍。这个习惯会让你远离「构建失败」和「上线才发现的坑」。把这三种核实方法写成排查清单，每次生成完扫一遍。你会发现幻觉 API 出现的频率并不低，只是以前没注意到——有了清单，它就会被挡在合并之前。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"查文档\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">查文档</tspan></text></g><g data-k=\"查依赖\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">查依赖</tspan></text></g><g data-k=\"查版本\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">查版本</tspan></text></g><g data-k=\"跑验证\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">跑验证</tspan></text></g></svg>","d":37.5},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「识别幻觉 API 与不存在的依赖」。对 AI 引用的每个新 API 做存在性核实把今天最有价值的三点写进产出物「幻觉排查清单」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：写一份幻觉排查清单并核实三个新 API。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":44.3}],"quiz":[{"q":"发现 AI 引用了没见过的库方法，正确做法是？","opts":["照着写","查官方文档或本地依赖确认存在","换个 AI 再问","删掉不用"],"a":1,"why":"核实存在性是防止幻觉依赖的关键，不能直接采信。"},{"q":"幻觉 API 最典型的危害是？","opts":["代码变丑","构建或运行时报错，甚至引入错误逻辑","注释变多","文件变大"],"a":1,"why":"引用不存在的 API 会直接导致构建失败，或在更隐蔽的情况下引入错误逻辑。"}],"template":"【幻觉排查清单】\n查文档：____\n查本地依赖：____\n查版本：____\n跑最小验证：____\n核实结论：____","brief":"【本单元要点】AI 最危险的错误，是编造一个不存在的东西\n【为什么重要】AI 引用了一个不存在的库方法，构建直接失败\n【看完做一件事】写一份幻觉排查清单并核实三个新 API。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M3U7","tier":"core","step":"spar","title":"陪练：Reviewer 挑刺你的生成结果","video":{"dur":"4.1min","script":["陪练说明","第一轮：为什么这样设计","第二轮：边界怎么处理的"]},"ppt":{"method":"能扛住评审的代码，才敢提交","case":"Reviewer 追问「为什么不用事务」，你答不上来","demo":"Review 对话记录"},"objective":"应对三轮代码质疑并修订","transfer":"面对 Reviewer 质疑能用依据回应并修订","deliverable":{"type":"document","name":"Review 对话记录","rubric":["被质疑点","你的回应","修订动作"],"acceptance":"一份记录：三轮质疑各写下被质疑点、你的回应、最终修订。"},"task":"完成三轮质疑应对，记录并修订。","rubric":["至少两轮有依据回应","有实际修订","记录了对话"],"vslides":[{"t":"陪练说明","n":"这一轮 AI 扮成资深 Reviewer，专门挑你生成结果的问题。他会从三个方向追问：为什么这样设计、边界怎么处理的、有没有更简单的写法。你的任务是用依据回应——测试、文档、需求，而不是「我觉得可以」。答不上来就诚实承认并现场修订。这一轮 AI 扮 Reviewer，专门质疑你生成结果的设计、边界和简化空间。真实代码评审里这三个问题最常出现，提前在这里被问一遍，上评审会时就从容得多。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"设计理由\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">设计理由</tspan></text></g><g data-k=\"边界处理\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">边界处理</tspan></text></g><g data-k=\"简化可能\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">简化可能</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":43.3},{"t":"第一轮：为什么这样设计","n":"第一轮问设计选择。比如「为什么这里用轮询不用事件」「为什么把这个逻辑放在这一层」。回应要讲清权衡：当时考虑了什么、为什么选这个、放弃方案的缺点是什么。有权衡意识的回答，才是资深工程师的回答。第一轮问「为什么这样设计」：要考虑过什么、为什么选这个方案、放弃了什么。能说出被放弃的方案，才说明这是权衡后的选择，而不是随手写的第一种写法。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"考虑了什么\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">考虑了什么</tspan></text></g><g data-k=\"为什么选它\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">为什么选它</tspan></text></g><g data-k=\"放弃了什么\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">放弃了什么</tspan></text></g></svg>","d":36.5},{"t":"第二轮：边界怎么处理的","n":"第二轮问边界。他会挑一个你没提到的边界问「如果这里是空值会怎样」「并发时会不会重复」。回应方式是拿出你的边界用例清单和测试：这些情况我测过，结果是这样。如果确实没考虑，承认并补一条处理。第二轮问边界怎么处理：空值、并发、超时、重复。挑两类给出具体处理方式和验证用例，答不上来的地方诚实记下来——评审会上被问倒不可怕，可怕的是现场编一个答案。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"空值\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">空值</tspan></text></g><g data-k=\"并发\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">并发</tspan></text></g><g data-k=\"超时\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">超时</tspan></text></g><g data-k=\"重复\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">重复</tspan></text></g></svg>","d":41.0},{"t":"第三轮：有没有更简单写法","n":"第三轮问简化。他会指出一段冗长代码问「能不能更简单」。这不是挑刺，而是可维护性的考验。如果能简化，现场改并说明；如果简化会损失可读性或扩展性，也要说清理由。好的代码是简单且够用，不是越短越好。第三轮问「有没有更简单的写法」。警惕为了短而短：过度简化会牺牲可读性。正确的回答是「简单且够用」——能说明为什么当前的复杂度是必要的，才是成熟判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"为短而短难维护\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">为短而短难维护</tspan></text></g><g data-k=\"简单且够用\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">简单且够用</tspan></text></g></svg>","d":43.3},{"t":"通过标准与修订","n":"通过标准是：至少两轮给出有依据的回应，且对答不上来的问题能诚实修订。结束后把三轮质疑和你做的修订记录下来。被挑出问题的代码才是好代码——因为问题在提交前就被发现了。通过标准是两轮有依据、一轮诚实修订。被问倒并当场承认、记录、回去改，比硬撑着辩解更能赢得评审人的信任——这一点在真实团队里同样成立。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"两轮有依据\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">两轮有依据</tspan></text></g><g data-k=\"诚实修订\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">诚实修订</tspan></text></g><g data-k=\"记录对话\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">记录对话</tspan></text></g></svg>","d":41.0},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「陪练：Reviewer 挑刺你的生成结果」。面对 Reviewer 质疑能用依据回应并修订把今天最有价值的三点写进产出物「Review 对话记录」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：完成三轮质疑应对，记录并修订。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":40.5}],"quiz":[{"q":"陪练中被质疑时，最好的回应方式是？","opts":["坚持说没问题","用测试和依据回应，不确定就承认并修订","回避技术问题","把责任推给 AI"],"a":1,"why":"用依据回应、对不确定的诚实修订，是专业评审中的正确态度。"},{"q":"代码评审陪练的核心价值是？","opts":["让代码变长","在提交前暴露设计缺陷","证明你写得快","减少注释"],"a":1,"why":"评审通过质疑暴露设计缺陷，是提交前的重要质量闸门。"}],"template":"【Review 对话记录】\n质疑1____ 回应____ 修订____\n质疑2____ 回应____ 修订____\n质疑3____ 回应____ 修订____","brief":"【本单元要点】能扛住评审的代码，才敢提交\n【为什么重要】Reviewer 追问「为什么不用事务」，你答不上来\n【看完做一件事】完成三轮质疑应对，记录并修订。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M3U8","tier":"core","step":"todo","title":"M3 实战：生成一个完整模块","video":{"dur":"4.2min","script":["实战任务说明","第一步：定粒度写规格","第二步：生成并解释"]},"ppt":{"method":"把生成方法用在一个真正要交付的模块上","case":"学员生成了一个订单查询模块并通过全部验收","demo":"模块代码包"},"objective":"交付一个通过三问验收的模块","transfer":"独立生成一个通过三问验收的完整模块","deliverable":{"type":"document","name":"模块代码包","rubric":["模块代码","三问验收记录","测试"],"acceptance":"一个可运行的模块代码包，含三问验收记录和通过的测试。"},"task":"生成一个真实模块，通过三问验收并交付。","rubric":["模块可运行","三问验收全部通过","有测试证明"],"vslides":[{"t":"实战任务说明","n":"这一节把 M3 的方法串起来：生成一个你真实需要的模块，通过三问验收。你会用到粒度选择、规格化指令、三问验收、自我解释、迭代优化和幻觉排查。目标是交付一个可运行、可复核、可提交的模块，而不是一段「看起来不错」的代码。这一节的实战是生成一个完整模块并通过三问验收。用你真实项目里的一个模块来做，别用玩具例子——只有真实上下文才能检验你前面学的粒度选择、规格编写和验收方法。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"选粒度\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">选粒度</tspan></text></g><g data-k=\"写规格\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">写规格</tspan></text></g><g data-k=\"生成\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">生成</tspan></text></g><g data-k=\"验收\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">验收</tspan></text></g><g data-k=\"迭代\"><rect x=\"145.3\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">迭代</tspan></text></g></svg>","d":45.9},{"t":"第一步：定粒度写规格","n":"先根据任务范围定粒度，从函数级开始。写出规格化指令：输入输出、边界、约束、验收条件。把你在 M1 写的需求和验收标准直接拿过来用，这一步是前面章节的积累兑现。第一步定粒度、写规格。先判断这个任务该用函数级还是模块级，再把输入、输出、边界、验收写成一份规格。规格写不清就别急着生成——这一步偷的懒，后面每一步都要还。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"粒度合适\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">粒度合适</tspan></text></g><g data-k=\"规格完整\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">规格完整</tspan></text></g><g data-k=\"验收明确\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">验收明确</tspan></text></g></svg>","d":40.8},{"t":"第二步：生成并解释","n":"让 AI 生成代码，然后让它自己解释一遍，重点看关键假设和不一致之处。发现幻觉 API，按排查清单核实。这一步能在验收前就拦掉不少问题。第二步生成并解释。生成完立刻让它解释关键假设和不确定处，你对照规格核一遍。这一步能挡掉大部分「生成时看着对、集成后才发现错」的问题。解释里的不确定处，就是你下一轮指令要重点补的地方。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"生成即结束\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">生成即结束</tspan></text></g><g data-k=\"生成+解释+核实\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">生成+解释+核实</tspan></text></g></svg>","d":41.2},{"t":"第三步：三问验收与迭代","n":"按三问逐项验收：正确性、安全性、可维护性，再跑你写的验收测试。任何一问不通过，就给出定向优化指令迭代。记录每轮改了什么、为什么改。直到三问全过、测试全绿。第三步做三问验收与迭代。正确性、安全性、可维护性逐项过，发现问题就按上一节的迭代顺序修：先正确、再可维护、最后性能。每轮修完都重跑一次全套用例，确认没有引入新问题。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"正确性\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">正确性</tspan></text></g><g data-k=\"安全性\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">安全性</tspan></text></g><g data-k=\"可维护性\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">可维护性</tspan></text></g><g data-k=\"测试\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">测试</tspan></text></g></svg>","d":44.5},{"t":"交付模块代码包","n":"把模块代码、三问验收记录、测试一起打包交付。这份代码包是 M3 的核心产出，也是后面 M4 审查、M5 测试的输入。它必须能被同事直接接手、被 Reviewer 复核。能交付，才叫学会。交付模块代码包时，代码、验收记录、测试、可交接说明四样要齐。单交代码等于把验证成本转嫁给下一个人——那不是交付，是甩锅。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"模块代码\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">模块代码</tspan></text></g><g data-k=\"验收记录\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">验收记录</tspan></text></g><g data-k=\"测试\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">测试</tspan></text></g><g data-k=\"可交接\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">可交接</tspan></text></g></svg>","d":39.8},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「M3 实战：生成一个完整模块」。独立生成一个通过三问验收的完整模块把今天最有价值的三点写进产出物「模块代码包」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：生成一个真实模块，通过三问验收并交付。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":40.5}],"quiz":[{"q":"M3 实战的交付标准是？","opts":["代码行数够多","通过三问验收且可运行","用了最多的 AI 工具","注释写得最长"],"a":1,"why":"交付标准是模块可运行、通过三问验收并有测试证明。"},{"q":"生成模块时遇到幻觉 API，应？","opts":["忽略继续","核实存在后再用","换个名字猜一个","删掉功能"],"a":1,"why":"先核实 API 真实存在，避免构建失败或引入错误逻辑。"}],"template":"【模块代码包】\n模块：____\n三问验收结论：____\n测试结果：____\n待优化项：____","brief":"【本单元要点】把生成方法用在一个真正要交付的模块上\n【为什么重要】学员生成了一个订单查询模块并通过全部验收\n【看完做一件事】生成一个真实模块，通过三问验收并交付。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"}]},{"id":"M4","title":"M4 代码审查：AI 初审 + 人把关","dims":["security","content"],"units":[{"id":"M4U1","tier":"core","step":"understand","title":"为什么 AI 审 AI 写的代码","video":{"dur":"4.1min","script":["一个自然的疑问","AI 初审擅长什么","AI 审查的盲区"]},"ppt":{"method":"让 AI 审 AI 写的代码，有用但不能全信","case":"AI 审查漏掉了一个业务逻辑错误，人工复核才发现","demo":"审查原则卡"},"objective":"说清 AI 审查的价值与人工复核的必要性","transfer":"理解 AI 初审 + 人把关的分工逻辑","deliverable":{"type":"document","name":"审查原则卡","rubric":["AI 初审","人把关","不互信"],"acceptance":"一页卡：写清 AI 审查擅长什么、不能信什么、哪些必须人工复核。"},"task":"写一份审查原则卡，说明哪些必须人工复核。","rubric":["说清 AI 初审价值","列出必须人工复核的点"],"vslides":[{"t":"一个自然的疑问","n":"让 AI 写代码，再让 AI 审代码，这不是自己查自己吗？这个疑问很合理。答案是：AI 初审确实有价值，但它不能替代人。它像一个勤奋的初级审查者，能快速扫出明显问题；但涉及业务判断和复杂权衡，必须由人来。「AI 写的代码让 AI 审」听起来像自己查自己，其实分工很清楚：AI 初审擅长快而广地扫一遍，把格式、坏味道、安全反模式先捞出来；人负责慢而深地把核心判断做掉。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"AI 初审：快而广\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">AI 初审：快而广</tspan></text></g><g data-k=\"人复核：准而深\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">人复核：准而深</tspan></text></g></svg>","d":43.6},{"t":"AI 初审擅长什么","n":"AI 擅长按已知模式扫描：格式问题、明显的坏味道、常见的安全反模式、命名不一致。这些工作重复度高、规则明确，AI 做得比人快且不易疲劳。把它用在这一层，能省下大量机械检查时间。AI 初审擅长四类：格式问题、明显坏味道、安全反模式、命名一致性。这些都是有明确模式可循的东西，机器扫得比人快，也不容易被看漏——让它做这些最划算。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"格式问题\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">格式问题</tspan></text></g><g data-k=\"明显坏味道\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">明显坏味道</tspan></text></g><g data-k=\"安全反模式\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">安全反模式</tspan></text></g><g data-k=\"命名一致性\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">命名一致性</tspan></text></g></svg>","d":42.7},{"t":"AI 审查的盲区","n":"AI 的盲区在业务和上下文。它不知道你们系统的历史约定，不知道某个「奇怪」写法是为了兼容老数据，也无法判断一个逻辑是否符合真实业务规则。更隐蔽的是，如果两个 AI 犯了同样的理解偏差，互相审查也发现不了。AI 审查的盲区在业务规则、历史约定、共同偏差和复杂权衡。它不知道你们系统三年前那次 bug 修复留下的特殊逻辑，也不知道客户那句「差不多」的真实含义——这些必须人来看。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"业务规则\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">业务规则</tspan></text></g><g data-k=\"历史约定\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">历史约定</tspan></text></g><g data-k=\"共同偏差\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">共同偏差</tspan></text></g><g data-k=\"复杂权衡\"><g><circle cx=\"30\" cy=\"154\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 154 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"158.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">复杂权衡</tspan></text></g></svg>","d":42.2},{"t":"人工复核的重点","n":"所以人要把关的是：业务逻辑是否正确、设计权衡是否合理、边界和数据是否符合现实、安全判断是否到位。这些恰恰是代码质量的核心。AI 扫表层，人把核心——这才是有效的审查分工。人工复核的重点是把核心拿住：AI 扫表层问题，人确认业务正确性和架构合理性，最后签字放行。分工不是「AI 审完人随便看看」，而是「AI 把表层扫干净，人专注深水区」。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"AI 扫表层\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">AI 扫表层</tspan></text></g><g data-k=\"人把核心\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">人把核心</tspan></text></g><g data-k=\"签字放行\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">签字放行</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":43.2},{"t":"写审查原则卡","n":"把这套分工写成原则卡：AI 初审的价值、它不能信的地方、必须人工复核的点。以后每次审查前扫一眼，避免走向两个极端——要么全信 AI，要么完全不用 AI。把这张审查原则卡写下来，团队共用一份。它能统一「哪些交给 AI、哪些必须人看」的口径，避免不同人审查深度差别太大的问题。卡片贴在评审入口，谁审都按同一把尺子来。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"AI 初审\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">AI 初审</tspan></text></g><g data-k=\"识别盲区\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">识别盲区</tspan></text></g><g data-k=\"人工复核\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">人工复核</tspan></text></g><g data-k=\"放行\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">放行</tspan></text></g></svg>","d":35.6},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「为什么 AI 审 AI 写的代码」。理解 AI 初审 + 人把关的分工逻辑把今天最有价值的三点写进产出物「审查原则卡」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：写一份审查原则卡，说明哪些必须人工复核。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":39.6}],"quiz":[{"q":"关于 AI 审查 AI 写的代码，正确的是？","opts":["完全可信，不用人看","能做初审发现明显问题，但必须人工复核","一定比人审得差","只能审查注释"],"a":1,"why":"AI 初审能高效发现明显问题，但受限于上下文和判断力，必须人工把关。"},{"q":"AI 审查最不适合承担的是？","opts":["找明显的格式问题","扫已知的安全模式","判断业务规则是否正确","列出潜在坏味道"],"a":2,"why":"业务规则正确性依赖领域上下文，AI 难以独立判断，必须由人把关。"}],"template":"【审查原则卡】\nAI 擅长：____\nAI 盲区：____\n必须人工复核：____","brief":"【本单元要点】让 AI 审 AI 写的代码，有用但不能全信\n【为什么重要】AI 审查漏掉了一个业务逻辑错误，人工复核才发现\n【看完做一件事】写一份审查原则卡，说明哪些必须人工复核。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M4U2","tier":"core","step":"understand","title":"结构化审查报告怎么写","video":{"dur":"4.0min","script":["从吐槽到清单","要素一：问题位置","要素二：级别"]},"ppt":{"method":"审查报告不是吐槽列表，是可执行的清单","case":"一份审查报告只写「代码不好」，开发无从下手","demo":"审查报告模板"},"objective":"生成含问题分级与修复建议的报告","transfer":"能产出可归档的结构化代码审查报告","deliverable":{"type":"document","name":"审查报告模板","rubric":["问题定位","级别","修复建议","证据"],"acceptance":"一份报告模板：每个问题含位置、级别、描述、修复建议四要素。"},"task":"生成一份结构化审查报告。","rubric":["四要素齐全","问题有级别","建议可执行"],"vslides":[{"t":"从吐槽到清单","n":"很多人写的审查意见是「这里不好」「这段要改」，开发看完还是不知道怎么动手。结构化审查报告的目标是把意见变成清单：每个问题有明确位置、级别、描述和修复建议。这样开发能逐条处理，主管能追踪进度。「这里代码不好」是一句无效反馈，因为它没给位置、没给理由、没给方向。把审查意见写成结构化报告，是让 AI 初审结果真正可用、让人复核真正高效的前提。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"这里代码不好（无效）\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">这里代码不好（无效）</tspan></text></g><g data-k=\"第42行：空值未处理，建议加判空（有效）\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"94.8\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">第42行：空值未处理，建</tspan><tspan x=\"295.0\" dy=\"15.600000000000001\">议加判空（有效）</tspan></text></g></svg>","d":42.4},{"t":"要素一：问题位置","n":"写清问题在哪个文件、哪一行、哪个函数。位置越精确，修复越快。模糊的「这个文件有问题」等于没说。让 AI 生成报告时，明确要求它标注文件与行号。问题位置要精确到文件名、行号、函数名。只说「这个函数有问题」会让人满文件找；给出行号，对方一眼就能定位——审查意见的可执行性，从位置精确开始。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"文件名\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">文件名</tspan></text></g><g data-k=\"行号\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">行号</tspan></text></g><g data-k=\"函数名\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">函数名</tspan></text></g></svg>","d":37.8},{"t":"要素二：级别","n":"给每个问题分级，比如阻断、重要、建议三级。阻断是必须改才能合并的，比如安全漏洞；重要是应该改的，比如明显的性能问题；建议是可选的优化。分级让开发知道先改什么，也让评审有据可依。级别分三档：阻断是必须改才能合并，重要是应该尽快改，建议是可以缓。分级让修复顺序一目了然，也避免把所有问题都堆成「都要改」——那等于没分级。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"阻断：必须改\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">阻断：必须改</tspan></text></g><g data-k=\"重要：应该改\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">重要：应该改</tspan></text></g><g data-k=\"建议：可选\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">建议：可选</tspan></text></g></svg>","d":44.5},{"t":"要素三：描述与建议","n":"描述要说清问题是什么、为什么是问题；建议要说清怎么改，最好给出方向或示例。不要只说「这里有安全问题」，要说「这里直接拼接 SQL，存在注入风险，建议改用参数化查询」。描述与建议要包含三件事：定位、原因、修复方向。「第 42 行空值未处理，传入 null 时会抛异常，建议先判空再取值」——这样的意见拿过去就能改。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"定位\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">定位</tspan></text></g><g data-k=\"描述原因\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">描述原因</tspan></text></g><g data-k=\"给修复方向\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">给修复方向</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":38.2},{"t":"生成与归档","n":"让 AI 按这个结构生成报告初稿，你人工校准级别和建议，特别是业务相关的判断。校准后的报告归档，作为这次审查的记录。一份好的审查报告，本身就是团队的知识资产。生成后要人工校准分级，再归档。AI 常常把风格问题标成阻断、把真正的风险标成建议，校准这一步不能省；归档下来的报告还会成为后面团队规范的素材。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"AI 生成\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">AI 生成</tspan></text></g><g data-k=\"人工校准\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">人工校准</tspan></text></g><g data-k=\"分级\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">分级</tspan></text></g><g data-k=\"归档\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">归档</tspan></text></g></svg>","d":39.0},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「结构化审查报告怎么写」。能产出可归档的结构化代码审查报告把今天最有价值的三点写进产出物「审查报告模板」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：生成一份结构化审查报告。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":37.7}],"quiz":[{"q":"结构化审查报告里，每个问题不该缺少的是？","opts":["开发者的名字","位置、级别、描述、修复建议","代码的总行数","AI 的模型版本"],"a":1,"why":"四要素让问题可定位、可判定、可执行，是报告的核心。"},{"q":"修复建议写得好的标准是？","opts":["写得越长越好","具体到怎么改、改哪里","用很多专业术语","只说「优化一下」"],"a":1,"why":"可执行的建议要具体指出改哪里、怎么改，而不是空泛的「优化」。"}],"template":"【审查报告模板】\n问题｜位置｜级别｜描述｜修复建议\n1 ____\n2 ____\n3 ____","brief":"【本单元要点】审查报告不是吐槽列表，是可执行的清单\n【为什么重要】一份审查报告只写「代码不好」，开发无从下手\n【看完做一件事】生成一份结构化审查报告。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M4U3","tier":"core","step":"understand","title":"安全漏洞初筛：注入、密钥、权限","video":{"dur":"4.3min","script":["为什么先扫安全","第一类：注入","第二类：密钥"]},"ppt":{"method":"安全问题不能等上线才发现","case":"AI 生成的接口把数据库异常直接返回给用户，暴露了表结构","demo":"安全初筛清单"},"objective":"用 AI 扫出三类高危问题","transfer":"能用 AI 辅助做三类高危安全初筛","deliverable":{"type":"document","name":"安全初筛清单","rubric":["注入","密钥","权限"],"acceptance":"一张清单：三类高危各写识别特征与处理建议，并扫描一段代码。"},"task":"写一份安全初筛清单并扫描一段真实代码。","rubric":["三类齐全","有识别特征","扫描了真实代码"],"vslides":[{"t":"为什么先扫安全","n":"在所有代码问题里，安全问题优先级最高。功能有 bug 影响体验，安全问题可能造成数据泄露、越权访问、甚至法律风险。让 AI 审代码，第一步就应该扫安全。这一节聚焦三类最高频的：注入、密钥、权限。安全问题优先扫，因为它一旦出问题，其他优点都抵不过。注入、密钥、权限这三类是最高频的高危项，也是 AI 初审最容易发现、人最容易忽略的三类——先扫它们性价比最高。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"注入\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">注入</tspan></text></g><g data-k=\"密钥\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">密钥</tspan></text></g><g data-k=\"权限\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">权限</tspan></text></g><g data-k=\"高危优先\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">高危优先</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":45.0},{"t":"第一类：注入","n":"注入包括 SQL 注入、命令注入、模板注入等。识别特征是：用户输入被直接拼进查询、命令或模板里。AI 能比较 reliably 地发现这类模式。处理建议统一是：改用参数化查询或转义，永远不要直接拼接。注入包括 SQL 注入、命令注入、模板注入。判断标准是：用户输入有没有被当成代码执行。参数化处理是通用解法，检查时看每一处拼接——尤其是看起来「只是内部用」的地方。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"SQL 注入\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">SQL 注入</tspan></text></g><g data-k=\"命令注入\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">命令注入</tspan></text></g><g data-k=\"模板注入\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">模板注入</tspan></text></g><g data-k=\"参数化处理\"><g><circle cx=\"30\" cy=\"154\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 154 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"158.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">参数化处理</tspan></text></g></svg>","d":44.3},{"t":"第二类：密钥","n":"密钥问题包括硬编码的口令、令牌、API Key，以及把它们写进日志或错误信息。识别特征是代码里出现疑似真实凭据的字符串。处理建议：一律改为环境变量或密钥管理服务，绝不入库、绝不入日志。密钥类问题有四种形态：硬编码口令、令牌写进日志、配置明文、错误信息里带凭据。改法是统一走环境变量，并在日志和错误信息里做脱敏——四处地方都要查，不能只查代码。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"硬编码口令\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">硬编码口令</tspan></text></g><g data-k=\"令牌入日志\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">令牌入日志</tspan></text></g><g data-k=\"配置明文\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">配置明文</tspan></text></g><g data-k=\"改用环境变量\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">改用环境变量</tspan></text></g></svg>","d":44.6},{"t":"第三类：权限","n":"权限问题包括越权访问、缺少鉴权、把内部错误直接返回给用户。识别特征是接口没有校验当前用户身份，或错误信息泄漏了内部表结构、路径。处理建议：补齐鉴权、最小化错误信息、统一错误码。权限和信息泄漏常常一起出现：数据库异常原样返回给用户，就把表结构暴露了。改法是统一错误码，对外只说「操作失败」，详细堆栈只进内部日志——用户不需要知道你的表叫什么。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"数据库异常原样返回\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">数据库异常原样返回</tspan></text></g><g data-k=\"统一错误码，不泄漏结构\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">统一错误码，不泄漏结构</tspan></text></g></svg>","d":45.7},{"t":"AI 初筛 + 人确认","n":"让 AI 按清单扫一遍，它会把可疑点列出来。但记住这是初筛：AI 可能误报，也可能漏掉业务特有的风险。你要逐条确认，并补充 AI 不知道的业务规则。确认后的问题进入审查报告，按级别处理。AI 初筛出结果后，人必须逐条确认，再补上业务特有的风险（比如某个字段虽然不是密钥但同样敏感），最后写进报告。初筛是线索，确认才是结论。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"AI 初筛\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">AI 初筛</tspan></text></g><g data-k=\"人工确认\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">人工确认</tspan></text></g><g data-k=\"补业务风险\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">补业务风险</tspan></text></g><g data-k=\"入报告\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">入报告</tspan></text></g></svg>","d":35.8},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「安全漏洞初筛：注入、密钥、权限」。能用 AI 辅助做三类高危安全初筛把今天最有价值的三点写进产出物「安全初筛清单」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：写一份安全初筛清单并扫描一段真实代码。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":41.0}],"quiz":[{"q":"下面哪项属于典型的安全高危？","opts":["命名不规范","SQL 直接拼接用户输入","注释太少","函数太长"],"a":1,"why":"直接拼接用户输入会造成注入漏洞，属于必须拦截的安全高危。"},{"q":"发现代码里硬编码了数据库口令，应定为？","opts":["建议优化","阻断级，必须修改","无需处理","看心情"],"a":1,"why":"硬编码密钥是严重安全隐患，属于阻断级问题，必须整改。"}],"template":"【安全初筛清单】\n注入：识别____ 处理____\n密钥：识别____ 处理____\n权限：识别____ 处理____\n扫描结论：____","brief":"【本单元要点】安全问题不能等上线才发现\n【为什么重要】AI 生成的接口把数据库异常直接返回给用户，暴露了表结构\n【看完做一件事】写一份安全初筛清单并扫描一段真实代码。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M4U4","tier":"core","step":"understand","title":"性能与可维护性审查","video":{"dur":"4.0min","script":["两类问题，两种价值","性能：看重复 I/O","性能：看数据结构"]},"ppt":{"method":"能跑不等于跑得好，能改才叫资产","case":"一个循环里反复查询数据库，导致接口越来越慢","demo":"性能审查表"},"objective":"定位性能瓶颈与代码坏味道","transfer":"能审查代码的性能与可维护性问题","deliverable":{"type":"document","name":"性能审查表","rubric":["性能瓶颈","坏味道","改进建议"],"acceptance":"一张表：列出三类性能问题和三类坏味道，各附识别方法。"},"task":"写一份性能与可维护性审查表。","rubric":["性能与可维护性都覆盖","有识别方法","建议具体"],"vslides":[{"t":"两类问题，两种价值","n":"安全和正确性决定代码能不能上线，性能和可维护性决定它值不值得长期拥有。这一节看后两类：性能瓶颈和代码坏味道。它们不会让程序立刻崩溃，但会让它越来越慢、越来越难改。性能和可维护性看起来是两类问题，价值不同：性能决定系统跑得慢不慢，可维护性决定以后改得动改不动。前者用户能感知，后者只有维护的人能感知——但后者往往代价更高。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"性能：跑得慢\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">性能：跑得慢</tspan></text></g><g data-k=\"可维护性：改不动\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">可维护性：改不动</tspan></text></g></svg>","d":40.9},{"t":"性能：看重复 I/O","n":"第一类性能问题是重复的低效操作，最典型的是循环里查数据库、循环里调外部接口。每次都慢一点，累积起来就非常慢。识别方法是看循环体内有没有 I/O 操作。改进方向是批量处理或加缓存。性能问题先看重复 I/O：循环里查数据库、重复调远程接口、没有缓存的重复计算。这三类的共同点是同样的活干了很多遍，而且通常不用改架构就能优化——性价比最高。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"循环内查询\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">循环内查询</tspan></text></g><g data-k=\"重复远程调用\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">重复远程调用</tspan></text></g><g data-k=\"无缓存的重复计算\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">无缓存的重复计算</tspan></text></g></svg>","d":39.4},{"t":"性能：看数据结构","n":"第二类性能问题是数据结构用得不对，比如用列表做频繁查找、在大数据集上做全量扫描。识别方法是看查找和遍历的频率与数据规模。改进方向是换成合适的结构，比如用哈希集合做查找。再看数据结构：用列表做频繁查找、全量扫描找一条记录、重复遍历同一个集合。换成合适的结构（哈希、索引、一次遍历），性能提升常常是数量级的，代码改动却很小。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"列表查找\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">列表查找</tspan></text></g><g data-k=\"全量扫描\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">全量扫描</tspan></text></g><g data-k=\"重复遍历\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">重复遍历</tspan></text></g><g data-k=\"缓存缺失\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">缓存缺失</tspan></text></g></svg>","d":41.7},{"t":"可维护性：坏味道","n":"坏味道包括超长函数、深层嵌套、重复代码、魔法数字、含义不明的命名。它们不导致功能错误，但让下一个人（包括几个月后的你）读不懂、改不动。AI 在识别坏味道上很擅长，因为它见过的模式多。可维护性看坏味道：超长函数、魔法数字、重复代码。它们的危害不是现在跑不动，而是下次改的时候没人敢动——「改不动」比「跑得慢」更拖垮一个项目。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"超长函数\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">超长函数</tspan></text></g><g data-k=\"魔法数字\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">魔法数字</tspan></text></g><g data-k=\"重复代码\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">重复代码</tspan></text></g><g data-k=\"改不动\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">改不动</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":35.1},{"t":"写审查表并改进","n":"把性能问题和坏味道各列三类，写清识别方法和改进方向，形成审查表。用它扫一遍你的模块，按优先级改进。优先处理影响大、改动小的项，别追求一次把所有问题都改完。把发现写进审查表，定优先级再逐项改。别看到什么改什么：先处理影响面大的，再处理容易改的。审查表的价值就在于它把发现变成了有顺序的待办清单。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"查性能\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">查性能</tspan></text></g><g data-k=\"查坏味道\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">查坏味道</tspan></text></g><g data-k=\"定优先级\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">定优先级</tspan></text></g><g data-k=\"逐项改\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">逐项改</tspan></text></g></svg>","d":40.8},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「性能与可维护性审查」。能审查代码的性能与可维护性问题把今天最有价值的三点写进产出物「性能审查表」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：写一份性能与可维护性审查表。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":41.9}],"quiz":[{"q":"下面哪项是典型性能问题？","opts":["循环内反复查询数据库","变量名用了下划线","注释是中文","函数有返回值"],"a":0,"why":"循环内重复 I/O 是典型的性能瓶颈，应批量查询或加缓存。"},{"q":"代码坏味道通常指？","opts":["代码有 bug","结构上有改进空间但不影响当前功能","注释太多","用了新框架"],"a":1,"why":"坏味道指结构性问题，如超长函数、重复代码、魔法数字，短期能用长期难维护。"}],"template":"【性能审查表】\n性能：1____ 2____ 3____\n坏味道：1____ 2____ 3____\n优先改进：____","brief":"【本单元要点】能跑不等于跑得好，能改才叫资产\n【为什么重要】一个循环里反复查询数据库，导致接口越来越慢\n【看完做一件事】写一份性能与可维护性审查表。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M4U5","tier":"core","step":"understand","title":"漏洞分级：什么必须改、什么可缓","video":{"dur":"3.7min","script":["为什么要分级","阻断：不改不能合并","重要：应该尽快改"]},"ppt":{"method":"不是所有问题都要立刻改，但必须分清楚","case":"团队因为纠结命名问题，耽误了修复一个安全漏洞","demo":"分级判定表"},"objective":"给审查发现的问题排优先级","transfer":"能对问题合理分级并决定处理顺序","deliverable":{"type":"document","name":"分级判定表","rubric":["阻断","重要","建议"],"acceptance":"一张表：三级各写判定标准，并给三组真实问题分级。"},"task":"写一份分级判定表并给三组问题分级。","rubric":["三级标准清晰","问题分级合理","有处理顺序"],"vslides":[{"t":"为什么要分级","n":"审查发现问题后，如果所有问题都同等对待，团队会陷入两难：全改来不及，不改不放心。分级的价值就是把有限精力用在风险最高的问题上。三级够用：阻断、重要、建议。审查发现一堆问题却不分级，结果往往是一个都不改——因为看起来都重要。分级就是把「发现」变成「可执行的顺序」，让修复工作能真正启动。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"发现问题\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">发现问题</tspan></text></g><g data-k=\"分级\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">分级</tspan></text></g><g data-k=\"按序处理\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">按序处理</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":35.1},{"t":"阻断：不改不能合并","n":"阻断级是红线问题：安全漏洞、硬编码密钥、逻辑错误导致功能不可用、数据泄漏风险。这类问题必须修复后才能合并或上线，没有商量余地。判断标准是：不改会不会造成严重后果？会，就是阻断。阻断级：不改不能合并。包括安全问题、功能错误、数据风险。这一级没有商量余地，发现一个就挡一次——它是合并前的硬闸门。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"安全问题\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">安全问题</tspan></text></g><g data-k=\"功能错误\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">功能错误</tspan></text></g><g data-k=\"数据风险\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">数据风险</tspan></text></g></svg>","d":37.5},{"t":"重要：应该尽快改","n":"重要级是影响质量但不致命的问题：明显的性能瓶颈、关键路径缺少测试、可维护性严重不足。这类问题应该在这个迭代内改掉，但如果时间紧，可以带 TODO 合并并约定时间。重要级：应该尽快改。性能瓶颈、测试缺失、结构严重问题属于这一档。它们暂时不会出事，但拖久了成本会累积，要排进近期计划而不是无限期搁置。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"性能瓶颈\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">性能瓶颈</tspan></text></g><g data-k=\"测试缺失\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">测试缺失</tspan></text></g><g data-k=\"结构严重问题\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">结构严重问题</tspan></text></g></svg>","d":35.8},{"t":"建议：可以缓","n":"建议级是优化类问题：命名可以更清楚、这段代码可以更短、注释可以更详细。这类问题不阻塞合并，可以放进后续优化。把它们降级，是为了让团队聚焦在真正重要的事上。建议级：可以缓。命名可优化、注释不足这类属于建议。把它们的级别压低很重要，否则会淹没真正要紧的问题——对比一下：硬编码密钥是阻断，命名不佳是建议。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"命名可优化（建议）\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">命名可优化（建议）</tspan></text></g><g data-k=\"硬编码密钥（阻断）\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">硬编码密钥（阻断）</tspan></text></g></svg>","d":39.1},{"t":"写分级判定表","n":"把三级标准写成判定表，配几个你项目里的真实例子。以后审查时先分级再派单：阻断的立刻修，重要的排进迭代，建议的进优化池。这样审查报告才真正可执行。写分级判定表时，每级配一两个真实例子。别人拿这张表就能自己判断级别，不需要每次来问你——标准写清楚，审查才能规模化。这张表也是派单依据，阻断级当天就要有人接。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"阻断\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">阻断</tspan></text></g><g data-k=\"重要\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">重要</tspan></text></g><g data-k=\"建议\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">建议</tspan></text></g><g data-k=\"按序派单\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">按序派单</tspan></text></g></svg>","d":37.2},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「漏洞分级：什么必须改、什么可缓」。能对问题合理分级并决定处理顺序把今天最有价值的三点写进产出物「分级判定表」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：写一份分级判定表并给三组问题分级。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":40.1}],"quiz":[{"q":"硬编码密钥应定为哪一级？","opts":["建议","重要","阻断","不处理"],"a":2,"why":"硬编码密钥属于安全问题，必须阻断合并、立即修复。"},{"q":"分级的主要作用是？","opts":["让报告更好看","决定处理的优先级","增加工作量","替开发者做决定"],"a":1,"why":"分级帮助团队把有限精力先用在风险最高的问题上。"}],"template":"【分级判定表】\n阻断：标准____ 例子____\n重要：标准____ 例子____\n建议：标准____ 例子____","brief":"【本单元要点】不是所有问题都要立刻改，但必须分清楚\n【为什么重要】团队因为纠结命名问题，耽误了修复一个安全漏洞\n【看完做一件事】写一份分级判定表并给三组问题分级。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M4U6","tier":"core","step":"understand","title":"人工复核清单：AI 结论哪里不能信","video":{"dur":"3.9min","script":["结论是线索不是判决","必查一：业务规则","必查二：历史约定"]},"ppt":{"method":"AI 的审查结论是线索，不是判决","case":"AI 报告说「无安全问题」，但人工发现了一处越权","demo":"人工复核卡"},"objective":"列出必须人工验证的点","transfer":"明确 AI 审查结论中必须人工验证的部分","deliverable":{"type":"document","name":"人工复核卡","rubric":["业务规则","历史约定","误报误判","最终签字"],"acceptance":"一页卡：列出四类必须人工验证的点，各写一句验证方法。"},"task":"写一份人工复核卡。","rubric":["四类齐全","有验证方法","强调签字责任"],"vslides":[{"t":"结论是线索不是判决","n":"AI 审查报告给出的是线索：它说有问题的地方值得去看，它说没问题的地方不代表真没问题。把它当成一个勤奋但经验有限的助手，而不是最终裁判。最终判断和签字，始终是人。AI 的审查结论是线索，不是判决。它能快速指出可疑之处，但判不判、改不改、能不能放行，必须人来定。把这一条记牢，就不会把 AI 报告当成免检通行证。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"AI 报告：线索\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">AI 报告：线索</tspan></text></g><g data-k=\"人复核：判决\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">人复核：判决</tspan></text></g></svg>","d":39.6},{"t":"必查一：业务规则","n":"AI 不知道你们的业务规则。它看不出一个计算逻辑是否符合财务口径，也判断不了一个状态流转是否符合审批流程。凡是涉及业务正确性的地方，必须懂业务的人来确认。必查一是业务规则：计算口径、状态流转、审批规则。AI 不知道你们的业务为什么这么定，它会按通用做法判断「这里应该加校验」，而那条校验恰好违反业务规则——这类误判很常见。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"计算口径\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">计算口径</tspan></text></g><g data-k=\"状态流转\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">状态流转</tspan></text></g><g data-k=\"审批规则\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">审批规则</tspan></text></g></svg>","d":38.1},{"t":"必查二：历史约定","n":"代码里有些「奇怪」的写法是为了兼容老系统、修复过某个历史问题。AI 可能把它当坏味道建议改掉，一改就出事。人工复核要确认：这些看似不合理的地方是不是有历史原因。必查二是历史约定：兼容老系统的特殊格式、历史 bug 修复留下的绕行逻辑。这些代码看起来「写法奇怪」，其实背后有原因；AI 建议你「简化」它，反而会把老问题带回来。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"兼容老系统\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">兼容老系统</tspan></text></g><g data-k=\"历史 bug 修复\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">历史 bug 修复</tspan></text></g><g data-k=\"特殊数据格式\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">特殊数据格式</tspan></text></g></svg>","d":36.7},{"t":"必查三：误报与漏报","n":"AI 会误报（把正常代码当问题），也会漏报（没发现真问题）。对误报，判断后直接排除；对漏报，靠你补充业务视角的检查。特别是它说「无问题」的部分，关键路径要自己再看一眼。必查三是误报与漏报：识别 AI 标错的地方，同时补上它没发现的关键点。尤其注意核心路径——AI 可能把大部分精力花在风格问题上，真正的业务风险反而漏了。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"识别误报\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">识别误报</tspan></text></g><g data-k=\"补充漏报\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">补充漏报</tspan></text></g><g data-k=\"关键点自查\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">关键点自查</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":39.1},{"t":"写人工复核卡","n":"把四类必查点写成卡：业务规则、历史约定、误报误判、最终签字。每次拿到 AI 审查报告，按卡复核一遍再签字。这张卡是你对质量负责的具体承诺。把人工复核卡写出「查什么、怎么查、谁签字」三样，它才真正可用。复核不是看一遍报告，而是带着清单逐项验证，最后留下签字和依据。签字那一行写名字和日期，别只写一个「已看」。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"业务规则\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">业务规则</tspan></text></g><g data-k=\"历史约定\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">历史约定</tspan></text></g><g data-k=\"误报漏报\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">误报漏报</tspan></text></g><g data-k=\"人工签字\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">人工签字</tspan></text></g></svg>","d":41.9},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「人工复核清单：AI 结论哪里不能信」。明确 AI 审查结论中必须人工验证的部分把今天最有价值的三点写进产出物「人工复核卡」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：写一份人工复核卡。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":38.9}],"quiz":[{"q":"AI 审查报告说「无问题」时，正确做法是？","opts":["直接合并","人工复核关键业务规则与历史约定","再让 AI 看一遍","加快上线"],"a":1,"why":"AI 可能漏掉业务和历史上下文相关的问题，必须人工复核关键点。"},{"q":"最终合并放行的责任人是？","opts":["AI","写代码的开发者或评审人","工具厂商","测试环境"],"a":1,"why":"签字放行必须由人承担，责任不能外包给 AI。"}],"template":"【人工复核卡】\n业务规则：____\n历史约定：____\n误报漏报：____\n签字人：____","brief":"【本单元要点】AI 的审查结论是线索，不是判决\n【为什么重要】AI 报告说「无安全问题」，但人工发现了一处越权\n【看完做一件事】写一份人工复核卡。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M4U7","tier":"core","step":"spar","title":"陪练：安全专家质疑你的审查结论","video":{"dur":"3.9min","script":["陪练说明","第一轮：注入怎么排除","第二轮：密钥有没有泄漏"]},"ppt":{"method":"安全审查的判断必须能经得起追问","case":"安全专家问「你怎么确认没有注入风险」，你只说「看起来没有」","demo":"质疑应对记录"},"objective":"守住三个关键安全判断","transfer":"面对安全专家质疑能守住关键判断","deliverable":{"type":"document","name":"质疑应对记录","rubric":["质疑点","你的依据","修订"],"acceptance":"一份记录：三轮安全质疑各写质疑点、你的依据、是否需要修订。"},"task":"完成安全专家三轮质疑，记录应对。","rubric":["至少两轮有依据","有修订动作","记录完整"],"vslides":[{"t":"陪练说明","n":"这一轮 AI 扮成安全专家，质疑你的审查结论。他会围绕三个高风险点追问：注入风险怎么排除的、密钥有没有泄漏途径、权限判断是不是完整。你的每个回答都要有依据——具体实现、测试、配置，而不是「我觉得应该没问题」。这一轮 AI 扮安全专家，质疑你的审查结论。它专挑注入、密钥、权限三类追问——这三类最容易「看起来没问题」，也最容易在上线后变成真事故。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"注入\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">注入</tspan></text></g><g data-k=\"密钥\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">密钥</tspan></text></g><g data-k=\"权限\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">权限</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":41.9},{"t":"第一轮：注入怎么排除","n":"他会问某个接口怎么确认没有注入风险。好的回答是展示你用了参数化查询、给出对应的测试用例、说明输入经过校验。如果你只是说「AI 审查说没问题」，这一轮就挂了。要有具体证据。第一轮问注入怎么排除：用了参数化查询没有、输入校验覆盖哪些、有没有对应测试用例。回答要给证据，不能只说「应该没问题」——安全判断最忌讳的就是「应该」。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"参数化查询\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">参数化查询</tspan></text></g><g data-k=\"输入校验\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">输入校验</tspan></text></g><g data-k=\"测试用例\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">测试用例</tspan></text></g></svg>","d":40.8},{"t":"第二轮：密钥有没有泄漏","n":"第二轮问密钥的完整链路：代码里有没有硬编码、日志里会不会打印、错误信息会不会带出、配置怎么管理。你要能回答每一个环节的处理方式。密钥问题只要有一个环节漏了，就等于没处理。第二轮问密钥有没有泄漏：代码里有没有硬编码、日志会不会打印、错误信息会不会带出、配置怎么管理。四个渠道都要答到，漏一个就可能被追问住。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"代码硬编码\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">代码硬编码</tspan></text></g><g data-k=\"日志打印\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">日志打印</tspan></text></g><g data-k=\"错误信息\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">错误信息</tspan></text></g><g data-k=\"配置管理\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">配置管理</tspan></text></g></svg>","d":33.7},{"t":"第三轮：权限是否完整","n":"第三轮问权限：这个接口谁可以访问、有没有越权可能、前端隐藏了按钮但后端是否也校验了。最常见的错误是只做前端控制，后端没校验。回答时要说清后端每一层的鉴权。第三轮问权限是否完整：「前端隐藏了按钮」不算答案，必须说清后端每一层都做了鉴权。前端的限制只是体验，真正的防线在服务端——这个判断说不清，就过不了这一轮。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"前端隐藏按钮\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">前端隐藏按钮</tspan></text></g><g data-k=\"后端逐层鉴权\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">后端逐层鉴权</tspan></text></g></svg>","d":36.3},{"t":"通过标准与修订","n":"通过标准是：三轮里至少两轮给出有依据的回答，任何答不上来的都按建议修订。安全陪练的目标不是赢，而是把风险在上线前问出来。结束后记录三轮质疑和修订动作。通过标准是有依据地回应、遇到真问题诚实修订、全程记录。被安全专家问倒不丢人，丢人的是明明没验证却硬说没问题——这轮的诚实，就是在训练你上线时的判断习惯。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"有依据回应\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">有依据回应</tspan></text></g><g data-k=\"诚实修订\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">诚实修订</tspan></text></g><g data-k=\"记录\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">记录</tspan></text></g></svg>","d":37.7},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「陪练：安全专家质疑你的审查结论」。面对安全专家质疑能守住关键判断把今天最有价值的三点写进产出物「质疑应对记录」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：完成安全专家三轮质疑，记录应对。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":43.1}],"quiz":[{"q":"被问「怎么确认没有注入风险」时，最好的回答是？","opts":["看起来没问题","展示参数化查询的写法和相关测试","问 AI 怎么说","说这是 AI 审查的结论"],"a":1,"why":"用具体实现和测试作为依据，才是可靠的回答。"},{"q":"安全质疑中被问倒时的正确做法是？","opts":["坚持己见","承认不确定并按建议修订","转移话题","结束陪练"],"a":1,"why":"安全领域不确定就是风险，诚实修订才是专业态度。"}],"template":"【质疑应对记录】\n质疑1____ 依据____ 修订____\n质疑2____ 依据____ 修订____\n质疑3____ 依据____ 修订____","brief":"【本单元要点】安全审查的判断必须能经得起追问\n【为什么重要】安全专家问「你怎么确认没有注入风险」，你只说「看起来没有」\n【看完做一件事】完成安全专家三轮质疑，记录应对。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M4U8","tier":"core","step":"todo","title":"M4 实战：完成一份代码审查报告","video":{"dur":"4.1min","script":["实战任务说明","第一步：AI 初审","第二步：安全三扫与补充"]},"ppt":{"method":"把审查方法用在真实代码上，才算掌握","case":"学员为自己的模块完成了一份四级分级的审查报告","demo":"审查报告（可带走）"},"objective":"交付可归档的结构化审查报告","transfer":"独立完成一份完整的代码审查报告","deliverable":{"type":"document","name":"审查报告（可带走）","rubric":["问题清单","分级","修复建议","人工复核结论"],"acceptance":"一份可归档报告：含结构化问题清单、分级、修复建议、人工复核结论。"},"task":"完成一份结构化审查报告并归档。","rubric":["四部分齐全","问题有分级和建议","有人工复核签字"],"vslides":[{"t":"实战任务说明","n":"这一节把 M4 串起来：为一段真实代码（可以是你 M3 生成的模块）完成一份结构化审查报告。你会用到 AI 初审、安全三扫、性能与坏味道检查、分级判定和人工复核。目标是交付一份别人能照着改、主管能追踪的报告。这一节的实战是交付一份可归档的审查报告，把 AI 初审、安全三扫、分级和人工复核串成一条完整流程。用你真实项目里的代码来练——真实代码里才有那些「教科书上没有」的历史约定。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"AI 初审\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">AI 初审</tspan></text></g><g data-k=\"安全三扫\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">安全三扫</tspan></text></g><g data-k=\"分级\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">分级</tspan></text></g><g data-k=\"人工复核\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">人工复核</tspan></text></g><g data-k=\"归档\"><rect x=\"145.3\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">归档</tspan></text></g></svg>","d":45.2},{"t":"第一步：AI 初审","n":"让 AI 按结构化模板生成初审报告，每个问题含位置、级别、描述、修复建议。要求它重点覆盖安全、性能、可维护性。拿到初稿后不要急着用，它只是起点。第一步让 AI 初审，检查它的意见是否位置明确、分级清楚、建议具体。不符合这三条的意见直接删掉——模糊的审查意见进了报告，只会让后面的复核更费劲。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"位置明确\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">位置明确</tspan></text></g><g data-k=\"分级清楚\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">分级清楚</tspan></text></g><g data-k=\"建议具体\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">建议具体</tspan></text></g></svg>","d":40.0},{"t":"第二步：安全三扫与补充","n":"按安全初筛清单人工过一遍注入、密钥、权限，补充 AI 可能漏掉的问题。再扫一遍性能和坏味道。把新发现的问题加进报告，按分级标准定级。第二步做安全三扫与补充：注入、密钥、权限逐项过，再补上性能和坏味道。AI 的初审常常漏掉业务特有的敏感字段，这部分只能靠你熟悉项目的人来补。把补充项单独标出来，让人一眼看到 AI 漏了什么。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"注入\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">注入</tspan></text></g><g data-k=\"密钥\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">密钥</tspan></text></g><g data-k=\"权限\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">权限</tspan></text></g><g data-k=\"性能坏味道\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">性能坏味道</tspan></text></g></svg>","d":44.8},{"t":"第三步：人工复核","n":"按人工复核卡逐项确认：业务规则对不对、有没有历史约定被误判、有没有误报漏报。校准每一条的分级和建议。最后你签字，确认这份报告可以作为放行依据。第三步人工复核：拿 AI 的初稿当素材，逐条校准业务规则、历史约定、误报漏报，最后签字。记住——报告上签的是你的名字，AI 不会替你承担这个责任。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"AI 初稿\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">AI 初稿</tspan></text></g><g data-k=\"人工校准后签字\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">人工校准后签字</tspan></text></g></svg>","d":38.1},{"t":"归档与交付","n":"把校准后的报告归档，问题清单可直接派单修复。这份报告是 M4 的核心产出，也是后面 M5 测试、M6 交付的输入。一份好报告让问题在合并前就暴露，这正是审查的意义。归档交付时，初审记录、补充项、复核结论三样都留着。完整的审查轨迹不只是给现在看——下次有人问「这个决定为什么这么做」，这份归档就是答案。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"初审\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">初审</tspan></text></g><g data-k=\"补充\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">补充</tspan></text></g><g data-k=\"复核\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">复核</tspan></text></g><g data-k=\"归档\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">归档</tspan></text></g></svg>","d":37.7},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「M4 实战：完成一份代码审查报告」。独立完成一份完整的代码审查报告把今天最有价值的三点写进产出物「审查报告（可带走）」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：完成一份结构化审查报告并归档。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":42.2}],"quiz":[{"q":"M4 实战的最终交付是？","opts":["一段新代码","可归档的结构化审查报告","一张截图","一份需求文档"],"a":1,"why":"M4 聚焦审查，交付物是完整、可归档、可执行的审查报告。"},{"q":"审查报告在 AI 生成后，必须经过？","opts":["直接归档","人工复核关键判断后再归档","交给 AI 再看一遍","删除不用"],"a":1,"why":"AI 审查结论必须经人工复核业务与历史上下文，才能作为最终报告归档。"}],"template":"【审查报告】\n审查对象：____\n阻断问题：____\n重要问题：____\n建议问题：____\n人工复核结论：____ 签字：____","brief":"【本单元要点】把审查方法用在真实代码上，才算掌握\n【为什么重要】学员为自己的模块完成了一份四级分级的审查报告\n【看完做一件事】完成一份结构化审查报告并归档。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"}]},{"id":"M5","title":"M5 测试与重构：把 AI 产出变可靠","dims":["dev","tools"],"units":[{"id":"M5U1","tier":"core","step":"understand","title":"AI 生成测试用例的边界","video":{"dur":"4.1min","script":["测试也能交给 AI 起草","AI 擅长：正常路径","人必须补：业务边界"]},"ppt":{"method":"测试能交给 AI 起草，但责任不能","case":"AI 生成的测试全是正常路径，漏掉了关键边界","demo":"测试用例分工表"},"objective":"区分 AI 能生成与必须人工补的用例","transfer":"知道哪些测试用例可交给 AI、哪些要自己补","deliverable":{"type":"document","name":"测试用例分工表","rubric":["AI 擅长","人必须补","共同验收"],"acceptance":"一张表：列出 AI 擅长生成的用例类型、必须人工补的类型、验收方式。"},"task":"写一份测试用例分工表。","rubric":["两类区分清楚","人补类型有理由","有验收方式"],"vslides":[{"t":"测试也能交给 AI 起草","n":"和写代码一样，测试用例也可以让 AI 起草。基于明确的规格，它能快速生成正常路径的测试、常见的边界测试、基本的异常测试。这省下的是最机械的那部分工作。但和写代码一样，起草不等于负责。测试是 AI 参与最安全的环节之一，因为断言能不能过是客观的。但「安全」不等于「可以完全交出去」——AI 起草的是通过的测试，不是真正重要的测试，后者需要你定义。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"规格\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">规格</tspan></text></g><g data-k=\"AI 起草\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">AI 起草</tspan></text></g><g data-k=\"人补充\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">人补充</tspan></text></g><g data-k=\"人验收\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">人验收</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":42.4},{"t":"AI 擅长：正常路径","n":"AI 最擅长的是基于规格生成正常路径测试：输入合法值、验证预期输出。它也能生成常见边界，比如空值、超长值、非法格式。这些用例有明确模式，AI 生成质量不错。你只要给它清晰的规格和验收条件。AI 擅长正常路径和常见边界：给一个规格，它能快速生成覆盖主流程、空值、典型异常的用例。这些有通用模式，它做起来又快又全——先用它把这一层铺满，省下的是机械劳动。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"正常路径\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">正常路径</tspan></text></g><g data-k=\"常见边界\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">常见边界</tspan></text></g><g data-k=\"基本异常\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">基本异常</tspan></text></g></svg>","d":43.1},{"t":"人必须补：业务边界","n":"AI 不知道你们业务的特殊规则。比如「VIP 用户的折扣计算有不同的舍入规则」「月末最后一天的订单走特殊流程」。这些领域特有的边界，只有懂业务的人能想到。漏了它们，测试再漂亮也挡不住线上的问题。业务边界必须人补：跨系统的状态不一致、历史遗留的特殊数据、客户那条例外的规则。这些不在通用模式里，AI 无从知道，只有熟悉业务的人能列出来——这是测试里最值钱的部分。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"业务规则\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">业务规则</tspan></text></g><g data-k=\"历史特殊场景\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">历史特殊场景</tspan></text></g><g data-k=\"跨系统边界\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">跨系统边界</tspan></text></g></svg>","d":42.6},{"t":"人必须补：关键验收","n":"关键路径的验收判定、涉及金额和权限的测试、需要真实数据验证的场景，也必须人把关。这些地方出错代价大，不能靠 AI 的自动生成的断言。人要为这些用例的正确性负责。关键断言必须人确认。AI 会生成一个看起来合理的断言，但它未必抓住了这次改动真正要保证的东西。问自己一句：「如果这条断言通过了，我能不能确信核心行为是对的？」答不上来就重写。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"AI 生成断言（参考）\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">AI 生成断言（参考）</tspan></text></g><g data-k=\"人确认关键断言（负责）\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">人确认关键断言（负责）</tspan></text></g></svg>","d":40.4},{"t":"写分工表","n":"把两类写成分工表：AI 擅长什么、人必须补什么、怎么共同验收。以后写测试先让 AI 起草基线，再由你补业务和关键场景，最后一起验收。这是高效又可靠的测试生产方式。分工表写清楚四件事：AI 起草什么、人补什么、人验收什么、出了问题谁负责。这张表不是推卸责任，而是让每个人——包括 AI——知道自己该做哪一段。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"AI 起草\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">AI 起草</tspan></text></g><g data-k=\"人补业务\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">人补业务</tspan></text></g><g data-k=\"人验收\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">人验收</tspan></text></g><g data-k=\"共同负责\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">共同负责</tspan></text></g></svg>","d":39.1},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「AI 生成测试用例的边界」。知道哪些测试用例可交给 AI、哪些要自己补把今天最有价值的三点写进产出物「测试用例分工表」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：写一份测试用例分工表。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":39.4}],"quiz":[{"q":"哪类测试用例最适合交给 AI？","opts":["基于明确规格的正常路径用例","涉及复杂业务规则的边界","需要领域知识的异常场景","关键路径的验收判定"],"a":0,"why":"规格明确的正常路径用例 AI 擅长生成；业务边界与领域场景需人补充。"},{"q":"为什么必须人工补充部分用例？","opts":["AI 不会写测试","AI 缺少业务上下文，会漏掉领域特有的边界","测试越短越好","AI 生成的测试太规范"],"a":1,"why":"AI 缺少真实业务上下文，容易漏掉领域特有的边界和异常，必须由人补充。"}],"template":"【测试用例分工表】\nAI 擅长：____\n人必须补：____\n验收方式：____","brief":"【本单元要点】测试能交给 AI 起草，但责任不能\n【为什么重要】AI 生成的测试全是正常路径，漏掉了关键边界\n【看完做一件事】写一份测试用例分工表。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M5U2","tier":"core","step":"understand","title":"三类用例生成：正常、边界、异常","video":{"dur":"4.0min","script":["一次生成三类","指令怎么写","正常用例：代表分支"]},"ppt":{"method":"用例集要覆盖正常、边界、异常三张网","case":"AI 一次生成了覆盖三类的完整用例集","demo":"测试用例集"},"objective":"让 AI 生成完整用例集","transfer":"能用结构化指令生成三类完整用例","deliverable":{"type":"document","name":"测试用例集","rubric":["正常用例","边界用例","异常用例"],"acceptance":"一份用例集：三类各至少三条，每条含输入与预期结果。"},"task":"为一个真实函数生成三类用例集。","rubric":["三类齐全","每条有输入与预期","含业务边界"],"vslides":[{"t":"一次生成三类","n":"与其零散地让 AI「再补个测试」，不如一次给它结构化指令，让它按正常、边界、异常三类生成完整用例集。这样不容易遗漏，也方便你一眼看出覆盖是否均衡。正常、边界、异常三类一次生成，比分三次各写一遍效率高，也更容易看出用例之间的重叠和空缺。一次把它们摊开，你会发现完整用例集的模样。三类的分界线写清楚，AI 才不会把边界混进正常用例。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"正常\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">正常</tspan></text></g><g data-k=\"边界\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">边界</tspan></text></g><g data-k=\"异常\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">异常</tspan></text></g><g data-k=\"完整用例集\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"76.4\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">完整用例</tspan><tspan x=\"341.8\" dy=\"16.900000000000002\">集</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":38.8},{"t":"指令怎么写","n":"指令要说清四件事：被测对象是什么、按哪三类生成、每条用例包含哪些字段、用什么格式输出。比如「为这个函数按正常/边界/异常三类生成用例，每条含输入、预期结果、覆盖点，用表格输出」。指令里要说清四样：被测对象是什么、三类怎么划分、每条用例要哪些字段、结果按什么格式输出。格式要求尤其重要——统一格式的输出才能直接变成可执行的测试代码。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"被测对象\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">被测对象</tspan></text></g><g data-k=\"三类划分\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">三类划分</tspan></text></g><g data-k=\"字段要求\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">字段要求</tspan></text></g><g data-k=\"输出格式\"><g><circle cx=\"30\" cy=\"154\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 154 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"158.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">输出格式</tspan></text></g></svg>","d":39.6},{"t":"正常用例：代表分支","n":"正常用例不必穷举所有合法输入，挑能代表不同分支的几条即可。比如一个折扣函数，正常用例要覆盖「普通用户」「VIP 用户」「大额订单」三条不同分支。目标是验证每条主路径都通。正常用例要覆盖代表分支，不是把主路径重复三遍。挑那些走不同判断分支的输入，每条对应一种典型情况——三条有代表性的用例，胜过十条几乎一样的用例。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"主路径1\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">主路径1</tspan></text></g><g data-k=\"主路径2\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">主路径2</tspan></text></g><g data-k=\"主路径3\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">主路径3</tspan></text></g></svg>","d":41.7},{"t":"边界与异常用例","n":"边界用例覆盖空值、临界值、超长、重复。异常用例覆盖非法格式、依赖失败、权限不足。这两类最容易漏，也最能发现问题。生成后你要人工补上业务特有的场景，形成最终用例集。边界用例盯空值和临界值，异常用例盯依赖失败和越权。前者测「刚好超出范围」，后者测「外部不配合时会怎样」。两类加起来，才是用户真实会遇到的世界。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"空值与临界（边界）\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">空值与临界（边界）</tspan></text></g><g data-k=\"依赖失败与越权（异常）\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">依赖失败与越权（异常）</tspan></text></g></svg>","d":40.6},{"t":"生成与执行","n":"拿到用例集后，让 AI 基于它生成测试代码，然后实际运行。通过的用例记录为基线，失败的用例分析是代码问题还是用例写错了。这份用例集既是这次的测试依据，也是后续回归的资产。生成用例后让 AI 同时生成测试代码，运行一遍，记录基线。基线很重要：以后每次改动都要和它比——测试不再是「这次通过了」，而是「和上次一样通过」。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"生成用例\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">生成用例</tspan></text></g><g data-k=\"生成测试\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">生成测试</tspan></text></g><g data-k=\"运行\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">运行</tspan></text></g><g data-k=\"记录基线\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">记录基线</tspan></text></g></svg>","d":37.7},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「三类用例生成：正常、边界、异常」。能用结构化指令生成三类完整用例把今天最有价值的三点写进产出物「测试用例集」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：为一个真实函数生成三类用例集。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":39.5}],"quiz":[{"q":"让 AI 生成用例集时，最有效的指令是？","opts":["多写点测试","按正常、边界、异常三类各生成用例，每条写清输入与预期结果","随便生成","只写正常情况"],"a":1,"why":"明确分类与字段的指令才能得到结构完整、可执行的用例集。"},{"q":"完整用例集应该覆盖？","opts":["只有正常路径","正常、边界、异常三类","只有异常情况","只看代码行数"],"a":1,"why":"三类覆盖才能有效发现不同层面的问题。"}],"template":"【测试用例集】\n正常：1____ 2____ 3____\n边界：1____ 2____ 3____\n异常：1____ 2____ 3____\n（每条写输入与预期）","brief":"【本单元要点】用例集要覆盖正常、边界、异常三张网\n【为什么重要】AI 一次生成了覆盖三类的完整用例集\n【看完做一件事】为一个真实函数生成三类用例集。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M5U3","tier":"core","step":"understand","title":"覆盖率补漏","video":{"dur":"4.1min","script":["覆盖率的正确用法","让 AI 分析未覆盖路径","判断哪些必须补"]},"ppt":{"method":"覆盖率不是目标，未覆盖的关键路径才是","case":"覆盖率 85%，但恰好漏了一个关键分支","demo":"覆盖率分析表"},"objective":"找出未覆盖路径并补测","transfer":"能用覆盖率信息找到并补齐未测路径","deliverable":{"type":"document","name":"覆盖率分析表","rubric":["覆盖数据","未覆盖路径","补测计划"],"acceptance":"一张表：写出覆盖率数据、未覆盖的关键路径、补测计划。"},"task":"写一份覆盖率分析表。","rubric":["有覆盖率数据","指出未覆盖路径","有补测计划"],"vslides":[{"t":"覆盖率的正确用法","n":"很多人把覆盖率当 KPI，追到 90% 就觉得万事大吉。其实覆盖率只是一个探针：它告诉你哪些代码路径没被测到。真正重要的是那些未覆盖的路径里有没有关键逻辑。一个 85% 覆盖率但漏了核心分支的项目，比 80% 但覆盖了所有关键路径的项目更危险。覆盖率是个指示器，不是目标本身。追数字很容易：写一堆没有断言的测试就能把数字刷上去。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"追数字（形式）\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">追数字（形式）</tspan></text></g><g data-k=\"找关键未测路径（实质）\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">找关键未测路径（实质）</tspan></text></g></svg>","d":41.9},{"t":"让 AI 分析未覆盖路径","n":"把覆盖率报告交给 AI，让它指出未覆盖的分支，并解释每个分支的业务含义。AI 能快速把「第 47 行未覆盖」翻译成「用户余额不足的分支没测」。这个翻译很有价值，让你快速判断该不该补。让 AI 把覆盖率报告翻译成人话：哪几个分支没覆盖、这些分支分别做什么、可能有什么后果。它擅长把报告里的行列转换成可读的描述，判断关键性则是你的活。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"覆盖率报告\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">覆盖率报告</tspan></text></g><g data-k=\"AI 翻译\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">AI 翻译</tspan></text></g><g data-k=\"判断关键性\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">判断关键性</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":41.7},{"t":"判断哪些必须补","n":"不是所有未覆盖都要补。判断标准：这个分支涉及金额、权限、状态流转吗？出错后果严重吗？是核心业务流程吗？是，就必须补；只是日志打印、兜底提示这类，可以缓。把精力用在关键路径上。判断哪些必须补，看三条：涉及金额或权限的、出错后果严重的、属于核心流程的。三条中有一条就补。反之，一些边缘的日志分支不补也可以——把精力放在真正要紧的地方。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"涉及金额权限\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">涉及金额权限</tspan></text></g><g data-k=\"后果严重\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">后果严重</tspan></text></g><g data-k=\"核心流程\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">核心流程</tspan></text></g></svg>","d":46.2},{"t":"补测与复测","n":"对必须补的路径，让 AI 生成对应用例，你确认断言的正确性，然后运行。补完后重新看覆盖率变化，确认目标路径已被覆盖。分析、补测、复测形成一个闭环。补测之后要复测，并确认断言是对的。补一条断言写错的用例，覆盖率上去了，保护反而变差了——它会给你虚假的安全感，比没有测试更危险。复测通过后再更新基线，别让旧基线留在报告里。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"分析\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">分析</tspan></text></g><g data-k=\"补测\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">补测</tspan></text></g><g data-k=\"确认断言\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">确认断言</tspan></text></g><g data-k=\"复测\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">复测</tspan></text></g></svg>","d":39.4},{"t":"写覆盖率分析表","n":"把这次分析写成表：当前覆盖率、未覆盖的关键路径、补测计划、复测结果。这张表让覆盖率从数字变成行动。记住目标不是某个百分比，而是所有关键路径都有测试守着。写覆盖率分析表时，除了记录补了什么，也写下「哪些没补、为什么不补」。这份记录将来评审时能回答「为什么这里没测」——有理由的省略和忘了测，是两回事。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"分析未覆盖\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">分析未覆盖</tspan></text></g><g data-k=\"判断关键\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">判断关键</tspan></text></g><g data-k=\"补测\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">补测</tspan></text></g><g data-k=\"复测\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">复测</tspan></text></g></svg>","d":38.9},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「覆盖率补漏」。能用覆盖率信息找到并补齐未测路径把今天最有价值的三点写进产出物「覆盖率分析表」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：写一份覆盖率分析表。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":35.1}],"quiz":[{"q":"关于测试覆盖率，正确的理解是？","opts":["越高越说明代码没问题","是发现未测路径的工具，不是质量目标","等于测试质量","不用关注"],"a":1,"why":"覆盖率帮助定位未测路径，但高覆盖率不等于高测试质量，关键在覆盖的内容。"},{"q":"发现覆盖率没覆盖某个分支时，应？","opts":["忽略","判断该分支是否关键，是则补测","降低覆盖率目标","删掉该分支"],"a":1,"why":"应评估分支重要性，对关键路径补测，而不是单纯追求数字。"}],"template":"【覆盖率分析表】\n当前覆盖率：____\n未覆盖关键路径：____\n补测计划：____\n复测结果：____","brief":"【本单元要点】覆盖率不是目标，未覆盖的关键路径才是\n【为什么重要】覆盖率 85%，但恰好漏了一个关键分支\n【看完做一件事】写一份覆盖率分析表。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M5U4","tier":"core","step":"understand","title":"让 AI 读懂失败用例并给修复建议","video":{"dur":"4.0min","script":["失败是线索不是麻烦","给足上下文","AI 给的是假设"]},"ppt":{"method":"测试失败不是坏消息，是定位问题的线索","case":"AI 从一段堆栈信息定位到空值未处理","demo":"失败分析记录"},"objective":"从失败反推代码问题","transfer":"能把失败用例交给 AI 分析并定位根因","deliverable":{"type":"document","name":"失败分析记录","rubric":["失败信息","AI 分析","根因确认","修复"],"acceptance":"一份记录：写清失败信息、AI 分析、你确认的根因、修复动作。"},"task":"用 AI 分析一个真实的测试失败并定位根因。","rubric":["有真实失败信息","根因确认有依据","有修复动作"],"vslides":[{"t":"失败是线索不是麻烦","n":"测试失败时，第一反应不应该是「怎么让它通过」，而是「它在告诉我什么」。失败信息里藏着问题的位置与原因。AI 擅长读堆栈、对照代码、给出可能的原因清单，这能大大加速定位。失败是用例在给你递线索，不是麻烦。它精确告诉你「哪一步和预期不一样」，比你自己猜哪里出错高效得多。心态上把失败当成信息源，调试效率会明显提升。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"失败\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">失败</tspan></text></g><g data-k=\"给上下文\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">给上下文</tspan></text></g><g data-k=\"AI 分析\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">AI 分析</tspan></text></g><g data-k=\"定位根因\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">定位根因</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":38.1},{"t":"给足上下文","n":"让 AI 分析失败，要给它三样东西：完整的失败信息和堆栈、失败的用例输入与预期、相关的代码。上下文越全，分析越准。只说「测试挂了」是得不到有用答案的。给 AI 的上下文要足：失败堆栈、用例的输入输出、相关代码三段缺一不可。只贴堆栈，它只能猜；三段都在，它能把「输入触发了哪条路径、在哪一步偏离预期」串起来。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"失败堆栈\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">失败堆栈</tspan></text></g><g data-k=\"用例输入输出\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用例输入输出</tspan></text></g><g data-k=\"相关代码\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">相关代码</tspan></text></g></svg>","d":40.3},{"t":"AI 给的是假设","n":"AI 给出的原因清单是假设，不是结论。你要逐条验证：这个原因和失败现象对得上吗？改了之后测试能过吗？特别是它给出的多个原因，别只看第一个就直接改。验证过的原因才是根因。AI 给的是假设，不是根因。它常给两三种可能，你的任务是一一验证：改一个小地方、重跑、看结果。验证过的假设才能升级成根因，没验证就动手改，容易把问题从一个地方挪到另一个地方。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"假设1\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">假设1</tspan></text></g><g data-k=\"验证\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">验证</tspan></text></g><g data-k=\"假设2\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">假设2</tspan></text></g><g data-k=\"验证\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">验证</tspan></text></g></svg>","d":44.3},{"t":"区分代码问题和用例问题","n":"失败不一定是代码的错，也可能是用例写错了：预期值设错、测试环境不对、依赖没准备好。让 AI 同时判断是代码问题还是用例问题。判断错了会改错地方，越改越乱。先区分代码问题和用例问题。有时失败是因为断言写错了、期望值本身不对，改代码反而会改坏正确的逻辑。判断标准是：对照需求看，到底是实现偏离了需求，还是用例写错了需求。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"代码有 bug\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">代码有 bug</tspan></text></g><g data-k=\"用例本身写错\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">用例本身写错</tspan></text></g></svg>","d":40.5},{"t":"记录并修复","n":"把分析过程记下来：失败信息、AI 的假设、你验证后的根因、修复动作。这份记录让一次失败变成可复用的经验。下次遇到类似失败，你能更快定位。把失败信息、AI 假设、确认的根因、修复方式记下来。积累几次之后，你会看到自己在哪类问题上容易判断失误——这份记录是比任何教材都贴合你的学习材料。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"失败信息\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">失败信息</tspan></text></g><g data-k=\"AI 假设\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">AI 假设</tspan></text></g><g data-k=\"确认根因\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">确认根因</tspan></text></g><g data-k=\"修复\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">修复</tspan></text></g></svg>","d":37.0},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「让 AI 读懂失败用例并给修复建议」。能把失败用例交给 AI 分析并定位根因把今天最有价值的三点写进产出物「失败分析记录」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：用 AI 分析一个真实的测试失败并定位根因。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":40.5}],"quiz":[{"q":"测试失败后，正确做法是？","opts":["删掉失败的测试","把断言改松让它通过","分析失败原因并修复代码","忽略它"],"a":2,"why":"失败说明代码或用例有问题，应分析根因并修复，而不是掩盖失败。"},{"q":"让 AI 分析失败时，最该提供的是？","opts":["只说「测试挂了」","堆栈信息、失败用例、相关代码","测试的文件名","代码行数"],"a":1,"why":"提供充分的上下文，AI 才能准确定位根因。"}],"template":"【失败分析记录】\n失败信息：____\nAI 分析：____\n确认根因：____\n修复动作：____","brief":"【本单元要点】测试失败不是坏消息，是定位问题的线索\n【为什么重要】AI 从一段堆栈信息定位到空值未处理\n【看完做一件事】用 AI 分析一个真实的测试失败并定位根因。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M5U5","tier":"core","step":"understand","title":"遗留代码重构：先测后改","video":{"dur":"4.1min","script":["重构的风险","第一步：建立行为基线","第二步：小步重构"]},"ppt":{"method":"没有测试保护的重构，等于蒙眼改代码","case":"重构后功能悄悄变了，因为缺少测试护栏","demo":"重构前后对照"},"objective":"在不破坏行为前提下重构","transfer":"能按先测后改的安全流程重构遗留代码","deliverable":{"type":"document","name":"重构前后对照","rubric":["测试护栏","重构动作","行为验证"],"acceptance":"一页对照：写清重构前的测试护栏、重构动作、重构后的行为验证。"},"task":"写一份重构前后对照并标注测试护栏。","rubric":["有测试护栏","行为未改变","有验证结论"],"vslides":[{"t":"重构的风险","n":"遗留代码往往缺少测试、逻辑复杂、没人敢动。但正因为没人动，它越来越烂。重构能改善它，但风险是改着改着行为变了，而且你不知道。安全的做法只有一个：先建立测试护栏，再动结构。重构最大的风险是「改坏了原来能用的东西」。没有测试护栏的重构等于蒙着眼改代码——你以为只是调了结构，实际上某个隐藏行为已经被改掉，要等上线才暴露。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"无测试改动（危险）\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">无测试改动（危险）</tspan></text></g><g data-k=\"有测试护栏（安全）\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">有测试护栏（安全）</tspan></text></g></svg>","d":39.6},{"t":"第一步：建立行为基线","n":"在改任何东西之前，先为现有代码补测试，记录当前行为——包括那些看起来奇怪但可能有意的行为。这些测试是护栏：只要重构后它们全过，就说明行为没变。这一步不能省。第一步建立行为基线：补测试覆盖主要行为，包括那些「奇怪但一直如此」的行为。这些看似不合理的地方往往是历史约定，改掉它就会破坏兼容性。测试全绿，才有资格动结构。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"覆盖主要行为\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">覆盖主要行为</tspan></text></g><g data-k=\"记录奇怪行为\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记录奇怪行为</tspan></text></g><g data-k=\"测试全部通过\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">测试全部通过</tspan></text></g></svg>","d":39.4},{"t":"第二步：小步重构","n":"一次只改一个小点：提取一个函数、改一个命名、拆一层嵌套。每改一步就跑一遍测试，全过才继续。小步的好处是出问题能立刻定位到刚才那一步。大步重构一旦失败，往往很难回退。第二步小步重构：补一条测试、改一小处、跑测试、再改下一处。每一步都能立刻知道有没有改坏。这种节奏看着慢，实际上比「大改一次再debug半天」快得多。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"补测试\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">补测试</tspan></text></g><g data-k=\"小步改\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">小步改</tspan></text></g><g data-k=\"跑测试\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">跑测试</tspan></text></g><g data-k=\"再改\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">再改</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":42.8},{"t":"让 AI 辅助重构","n":"让 AI 帮你识别可以提取的函数、可以改善的命名、可以简化的结构，但每次只接受一个改动并立刻验证。不要让 AI 一次性重写整个文件——那样你无法确认行为是否保持。让 AI 辅助时，让它一次只识别一个改进点，别让它一口气重写整个文件。一次一处、立即验证，是人和 AI 配合重构最稳的方式——它的建议常常都对，但一次全改你无法分辨哪个改动引入了问题。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"识别改进点\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">识别改进点</tspan></text></g><g data-k=\"一次一处\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">一次一处</tspan></text></g><g data-k=\"立即验证\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">立即验证</tspan></text></g></svg>","d":40.8},{"t":"写重构对照","n":"把重构前后写成对照：改了哪些结构、测试护栏是什么、行为是否保持不变。这份对照证明你的重构是安全的。记住：重构的价值是让代码更好改，而不是让它看起来更漂亮。写重构对照时，记下基线、每步改动、验证结果。这份记录能回答两个问题：重构前后行为是否一致、每一步改动是否必要。它也是下一个人理解这段代码的入口。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"建基线\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">建基线</tspan></text></g><g data-k=\"小步改\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">小步改</tspan></text></g><g data-k=\"每步验证\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">每步验证</tspan></text></g><g data-k=\"记录\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">记录</tspan></text></g></svg>","d":41.2},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「遗留代码重构：先测后改」。能按先测后改的安全流程重构遗留代码把今天最有价值的三点写进产出物「重构前后对照」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：写一份重构前后对照并标注测试护栏。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":43.1}],"quiz":[{"q":"重构遗留代码前，第一步应该是？","opts":["直接改结构","先补测试保护现有行为","删掉重写","改完再说"],"a":1,"why":"先补测试建立行为基线，才能在重构后验证行为没有改变。"},{"q":"重构的基本原则是？","opts":["改变外部行为","只改内部结构，不改变外部行为","让代码更短就行","增加新功能"],"a":1,"why":"重构的定义就是在不改变外部行为的前提下改善内部结构。"}],"template":"【重构前后对照】\n测试护栏：____\n重构动作：1____ 2____\n行为验证：____\n结论：____","brief":"【本单元要点】没有测试保护的重构，等于蒙眼改代码\n【为什么重要】重构后功能悄悄变了，因为缺少测试护栏\n【看完做一件事】写一份重构前后对照并标注测试护栏。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M5U6","tier":"core","step":"understand","title":"测试代码也要审","video":{"dur":"3.9min","script":["为什么测试也要审","检查一：断言是否有效","检查二：覆盖是否真实"]},"ppt":{"method":"不可靠的测试比没有测试更危险","case":"AI 生成的测试断言写成了恒真，永远通过","demo":"测试审查清单"},"objective":"检查 AI 生成测试的可靠性","transfer":"能审查测试代码本身是否可靠","deliverable":{"type":"document","name":"测试审查清单","rubric":["断言有效","覆盖真实","无恒真"],"acceptance":"一张清单：列出审查测试代码的检查项，用它审查一段 AI 生成的测试。"},"task":"写一份测试审查清单。","rubric":["检查项具体","强调断言有效","审查了真实测试"],"vslides":[{"t":"为什么测试也要审","n":"很多人觉得测试代码不重要，AI 生成的测试拿来就用。但一段不可靠的测试比没有测试更危险：它会给你虚假的安全感。最典型的坏情况是断言恒真——测试永远通过，实际上什么都没验证。所以测试代码同样要审。测试代码也要审，因为它可能是假的通过。最典型的坑是恒真断言——写了个断言永远成立，测试永远绿，但什么都没验证。这种测试比没有测试更有害，因为它制造了安全感。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"恒真断言：虚假通过\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">恒真断言：虚假通过</tspan></text></g><g data-k=\"有效断言：真检验\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">有效断言：真检验</tspan></text></g></svg>","d":41.0},{"t":"检查一：断言是否有效","n":"看断言是不是真的在检验预期行为。警惕几种坏模式：assertTrue(True) 这类恒真断言、只验证「没有抛异常」而不验证结果、断言写得太松（比如只检查返回值非空）。好的断言要精确验证预期值。检查断言是否有效：把断言故意改错，看测试会不会失败。会失败才是真断言；不会失败，说明它恒真或者根本没执行到。这一步叫「变异检查」，是最直接的验证办法。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"非恒真\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">非恒真</tspan></text></g><g data-k=\"验证具体结果\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">验证具体结果</tspan></text></g><g data-k=\"断言足够严格\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">断言足够严格</tspan></text></g></svg>","d":46.0},{"t":"检查二：覆盖是否真实","n":"看测试是不是真的覆盖了声称的场景。比如命名为「空值测试」的用例，输入却是合法值。还有测试之间互相依赖、依赖真实外部环境导致结果不稳定。这些都会让测试失去价值。检查覆盖是否真实：用例名说测的是 A，实际断言的是 B；用例依赖外部服务，换个环境就跑不过。名实相符、可重复运行，是测试可信的基本条件。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"名实相符\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">名实相符</tspan></text></g><g data-k=\"无外部依赖\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">无外部依赖</tspan></text></g><g data-k=\"可重复运行\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">可重复运行</tspan></text></g></svg>","d":37.7},{"t":"检查三：是否过度拟合","n":"AI 有时会让测试去迁就当前代码的实现细节，而不是验证需求。比如断言某个内部方法的调用次数。这种测试在代码重构时会大量失败，即使行为是对的。好的测试验证行为，不验证实现。检查是否过度拟合：好的测试验证行为，不验证实现细节。如果一重构就有一堆测试失败，而功能其实没变，说明测试绑死了实现——它会让后续重构举步维艰。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"验证行为\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">验证行为</tspan></text></g><g data-k=\"不验实现\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">不验实现</tspan></text></g><g data-k=\"重构友好\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">重构友好</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":37.7},{"t":"写测试审查清单","n":"把三类检查写成清单：断言有效、覆盖真实、不过度拟合。每次接受 AI 生成的测试前过一遍。可靠的测试是重构和交付的信心来源，值得你花时间审查。把三条写成测试审查清单，AI 生成的测试先过一遍清单再合入。这一步花不了几分钟，但能挡掉「绿测试、真缺陷」这类最难发现的问题。审查记录留档，下次 AI 生成测试时直接对照。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"断言有效\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">断言有效</tspan></text></g><g data-k=\"覆盖真实\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">覆盖真实</tspan></text></g><g data-k=\"不过度拟合\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">不过度拟合</tspan></text></g></svg>","d":39.9},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「测试代码也要审」。能审查测试代码本身是否可靠把今天最有价值的三点写进产出物「测试审查清单」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：写一份测试审查清单。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":34.2}],"quiz":[{"q":"下面哪项是测试代码最严重的问题？","opts":["命名不好看","断言恒真，永远通过","注释是中文","测试文件太长"],"a":1,"why":"恒真断言让测试失去意义，给人虚假的安全感，比没有测试更危险。"},{"q":"审查测试代码时，最重要的是确认？","opts":["代码行数","断言确实检验了预期行为","用了什么框架","运行速度"],"a":1,"why":"测试的价值在于断言能真实检验行为，其他都是次要的。"}],"template":"【测试审查清单】\n断言有效：____\n覆盖真实：____\n不过度拟合：____\n审查结论：____","brief":"【本单元要点】不可靠的测试比没有测试更危险\n【为什么重要】AI 生成的测试断言写成了恒真，永远通过\n【看完做一件事】写一份测试审查清单。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M5U7","tier":"core","step":"spar","title":"陪练：QA 追问覆盖率与边界","video":{"dur":"3.8min","script":["陪练说明","第一轮：覆盖率数据","第二轮：边界场景"]},"ppt":{"method":"质量不是感觉，是能用数据证明的","case":"QA 问「你怎么证明边界都覆盖了」，你只说「应该都测了」","demo":"QA 对话记录"},"objective":"用数据回应三轮质量质疑","transfer":"面对 QA 质疑能用测试和数据回应","deliverable":{"type":"document","name":"QA 对话记录","rubric":["质疑点","你的数据","补测"],"acceptance":"一份记录：三轮质疑各写质疑点、你用的数据、补测动作。"},"task":"完成三轮 QA 质疑并记录。","rubric":["至少两轮用数据回应","有补测动作","记录完整"],"vslides":[{"t":"陪练说明","n":"这一轮 AI 扮成 QA，追问你的测试质量。他会问三个方向：覆盖率数据、边界场景、异常路径。你的回答要用数据说话——用例清单、覆盖率报告、测试结果，而不是「应该都测了」。答不上来的地方，现场承认并补测。这一轮 AI 扮 QA，用数据追问你的覆盖率、边界和异常路径。真实评审里 QA 不问「你觉得怎么样」，只问「覆盖率多少、哪些没测、为什么」——这一轮就是提前适应这种问法。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"覆盖率\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">覆盖率</tspan></text></g><g data-k=\"边界\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">边界</tspan></text></g><g data-k=\"异常\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">异常</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":42.4},{"t":"第一轮：覆盖率数据","n":"他会问覆盖率多少、哪些路径没覆盖。好的回答是拿出覆盖率报告，说明数字，并解释未覆盖路径为什么不关键（或者承认需要补）。含糊的「挺高的」不算回答。第一轮给覆盖率数据：具体数字、未覆盖的关键路径、补测计划。别只报一个百分比，要说清「80% 覆盖的是哪些、剩下 20% 里哪些要紧」——QA 关心的是风险分布，不是数字本身。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"具体数字\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">具体数字</tspan></text></g><g data-k=\"未覆盖说明\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">未覆盖说明</tspan></text></g><g data-k=\"补测计划\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">补测计划</tspan></text></g></svg>","d":37.0},{"t":"第二轮：边界场景","n":"第二轮挑一个边界问你怎么测的。你要能说出具体用例：空值、临界值、超长、重复，以及对应的预期结果。如果是业务特有的边界，更要讲清它的来源。只有清单具体，QA 才会认可。第二轮讲边界场景：空值、临界值、超长和业务特有的边界。业务边界这一项最容易被漏，也最容易被追问——它是你熟悉业务的优势所在，要主动讲。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"空值\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">空值</tspan></text></g><g data-k=\"临界值\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">临界值</tspan></text></g><g data-k=\"超长\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">超长</tspan></text></g><g data-k=\"业务边界\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">业务边界</tspan></text></g></svg>","d":36.5},{"t":"第三轮：异常路径","n":"第三轮问异常：依赖超时怎么办、权限不足怎么办、并发冲突怎么办。你要展示异常用例和处理逻辑。特别注意：如果某个异常场景你确实没测，诚实承认并当场补一条用例，这比硬撑强。第三轮讲异常路径。「应该没问题」在这里是无效回答，要展示异常用例和处理结果：依赖失败时返回什么、越权时怎么拦截、重试策略是什么。有证据才过得去。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"应该没问题（无依据）\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">应该没问题（无依据）</tspan></text></g><g data-k=\"展示异常用例与处理\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">展示异常用例与处理</tspan></text></g></svg>","d":37.2},{"t":"通过标准与补测","n":"通过标准是：至少两轮用具体数据回应，对答不上来的能补测。结束后记录三轮质疑和你补的测试。QA 陪练的目标不是难倒你，而是让交付前的质量盲点暴露出来。通过标准是数据回应、承认盲点、当场补测、记录全过程。被问到没测的地方就承认并补上——QA 要的是可靠，不是完美；诚实加行动比嘴硬更能建立信任。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"数据回应\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">数据回应</tspan></text></g><g data-k=\"承认盲点\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">承认盲点</tspan></text></g><g data-k=\"当场补测\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">当场补测</tspan></text></g><g data-k=\"记录\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">记录</tspan></text></g></svg>","d":36.3},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「陪练：QA 追问覆盖率与边界」。面对 QA 质疑能用测试和数据回应把今天最有价值的三点写进产出物「QA 对话记录」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：完成三轮 QA 质疑并记录。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":38.5}],"quiz":[{"q":"被问「怎么证明边界都覆盖了」时，最好的回答是？","opts":["应该都测了","展示边界用例清单和覆盖率报告，逐个说明","QA 不该问这个","测试跑过就行"],"a":1,"why":"用清单和数据具体回应，才能证明覆盖，而不是靠感觉。"},{"q":"QA 陪练的核心价值是？","opts":["让测试变多","在交付前用质疑发现质量盲点","证明开发很辛苦","减少代码量"],"a":1,"why":"QA 通过质疑暴露质量盲点，是交付前的重要闸门。"}],"template":"【QA 对话记录】\n质疑1____ 数据____ 补测____\n质疑2____ 数据____ 补测____\n质疑3____ 数据____ 补测____","brief":"【本单元要点】质量不是感觉，是能用数据证明的\n【为什么重要】QA 问「你怎么证明边界都覆盖了」，你只说「应该都测了」\n【看完做一件事】完成三轮 QA 质疑并记录。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M5U8","tier":"core","step":"todo","title":"M5 实战：给模块补齐测试","video":{"dur":"4.0min","script":["实战任务说明","第一步：生成三类用例","第二步：生成测试并补漏"]},"ppt":{"method":"把测试方法用在真实模块上，才算学会","case":"学员为 M3 模块补齐测试，覆盖率达到约定阈值","demo":"测试集（可带走）"},"objective":"交付达到 coverage 阈值的测试集","transfer":"独立为模块补齐测试并通过验收","deliverable":{"type":"document","name":"测试集（可带走）","rubric":["测试用例","测试代码","覆盖率报告","审查结论"],"acceptance":"一套完整测试：含用例集、测试代码、覆盖率报告、测试审查结论。"},"task":"为你的模块补齐测试并交付。","rubric":["三类用例齐全","覆盖率达标","测试经过审查"],"vslides":[{"t":"实战任务说明","n":"这一节把 M5 串起来：为你 M3 生成的模块补齐测试。你会用到用例分工、三类用例生成、覆盖率补漏、失败分析和测试审查。目标是交付一套可靠、可审查、有覆盖率证明的测试集。这一节的实战是给模块补齐测试并交付测试集。用前面生成审查过的那个模块继续做——真实项目里测试就是跟着代码一路补的，不是单独存在的一个练习。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"分工\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">分工</tspan></text></g><g data-k=\"生成用例\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">生成用例</tspan></text></g><g data-k=\"补漏\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">补漏</tspan></text></g><g data-k=\"失败分析\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">失败分析</tspan></text></g><g data-k=\"审查\"><rect x=\"145.3\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">审查</tspan></text></g></svg>","d":43.1},{"t":"第一步：生成三类用例","n":"基于模块规格，让 AI 按正常、边界、异常三类生成用例集，你补上业务特有的边界。为每条用例确认预期结果的正确性。这是测试的地基。第一步生成三类用例，检查是否齐全、业务边界有没有覆盖、预期结果写得对不对。缺任何一类都先补齐再往下走——用例层漏了，后面的测试代码写得再漂亮也没用。用例写清预期结果，后面生成断言才有依据。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"三类齐全\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">三类齐全</tspan></text></g><g data-k=\"业务边界\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">业务边界</tspan></text></g><g data-k=\"预期正确\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">预期正确</tspan></text></g></svg>","d":40.8},{"t":"第二步：生成测试并补漏","n":"让 AI 基于用例集生成测试代码，运行后分析失败。按覆盖率报告找出未覆盖的关键路径并补测。反复直到关键路径都有测试守住。第二步生成测试代码并运行，分析失败、补漏、复测。失败时先判断是代码问题还是用例问题，别急着改代码——这一步的判断习惯比测试结果本身更重要。这份判断记录，比测试通过本身更能说明你的能力。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"生成代码\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">生成代码</tspan></text></g><g data-k=\"运行\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">运行</tspan></text></g><g data-k=\"补漏\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">补漏</tspan></text></g><g data-k=\"复测\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">复测</tspan></text></g></svg>","d":40.1},{"t":"第三步：审查测试代码","n":"按测试审查清单过一遍：断言是否有效、覆盖是否真实、有没有过度拟合实现细节。修正不可靠的测试。记住不可靠的测试比没有更危险。第三步审查测试代码：断言是否有效、覆盖是否真实、有没有过度拟合。AI 生成的测试是初稿，经过这三条审查才算可靠——和审查业务代码是同一个标准。审查不过的用例别急着删，先改到能通过为止。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"AI 生成的测试初稿\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">AI 生成的测试初稿</tspan></text></g><g data-k=\"人工审查后可靠\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">人工审查后可靠</tspan></text></g></svg>","d":40.9},{"t":"交付测试集","n":"把用例集、测试代码、覆盖率报告、审查结论一起打包交付。这套测试是 M5 的核心产出，也是 M6 交付包的组成部分。可靠的测试让你在交付时能理直气壮地说：这个模块，我验过。交付测试集时，用例、代码、覆盖率报告、审查记录四样齐全。别人拿到这套东西，能看懂测了什么、为什么这么测、还有哪些没测——这才叫可交接的测试集。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"用例\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">用例</tspan></text></g><g data-k=\"代码\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">代码</tspan></text></g><g data-k=\"覆盖率\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">覆盖率</tspan></text></g><g data-k=\"审查\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">审查</tspan></text></g></svg>","d":37.0},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「M5 实战：给模块补齐测试」。独立为模块补齐测试并通过验收把今天最有价值的三点写进产出物「测试集（可带走）」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：为你的模块补齐测试并交付。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":39.1}],"quiz":[{"q":"M5 实战的最终交付是？","opts":["一段新功能","完整测试集含覆盖率报告","一张截图","需求文档"],"a":1,"why":"M5 聚焦测试，交付物是可运行、可审查、有覆盖率证明的测试集。"},{"q":"交付测试集前必须确认？","opts":["测试数量够多","测试代码本身可靠、覆盖率达标","用了最贵的工具","测试跑得最快"],"a":1,"why":"测试的价值在可靠和有效覆盖，而不是数量或速度。"}],"template":"【测试集】\n用例数：____\n覆盖率：____\n审查结论：____\n遗留风险：____","brief":"【本单元要点】把测试方法用在真实模块上，才算学会\n【为什么重要】学员为 M3 模块补齐测试，覆盖率达到约定阈值\n【看完做一件事】为你的模块补齐测试并交付。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"}]},{"id":"M6","title":"M6 交付与协作：从代码到可交接","dims":["content","workflow"],"units":[{"id":"M6U1","tier":"core","step":"understand","title":"代码不等于交付物","video":{"dur":"3.8min","script":["「做完了」的误会","第一类：代码","第二类：测试"]},"ppt":{"method":"能跑的代码只是交付物的一部分","case":"开发说「做完了」，主管问「文档和测试呢」","demo":"交付物清单"},"objective":"说清一个完整交付物包含什么","transfer":"提交前按交付物清单自检","deliverable":{"type":"document","name":"交付物清单","rubric":["代码","测试","文档","变更说明"],"acceptance":"一张清单：列出四类交付物及其验收要点。"},"task":"写一份交付物清单，用于每次提交前自检。","rubric":["四类齐全","每类有验收要点","可用于自检"],"vslides":[{"t":"「做完了」的误会","n":"开发说做完了，主管一看：代码有了，测试没写，文档没有，变更说明也没有。这就是把代码等同于交付物的误会。代码只是交付物的一部分——真正的交付物是让别人能接手、能维护、能复核的一整套东西。「做完了」是研发里最容易被误解的词。你心里想的是代码写完了，评审人想的是能交接上线了。两者差着测试、文档和变更说明——这一节就是把「做完」的标准一次说清。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"只有代码（难接手）\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">只有代码（难接手）</tspan></text></g><g data-k=\"代码+测试+文档+说明\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">代码+测试+文档+说明</tspan></text></g></svg>","d":42.6},{"t":"第一类：代码","n":"代码本身要满足基本要求：能通过构建、通过审查、符合项目规范、没有阻断级问题。这是基础，但不是全部。代码的质量由前面 M3、M4 保证，这里只是确认为交付状态。第一类是代码：构建通过、审查通过、符合规范。代码本身合格只是入场券，它不包含「别人能不能接手」这个问题——所以后面还有三类。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"构建通过\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">构建通过</tspan></text></g><g data-k=\"审查通过\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">审查通过</tspan></text></g><g data-k=\"符合规范\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">符合规范</tspan></text></g></svg>","d":33.9},{"t":"第二类：测试","n":"测试要随代码一起交付：用例集、测试代码、覆盖率报告。它证明你的代码被验证过，也让后面的维护者知道行为的边界。缺了测试的交付，等于把验证责任推给下一个人。第二类测试：用例集、测试代码、覆盖率报告。三样合起来，才能让接手的人知道「什么情况下这个功能是好的」——测试是可执行的行为说明，比文档更可靠。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"用例集\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">用例集</tspan></text></g><g data-k=\"测试代码\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">测试代码</tspan></text></g><g data-k=\"覆盖率报告\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">覆盖率报告</tspan></text></g></svg>","d":36.2},{"t":"第三类：文档","n":"必要的文档包括：技术方案说明（为什么这么做）、API 文档（怎么用）、关键的架构决策记录。文档不需要长，但要回答后来者最关心的问题：这段代码解决什么、怎么用、为什么这么设计。第三类文档：技术方案、API 文档、决策记录。文档回答「为什么这么做」和「别人怎么用」——没有它，下一个改这段的人只能猜你的意图，而猜错的成本很高。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"技术方案\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">技术方案</tspan></text></g><g data-k=\"API 文档\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">API 文档</tspan></text></g><g data-k=\"决策记录\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">决策记录</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":39.1},{"t":"第四类：变更说明","n":"最后是变更说明，也就是 PR 描述：这次改了什么、为什么改、影响范围、怎么验证的。它是评审人快速理解变更的入口。四类合起来，才是可交接的完整交付物。第四类变更说明：这次改了什么、影响谁、怎么验证。它是给评审人和运维看的入口——一份清楚的变更说明，能让评审从半小时缩到五分钟。四类齐全，才叫交付物。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"代码\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">代码</tspan></text></g><g data-k=\"测试\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">测试</tspan></text></g><g data-k=\"文档\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">文档</tspan></text></g><g data-k=\"变更说明\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">变更说明</tspan></text></g></svg>","d":34.6},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「代码不等于交付物」。提交前按交付物清单自检把今天最有价值的三点写进产出物「交付物清单」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：写一份交付物清单，用于每次提交前自检。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":38.6}],"quiz":[{"q":"一个完整交付物不包括下列哪项？","opts":["可运行的代码","对应的测试","必要的文档","开发者当天的心情"],"a":3,"why":"交付物包括代码、测试、文档和变更说明，与情绪无关。"},{"q":"为什么说代码不等于交付物？","opts":["代码不重要","同事需要测试和文档才能接手和维护","代码行数太少","AI 生成的代码不算代码"],"a":1,"why":"交付物的价值在于别人能接手，缺了测试和文档就接不了手。"}],"template":"【交付物清单】\n代码：____\n测试：____\n文档：____\n变更说明：____\n自检结论：____","brief":"【本单元要点】能跑的代码只是交付物的一部分\n【为什么重要】开发说「做完了」，主管问「文档和测试呢」\n【看完做一件事】写一份交付物清单，用于每次提交前自检。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M6U2","tier":"core","step":"understand","title":"用 AI 写 PR 描述","video":{"dur":"3.7min","script":["PR 描述的价值","写清改了什么","写清为什么"]},"ppt":{"method":"好的 PR 描述让评审一遍就懂","case":"PR 描述只写「修复 bug」，评审人一头雾水","demo":"PR 描述模板"},"objective":"生成评审人看得懂的变更说明","transfer":"能用 AI 生成结构完整的 PR 描述","deliverable":{"type":"document","name":"PR 描述模板","rubric":["改了什么","为什么","影响范围","怎么验证"],"acceptance":"一份 PR 描述：四部分齐全，评审人能据此快速理解变更。"},"task":"用模板为一个真实变更写 PR 描述。","rubric":["四部分齐全","有验证方式","评审人可理解"],"vslides":[{"t":"PR 描述的价值","n":"很多人写 PR 描述只写「修复 bug」「优化代码」，评审人点开一看一头雾水，只能反复问你。好的 PR 描述能让评审人三十秒内理解变更的全貌，把时间花在真正需要判断的地方。这是协作效率的隐形杠杆。PR 描述是评审人的第一印象。「修复 bug」这种写法让他必须自己读 diff 才能知道发生了什么；「修复空值导致的崩溃，附回归测试」则让他一眼判断风险——这就是有效和无效的区别。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"修复 bug（无效）\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">修复 bug（无效）</tspan></text></g><g data-k=\"修复空值导致的崩溃，附测试（有效）\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"94.8\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">修复空值导致的崩溃，附</tspan><tspan x=\"295.0\" dy=\"15.600000000000001\">测试（有效）</tspan></text></g></svg>","d":40.5},{"t":"写清改了什么","n":"第一部分是变更内容：改了哪些文件、加了什么功能、修了什么问题。要具体到模块和行为，不要只写「优化」。让评审人一眼看到变更的边界。写清改了什么：涉及哪些文件、功能有什么变化、修了什么问题。列文件时按重要性排，把最核心的改动放最前——评审人的注意力有限，别让他从一堆次要文件里找重点。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"涉及文件\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">涉及文件</tspan></text></g><g data-k=\"功能变化\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">功能变化</tspan></text></g><g data-k=\"问题修复\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">问题修复</tspan></text></g></svg>","d":33.2},{"t":"写清为什么","n":"第二部分是背景和原因：为什么要做这个变更，它解决什么问题，有没有考虑过其他方案。这一部分帮助评审人理解设计意图，也让他能判断你的方案是不是合理。写清为什么：背景是什么、解决了什么问题、为什么选这个方案。特别是方案权衡——你考虑过别的做法吗、为什么没选。写清这些，评审人才会信任你的判断而不是逐行质疑。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"背景\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">背景</tspan></text></g><g data-k=\"解决的问题\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">解决的问题</tspan></text></g><g data-k=\"方案权衡\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">方案权衡</tspan></text></g></svg>","d":35.8},{"t":"写清影响与验证","n":"第三部分是影响范围：这个改动会影响哪些调用方、需不需要数据迁移、有没有兼容性问题。第四部分是验证方式：跑了哪些测试、覆盖到什么程度、有没有手工验证的项。写清影响与验证：影响哪些调用方、兼容性有没有变化、你跑了哪些测试。这一栏是给评审人的定心丸——他最怕的是「改了这里，别的地方悄悄坏了」。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"影响范围\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">影响范围</tspan></text></g><g data-k=\"兼容性\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">兼容性</tspan></text></g><g data-k=\"验证方式\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">验证方式</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":37.1},{"t":"用模板生成","n":"把四部分写成模板，让 AI 基于你的变更内容生成初稿，你补充背景和权衡这些它不知道的部分。生成后自己读一遍：假设你是评审人，能不能看懂？能，就可以提交了。用模板生成时，把改了什么、为什么、影响范围、怎么验证四段都填上。缺任何一段，评审人都得多问一轮——PR 描述的本质是替评审人省时间，省下的就是团队的效率。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"改了什么\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">改了什么</tspan></text></g><g data-k=\"为什么\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">为什么</tspan></text></g><g data-k=\"影响范围\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">影响范围</tspan></text></g><g data-k=\"怎么验证\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">怎么验证</tspan></text></g></svg>","d":38.6},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「用 AI 写 PR 描述」。能用 AI 生成结构完整的 PR 描述把今天最有价值的三点写进产出物「PR 描述模板」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：用模板为一个真实变更写 PR 描述。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":38.4}],"quiz":[{"q":"好的 PR 描述最重要的特点是？","opts":["写得越长越好","让评审人快速理解改了什么、为什么、怎么验证","用很多术语","只写结论"],"a":1,"why":"PR 描述的核心价值是帮助评审人快速理解变更并有效评审。"},{"q":"PR 描述里「怎么验证」这一项的作用是？","opts":["凑字数","告诉评审人你做了哪些验证，便于复核","替代测试","给主管看"],"a":1,"why":"说明验证方式让评审人知道你测过什么，也便于他针对性复核。"}],"template":"【PR 描述模板】\n改了什么：____\n为什么：____\n影响范围：____\n怎么验证：____","brief":"【本单元要点】好的 PR 描述让评审一遍就懂\n【为什么重要】PR 描述只写「修复 bug」，评审人一头雾水\n【看完做一件事】用模板为一个真实变更写 PR 描述。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M6U3","tier":"core","step":"understand","title":"技术方案文档生成","video":{"dur":"3.8min","script":["方案是开工前的蓝图","第一部分：背景与目标","第二部分：架构设计"]},"ppt":{"method":"方案文档是把想法变成可评审的蓝图","case":"团队没写方案就开工，做到一半发现方向错了","demo":"技术方案模板"},"objective":"生成含架构与实现路径的方案","transfer":"能用 AI 辅助生成结构完整的技术方案","deliverable":{"type":"document","name":"技术方案模板","rubric":["背景目标","架构设计","关键决策","验证方式"],"acceptance":"一份技术方案：四部分齐全，含至少一个关键决策的权衡。"},"task":"用模板为一个真实功能写技术方案。","rubric":["四部分齐全","有决策权衡","可评审"],"vslides":[{"t":"方案是开工前的蓝图","n":"复杂功能不该上来就写代码。技术方案是开工前的蓝图：先把背景、目标、架构、关键决策写清楚，让团队评审通过再动手。它能避免做到一半才发现方向错了这种代价高昂的返工。方案是开工前的蓝图。跳过它直接写代码，短任务还能靠脑子兜住，稍大一点就会在半路发现「当初没想清楚」——回头改的代价，远大于开头花十分钟写方案。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"背景目标\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">背景目标</tspan></text></g><g data-k=\"架构设计\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">架构设计</tspan></text></g><g data-k=\"关键决策\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">关键决策</tspan></text></g><g data-k=\"评审后开工\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"76.4\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">评审后开</tspan><tspan x=\"341.8\" dy=\"16.900000000000002\">工</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":38.9},{"t":"第一部分：背景与目标","n":"写清要解决什么问题、当前的痛点、预期的目标，最好有可衡量的指标。比如「当前导出一万条订单要两分钟，目标是降到三十秒内」。背景清楚，方案才有靶子。第一部分背景与目标：要解决什么问题、预期达到什么状态、有没有可衡量的指标。指标是关键——「提升性能」不算目标，「接口响应从 2 秒降到 500 毫秒」才算。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"问题痛点\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">问题痛点</tspan></text></g><g data-k=\"预期目标\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">预期目标</tspan></text></g><g data-k=\"可衡量指标\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">可衡量指标</tspan></text></g></svg>","d":35.8},{"t":"第二部分：架构设计","n":"描述整体结构：有哪些模块、数据怎么流、关键接口怎么设计。可以用文字加简单的示意图。架构设计要让读者能看懂系统的骨架，不需要写到代码细节。第二部分架构设计：模块怎么划分、数据怎么流、关键接口是什么、模块间什么依赖。这部分让别人能看懂你的整体思路，也能提前发现「这个模块职责太重」这类问题。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"模块划分\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">模块划分</tspan></text></g><g data-k=\"数据流\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">数据流</tspan></text></g><g data-k=\"关键接口\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">关键接口</tspan></text></g><g data-k=\"依赖关系\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">依赖关系</tspan></text></g></svg>","d":35.8},{"t":"第三部分：关键决策","n":"这是方案里最有价值的部分。写下你做的关键选择：为什么用这个方案不用那个、权衡了什么、放弃了什么、有什么风险。把这些写清楚，评审才有抓手，后来者也才知道当时的考虑。第三部分关键决策：别只给结论，要给结论、权衡和风险。为什么选 A 不选 B、A 的代价是什么、什么情况下要重新考虑——写清这些，方案才经得起评审追问。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"直接给结论\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">直接给结论</tspan></text></g><g data-k=\"给结论+权衡+风险\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">给结论+权衡+风险</tspan></text></g></svg>","d":38.0},{"t":"第四部分：验证方式","n":"写清怎么验证方案达成目标：测试策略、验收指标、上线后的观察点。让 AI 生成初稿，你补充业务背景和权衡判断。评审通过后，这份方案就是实施的依据。第四部分验证方式：怎么证明方案达成目标。把测试策略、验收标准、上线后的观察指标写下来——没有验证方式的方案，只是想法，不是方案。上线后看什么指标，也要在这一节里写明。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"背景目标\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">背景目标</tspan></text></g><g data-k=\"架构\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">架构</tspan></text></g><g data-k=\"决策权衡\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">决策权衡</tspan></text></g><g data-k=\"验证\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">验证</tspan></text></g></svg>","d":39.0},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「技术方案文档生成」。能用 AI 辅助生成结构完整的技术方案把今天最有价值的三点写进产出物「技术方案模板」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：用模板为一个真实功能写技术方案。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":39.1}],"quiz":[{"q":"技术方案里最体现价值的部分是？","opts":["字数多少","关键决策及其权衡","用了多少工具","格式是否花哨"],"a":1,"why":"方案的价值在于把设计决策和权衡讲清楚，供团队评审。"},{"q":"技术方案的主要读者和用途是？","opts":["只有 AI 看","团队评审与后来者理解设计意图","用来凑交付数量","替代代码"],"a":1,"why":"方案用于让团队评审设计、让后来者理解为什么这么做。"}],"template":"【技术方案模板】\n背景目标：____\n架构设计：____\n关键决策：____\n验证方式：____","brief":"【本单元要点】方案文档是把想法变成可评审的蓝图\n【为什么重要】团队没写方案就开工，做到一半发现方向错了\n【看完做一件事】用模板为一个真实功能写技术方案。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M6U4","tier":"core","step":"understand","title":"从代码生成 API 文档","video":{"dur":"3.8min","script":["为什么需要 API 文档","让 AI 生成初稿","校准重点一：参数与类型"]},"ppt":{"method":"API 文档是给调用者的说明书","case":"AI 生成的 API 文档把参数类型写错了，调用方照着对接失败","demo":"API 文档"},"objective":"自动生成并人工校准 API 文档","transfer":"能生成 API 文档并知道人工校准重点","deliverable":{"type":"document","name":"API 文档","rubric":["接口说明","参数","返回值","示例"],"acceptance":"一份 API 文档：含接口说明、参数表、返回值、调用示例。"},"task":"为一个真实接口生成 API 文档并人工校准。","rubric":["四部分齐全","参数类型准确","人工校准过"],"vslides":[{"t":"为什么需要 API 文档","n":"代码是写给机器执行的，文档是写给人看的。调用方要知道这个接口怎么用、传什么参数、返回什么、出错怎么处理。AI 擅长从代码里提取这些信息生成初稿，但初稿必须人工校准。API 文档是写给别人看的说明书。代码里的函数签名只有你自己看得懂，调用方需要知道参数怎么传、返回什么、出错怎么办——这些不写清楚，他们就得来问你，或者猜错。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"代码\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">代码</tspan></text></g><g data-k=\"AI 提取\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">AI 提取</tspan></text></g><g data-k=\"人工校准\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">人工校准</tspan></text></g><g data-k=\"调用方可用\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"76.4\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">调用方可</tspan><tspan x=\"341.8\" dy=\"16.900000000000002\">用</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":35.3},{"t":"让 AI 生成初稿","n":"把接口代码交给 AI，让它按标准结构生成：接口说明、参数表（名称、类型、必填、说明）、返回值结构、错误码、调用示例。明确的格式要求能得到规整的初稿。让 AI 从代码生成初稿很快：接口说明、参数表、返回值、示例，四样一次出来。但初稿只是起点——它常把默认值、边界条件、错误码写漏，或者直接照抄类型名当说明。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"接口说明\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">接口说明</tspan></text></g><g data-k=\"参数表\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">参数表</tspan></text></g><g data-k=\"返回值\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">返回值</tspan></text></g><g data-k=\"示例\"><g><circle cx=\"30\" cy=\"154\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 154 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"158.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">示例</tspan></text></g></svg>","d":40.0},{"t":"校准重点一：参数与类型","n":"人工校准的第一重点是参数的准确性和完整性：类型对不对、有没有必填项没标、取值范围对不对、枚举值全不全。这些错一个，调用方就会对接失败。对照代码逐项核实。校准重点一是参数与类型：参数类型、是否必填、取值范围、枚举值分别是什么。特别是枚举值，一定要写出每个值的含义——只写「status: int」等于没写。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"参数类型\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">参数类型</tspan></text></g><g data-k=\"必填性\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">必填性</tspan></text></g><g data-k=\"取值范围\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">取值范围</tspan></text></g><g data-k=\"枚举值\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">枚举值</tspan></text></g></svg>","d":39.2},{"t":"校准重点二：错误与边界","n":"第二重点是错误码和边界说明：什么情况返回什么错误、有没有限流、幂等性如何保证。AI 常常漏掉这些，但它们恰恰是调用方最容易踩坑的地方。校准重点二是错误与边界：别只写成功返回，把错误码、错误场景、边界行为都写清。调用方最容易踩的坑就是「没考虑失败情况」，文档有这一节，他们就不会踩。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"只写成功返回\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">只写成功返回</tspan></text></g><g data-k=\"成功与错误场景都写清\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">成功与错误场景都写清</tspan></text></g></svg>","d":31.8},{"t":"交付与维护","n":"校准后的文档随代码一起交付。当接口变更时，文档必须同步更新——过时的文档比没有文档更有害。把「接口变更需同步文档」写进团队的规范里。文档交付后要跟着代码同步更新。代码改了文档没改，比没有文档更糟——它会把调用方引到错误路上。把这个同步动作写进团队规范，文档才不会腐烂。接口变更时同步更新，是文档维护最低的要求。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"生成\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">生成</tspan></text></g><g data-k=\"校准\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">校准</tspan></text></g><g data-k=\"交付\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">交付</tspan></text></g><g data-k=\"同步更新\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">同步更新</tspan></text></g></svg>","d":41.0},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「从代码生成 API 文档」。能生成 API 文档并知道人工校准重点把今天最有价值的三点写进产出物「API 文档」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：为一个真实接口生成 API 文档并人工校准。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":39.1}],"quiz":[{"q":"AI 生成的 API 文档，必须人工校准的是什么？","opts":["字体颜色","参数类型、必填性和错误码的准确性","文档的行数","AI 的名字"],"a":1,"why":"参数与错误码的准确性直接决定调用方能否正确对接，必须人工核实。"},{"q":"好的 API 文档应该包含？","opts":["只有函数签名","接口说明、参数、返回值、示例","开发者的感想","代码全部源码"],"a":1,"why":"这些是调用方真正需要的信息，帮助其快速正确对接。"}],"template":"【API 文档】\n接口说明：____\n参数表：____\n返回值：____\n错误码：____\n示例：____","brief":"【本单元要点】API 文档是给调用者的说明书\n【为什么重要】AI 生成的 API 文档把参数类型写错了，调用方照着对接失败\n【看完做一件事】为一个真实接口生成 API 文档并人工校准。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M6U5","tier":"core","step":"understand","title":"把项目经验沉淀进知识库","video":{"dur":"4.0min","script":["经验不沉淀就流失","让 AI 帮你蒸馏","写清适用场景"]},"ppt":{"method":"一次经验只有沉淀下来才算团队资产","case":"同样的问题下个月又被踩了一遍，因为没人记录","demo":"知识库条目"},"objective":"蒸馏一次任务为可复用条目","transfer":"能把一次实践蒸馏成团队可复用的知识条目","deliverable":{"type":"document","name":"知识库条目","rubric":["问题场景","有效做法","踩坑提醒"],"acceptance":"一条可复用知识：写清适用场景、有效做法、踩过的坑。"},"task":"把你最近一次 AI Coding 实践蒸馏成知识条目。","rubric":["场景明确","做法具体","含踩坑提醒"],"vslides":[{"t":"经验不沉淀就流失","n":"你花两小时解决了一个棘手问题，如果不记下来，下个月同事遇到同样的问题还要再花两小时。个人经验只有写下来、被别人找到，才算团队资产。AI Coding 是新事物，团队尤其需要把有效做法快速沉淀。经验不沉淀就会流失。你这次摸索出来的规则写法、踩过的坑，下周可能就忘了；写进知识库，它就能被下一个人直接拿来用——个人经验变成团队资产，就差这一步。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"只在脑子里（会流失）\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">只在脑子里（会流失）</tspan></text></g><g data-k=\"写进知识库（可复用）\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">写进知识库（可复用）</tspan></text></g></svg>","d":40.5},{"t":"让 AI 帮你蒸馏","n":"把一次任务的过程记录交给 AI，让它按结构蒸馏：问题场景是什么、有效的做法是什么、踩过哪些坑、适用于什么范围。AI 擅长从流水账里提炼要点，你要补充的是判断——哪些真的值得记。让 AI 帮你蒸馏：把这次的任务记录、指令、偏差、修正给它，让它提炼出可复用的条目。它擅长把散乱过程整理成结构化结论，筛选和判断哪些值得入库则是你的活。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"任务记录\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">任务记录</tspan></text></g><g data-k=\"AI 蒸馏\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">AI 蒸馏</tspan></text></g><g data-k=\"人工筛选\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">人工筛选</tspan></text></g><g data-k=\"入库\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">入库</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":39.3},{"t":"写清适用场景","n":"一条知识首先要写清适用场景：什么问题、什么条件下用。没有场景的知识是孤立的，别人不知道什么时候该用它。比如不说「用复述确认」，而说「当任务复杂、约束多、返工代价大时，先让 AI 复述确认」。写清适用场景：这个经验解决什么问题、在什么条件下适用、有什么触发信号。「适用于需要生成新模块的场景」比「这个技巧很好用」有用得多——别人靠场景判断能不能用。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"问题场景\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">问题场景</tspan></text></g><g data-k=\"适用条件\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">适用条件</tspan></text></g><g data-k=\"触发信号\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">触发信号</tspan></text></g></svg>","d":36.5},{"t":"写清做法与坑","n":"做法要具体到可执行： step 是什么、指令怎么写。踩坑提醒同样重要——哪些做法看起来对其实有坑、哪里容易出错。真实的坑比正确的做法更有价值，因为它别人不知道。写清做法与坑：有效做法是什么、常见误区在哪、踩过的坑提醒什么。坑那一条尤其有价值——成功做法大家会写，失败教训常常没人记，而后者恰恰最能帮后来人绕弯路。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"有效做法\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">有效做法</tspan></text></g><g data-k=\"常见误区\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">常见误区</tspan></text></g><g data-k=\"踩坑提醒\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">踩坑提醒</tspan></text></g><g data-k=\"注意事项\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">注意事项</tspan></text></g></svg>","d":38.6},{"t":"入库并分享","n":"把蒸馏好的条目放进团队知识库，在相关场景里能被找到。定期回顾：哪些条目被用到、哪些已经过时。知识库不是一次性工程，而是持续维护的活资产。入库后分享给团队，并约定维护责任。知识库不是写完就完——项目结构变了、工具换了，旧条目要更新。没人维护的知识库，半年后就没人敢信了。条目写清由谁维护，才不会变成没人认领的孤儿。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"蒸馏\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">蒸馏</tspan></text></g><g data-k=\"筛选\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">筛选</tspan></text></g><g data-k=\"入库\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">入库</tspan></text></g><g data-k=\"维护\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">维护</tspan></text></g></svg>","d":39.6},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「把项目经验沉淀进知识库」。能把一次实践蒸馏成团队可复用的知识条目把今天最有价值的三点写进产出物「知识库条目」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：把你最近一次 AI Coding 实践蒸馏成知识条目。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":43.2}],"quiz":[{"q":"一条有用的知识条目最重要的是？","opts":["字数多","场景和做法具体，别人能复用","用词高级","包含所有细节"],"a":1,"why":"知识条目的价值在于别人遇到类似场景时能直接借鉴。"},{"q":"为什么要把经验沉淀下来？","opts":["为了让文档更多","避免团队重复踩坑，把个人经验变组织资产","应付检查","替代代码审查"],"a":1,"why":"沉淀让经验可被复用，避免重复犯错，是个人能力转为组织资产的关键。"}],"template":"【知识库条目】\n场景：____\n有效做法：____\n踩坑提醒：____\n适用范围：____","brief":"【本单元要点】一次经验只有沉淀下来才算团队资产\n【为什么重要】同样的问题下个月又被踩了一遍，因为没人记录\n【看完做一件事】把你最近一次 AI Coding 实践蒸馏成知识条目。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M6U6","tier":"core","step":"understand","title":"团队 AI Coding 规范制定","video":{"dur":"3.8min","script":["从个人习惯到团队规范","第一类：数据红线","第二类：生成与审查"]},"ppt":{"method":"规范不是写在墙上的口号，是每天能执行的约定","case":"团队各用各的 AI 习惯，代码合并后风格混乱","demo":"团队规范 v1"},"objective":"汇总个人规则为团队规范","transfer":"能把团队已有的实践汇总为可执行规范","deliverable":{"type":"document","name":"团队规范 v1","rubric":["数据红线","生成与审查","测试要求","交付要求"],"acceptance":"一份团队规范：四类约定，每条可执行、可判定。"},"task":"写一份团队 AI Coding 规范 v1。","rubric":["四类齐全","每条可执行","有落地方式"],"vslides":[{"t":"从个人习惯到团队规范","n":"前面你写了个人规则、项目规则。当很多人一起用 AI，就需要团队规范来统一底线：什么能做、什么不能做、做完要交什么。规范的目的不是限制，而是让每个人的产出都能被别人接手。团队规范不是把个人习惯投票选一个，而是把「已经被验证有效」的做法固定下来。个人规则管自己，项目规则管一个项目，团队规范管所有项目——层级不同，约束力也不同。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"个人习惯\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">个人习惯</tspan></text></g><g data-k=\"项目规则\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">项目规则</tspan></text></g><g data-k=\"团队规范\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">团队规范</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":40.0},{"t":"第一类：数据红线","n":"把数据红线放在规范第一条，因为它最不能妥协：什么数据不能贴公网 AI、涉敏项目怎么处理、密钥和客户信息怎么脱敏。这一条要写得毫不含糊，让每个人都知道边界在哪。第一类数据红线：什么数据不能贴公网 AI、脱敏怎么做、涉敏项目怎么处理。这一类是规范的底线，没有商量余地——写的时候要具体到「看到什么、做什么」，别写成口号。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"不贴公网的数据\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">不贴公网的数据</tspan></text></g><g data-k=\"脱敏方法\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">脱敏方法</tspan></text></g><g data-k=\"涉敏项目处理\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">涉敏项目处理</tspan></text></g></svg>","d":37.5},{"t":"第二类：生成与审查","n":"约定生成和审查的要求：生成粒度怎么选、规格怎么写、生成后必须过什么验收、AI 结论怎么复核、谁签字放行。把你在课程里学的方法固化成团队动作。第二类生成与审查：生成粒度怎么选、规格要写到什么程度、三问验收怎么做、哪些必须人工复核。这些统一了，不同人产出的质量才不会差三倍。这四类写进规范，审查时照着勾一遍就行。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"生成粒度\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">生成粒度</tspan></text></g><g data-k=\"规格要求\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">规格要求</tspan></text></g><g data-k=\"三问验收\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">三问验收</tspan></text></g><g data-k=\"人工复核\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">人工复核</tspan></text></g></svg>","d":38.4},{"t":"第三类：测试与交付","n":"约定测试要求（覆盖率底线、测试必须审查）和交付要求（交付物包括什么、PR 怎么写、文档怎么维护）。这两类约定决定了团队交付的一致性。第三类测试与交付：不能「能跑就提交」，要有测试、文档和变更说明。把交付物清单写进规范，评审时照单核对——标准明确，争论就少了。清单贴在提交入口，比口头提醒有效得多。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"能跑就提交（不规范）\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">能跑就提交（不规范）</tspan></text></g><g data-k=\"测试+文档+说明齐全\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">测试+文档+说明齐全</tspan></text></g></svg>","d":37.2},{"t":"让规范活起来","n":"规范写好后要推广：放进项目规则文件让 AI 也遵守、新人入职就学、评审时按规范检查。定期收集执行中的问题和反馈，迭代规范。写在文档里不动的规范等于没有。规范要活起来，得靠执行和迭代：推广时给例子，检查时照规范，定期收集反馈更新。写一份没人用的规范毫无意义——让它真正被用起来，比写得完美重要。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"写规范\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">写规范</tspan></text></g><g data-k=\"推广执行\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">推广执行</tspan></text></g><g data-k=\"按规检查\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">按规检查</tspan></text></g><g data-k=\"定期迭代\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">定期迭代</tspan></text></g></svg>","d":35.3},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「团队 AI Coding 规范制定」。能把团队已有的实践汇总为可执行规范把今天最有价值的三点写进产出物「团队规范 v1」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：写一份团队 AI Coding 规范 v1。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":38.6}],"quiz":[{"q":"团队 AI Coding 规范最该包含的是？","opts":["谁的 AI 工具最好","数据红线、生成审查、测试与交付的约定","开发者的个人偏好","AI 的价格"],"a":1,"why":"规范要覆盖影响质量与安全的关键环节，且每条可执行可判定。"},{"q":"好的团队规范应该是？","opts":["写得越严越好","可执行、可判定，团队真能照做","写在文档里不用执行","只约束新人"],"a":1,"why":"规范的价值在执行，写得再好没人遵守也没有意义。"}],"template":"【团队规范 v1】\n数据红线：____\n生成审查：____\n测试要求：____\n交付要求：____\n落地方式：____","brief":"【本单元要点】规范不是写在墙上的口号，是每天能执行的约定\n【为什么重要】团队各用各的 AI 习惯，代码合并后风格混乱\n【看完做一件事】写一份团队 AI Coding 规范 v1。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M6U7","tier":"core","step":"spar","title":"陪练：技术负责人评审你的 PR","video":{"dur":"3.9min","script":["陪练说明","第一轮：为什么这么设计","第二轮：影响范围"]},"ppt":{"method":"评审不是考试，是让方案经得起追问","case":"技术负责人问「这个改动会不会影响老客户」，你没准备","demo":"评审复盘记录"},"objective":"顶住三轮评审追问","transfer":"面对技术负责人评审能有条理地回应","deliverable":{"type":"document","name":"评审复盘记录","rubric":["质疑点","你的回应","改进"],"acceptance":"一份记录：三轮评审质疑各写质疑点、你的回应、后续改进。"},"task":"完成三轮评审追问并记录。","rubric":["至少两轮有条理回应","有实际改进","记录完整"],"vslides":[{"t":"陪练说明","n":"这一轮 AI 扮成技术负责人，评审你的 PR。他会问三个方向：为什么这么设计、影响范围多大、出问题怎么回滚。你要用方案、测试、数据回应。答不上来的地方诚实承认并补充，不要用「应该没问题」搪塞。这一轮 AI 扮技术负责人，评审你的 PR。它追问设计理由、影响范围和回滚方案——这三点正是技术负责人最关心的：你为什么这么做、会波及谁、出事怎么办。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"设计理由\"><rect x=\"18.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"74.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"74.0\">设计理由</tspan></text></g><g data-k=\"影响范围\"><rect x=\"144.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">影响范围</tspan></text></g><g data-k=\"回滚方案\"><rect x=\"270.0\" y=\"42.0\" width=\"112.0\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"326.0\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"326.0\">回滚方案</tspan></text></g><path d=\"M132.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M258.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":37.5},{"t":"第一轮：为什么这么设计","n":"他会问设计选择：为什么用这个方案、有没有考虑过别的、为什么选现在这个。回应要讲清权衡和约束——当时的条件下为什么这是最合适的。有权衡的回答才让人信服。第一轮追问设计理由：说清权衡过程、考虑过哪些方案、为什么选现在这个。能讲出被放弃的方案，说明你的选择是经过判断的；只说「这么写比较顺」，很难让人放心。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"设计权衡\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">设计权衡</tspan></text></g><g data-k=\"考虑过的方案\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">考虑过的方案</tspan></text></g><g data-k=\"选择理由\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">选择理由</tspan></text></g></svg>","d":38.0},{"t":"第二轮：影响范围","n":"第二轮问影响：这个改动会影响哪些调用方、有没有兼容性问题、需不需要数据迁移、老用户会不会受影响。你要拿出影响分析的结论。如果没分析过，这一轮就暴露了准备不足。第二轮追问影响范围：调用方有谁、兼容性有没有变、要不要数据迁移、老用户会怎样。这一轮答不全，说明你对改动的影响面还没盘清——而那是上线事故最常见的来源。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"调用方\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">调用方</tspan></text></g><g data-k=\"兼容性\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">兼容性</tspan></text></g><g data-k=\"数据迁移\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">数据迁移</tspan></text></g><g data-k=\"老用户\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">老用户</tspan></text></g></svg>","d":36.7},{"t":"第三轮：出问题怎么回滚","n":"第三轮问兜底：上线后如果出问题，怎么发现、怎么回滚、有没有开关。这是资深工程师最看重的意识——不只想着怎么上线，还想清楚出问题怎么办。回答要有具体的监控和回滚方案。第三轮追问出问题怎么回滚：只想到上线的人会卡在这里。要说清上线后看什么指标、什么情况判定异常、回滚步骤是什么、回滚后数据怎么处理——完整方案才过得了这一轮。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"只想到上线\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">只想到上线</tspan></text></g><g data-k=\"上线+监控+回滚\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">上线+监控+回滚</tspan></text></g></svg>","d":41.3},{"t":"通过标准与改进","n":"通过标准是：至少两轮有条理地回应，对答不上来的能给出补充计划。结束后记录三轮质疑和改进点。能被评审问不倒的 PR，才是真正准备好的 PR。通过标准是有条理回应、诚实补充、记录改进。被问到没想过的点就说「这个我确实没考虑到，我补进方案」——技术负责人要的是可靠，不是全知；诚实补漏比硬撑更值得信任。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"有条理回应\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">有条理回应</tspan></text></g><g data-k=\"诚实补充\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">诚实补充</tspan></text></g><g data-k=\"记录改进\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">记录改进</tspan></text></g></svg>","d":39.8},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「陪练：技术负责人评审你的 PR」。面对技术负责人评审能有条理地回应把今天最有价值的三点写进产出物「评审复盘记录」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：完成三轮评审追问并记录。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":38.4}],"quiz":[{"q":"面对评审质疑，最好的态度是？","opts":[" defensive 坚持","用方案和测试回应，不确定就承认","回避问题","责怪需求不清"],"a":1,"why":"有依据地回应、对不确定诚实，是成熟工程师在评审中的表现。"},{"q":"评审陪练的价值在于？","opts":["让你难堪","在合并前发现设计与影响面的问题","证明你写得快","减少文档"],"a":1,"why":"评审通过追问暴露盲点，是合并前的重要质量闸门。"}],"template":"【评审复盘记录】\n质疑1____ 回应____ 改进____\n质疑2____ 回应____ 改进____\n质疑3____ 回应____ 改进____","brief":"【本单元要点】评审不是考试，是让方案经得起追问\n【为什么重要】技术负责人问「这个改动会不会影响老客户」，你没准备\n【看完做一件事】完成三轮评审追问并记录。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M6U8","tier":"core","step":"todo","title":"M6 实战：完整交付一个变更","video":{"dur":"4.0min","script":["实战任务说明","第一步：整理四类交付物","第二步：自检与校准"]},"ppt":{"method":"把交付方法用在真实变更上，才算走完一个闭环","case":"学员交付了一个包含四类交付物的完整变更","demo":"完整演示从整理交付物到自检交付的全过程"},"objective":"交付代码、测试、文档、PR 的完整包","transfer":"独立完成一个完整变更的交付","deliverable":{"type":"document","name":"交付包","rubric":["代码","测试","文档","PR 描述"],"acceptance":"一个完整交付包：四类交付物齐全，可交接、可复核。"},"task":"为你的模块完成一次完整交付","rubric":["四类齐全","可交接","经过自检"],"vslides":[{"t":"实战任务说明","n":"这一节把 M6 串起来：为你的模块完成一次完整交付。你会用到交付物清单、PR 描述、技术方案、API 文档、知识沉淀和团队规范。目标是交付一个别人能直接接手的完整包，而不是一堆散落的文件。这一节的实战是完整交付一个变更：代码、测试、文档、PR 四样齐全，再自检、沉淀。它把 M6 全部内容串成一次真实交付——做完这一次，你就有了可放进作品集的完整产出。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"代码测试\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">代码测试</tspan></text></g><g data-k=\"技术方案\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">技术方案</tspan></text></g><g data-k=\"API 文档\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">API 文档</tspan></text></g><g data-k=\"PR 描述\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">PR 描述</tspan></text></g><g data-k=\"自检\"><rect x=\"145.3\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">自检</tspan></text></g></svg>","d":43.8},{"t":"第一步：整理四类交付物","n":"按交付物清单整理：代码（已审查）、测试（已验证）、文档（技术方案与 API 文档）、变更说明（PR 描述）。缺哪类补哪类。用 AI 辅助生成文档初稿，人工校准关键内容。第一步整理四类交付物，逐项核对是否齐全。别凭记忆，照着清单一样样点：代码有没有审查过、测试有没有覆盖率报告、文档有没有决策记录、PR 是不是四段齐全。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"代码\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">代码</tspan></text></g><g data-k=\"测试\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">测试</tspan></text></g><g data-k=\"文档\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">文档</tspan></text></g><g data-k=\"变更说明\"><g><circle cx=\"30\" cy=\"154\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 154 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"158.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">变更说明</tspan></text></g></svg>","d":38.9},{"t":"第二步：自检与校准","n":"用交付物清单逐项自检：代码是否审查通过、测试是否可靠、文档是否准确、PR 描述评审人能不能看懂。校准 AI 生成的内容，特别是业务背景和权衡判断。第二步自检与校准：用你自己的交付清单过一遍，校准文档里的参数、错误码、示例，完善 PR 描述。自检的意义是别让评审人替你发现低级错误——那会消耗你的可信度。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"自检交付物\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">自检交付物</tspan></text></g><g data-k=\"校准文档\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">校准文档</tspan></text></g><g data-k=\"完善 PR\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">完善 PR</tspan></text></g></svg>","d":37.9},{"t":"第三步：沉淀与规范","n":"把这次实践中值得复用的经验蒸馏成知识条目，检查是否符合团队规范。这一步让这次交付的价值超出代码本身，成为团队可以复用的资产。第三步沉淀与规范：把这次值得复用的做法写成一条知识库条目，顺手看看要不要补充进团队规范。只交付代码的人做一次是一次，会沉淀的人做一次能让团队以后都少做一次。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"只交付代码\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">只交付代码</tspan></text></g><g data-k=\"交付+沉淀可复用经验\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">交付+沉淀可复用经验</tspan></text></g></svg>","d":36.1},{"t":"交付完整包","n":"把四类交付物加上知识条目打包交付，走一遍自检清单确认齐全。这份交付包是 M6 的核心产出，也是 M7 结业项目的组成部分。能完整交付，才说明你真的走完了从需求到上路的闭环。交付完整包时，四类交付物加一条沉淀记录一起交。评审人看到的不只是一次改动，还有你把经验留给团队意识——这正是从「会写代码」到「能负责交付」的分水岭。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"整理\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">整理</tspan></text></g><g data-k=\"自检\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">自检</tspan></text></g><g data-k=\"沉淀\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">沉淀</tspan></text></g><g data-k=\"交付\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">交付</tspan></text></g></svg>","d":42.9},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「M6 实战：完整交付一个变更」。独立完成一个完整变更的交付把今天最有价值的三点写进产出物「交付包」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：为你的模块完成一次完整交付做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":39.8}],"quiz":[{"q":"M6 实战的交付标准是？","opts":["代码能跑就行","四类交付物齐全、可交接、经过自检","文件越多越好","不需要评审"],"a":1,"why":"交付的核心是别人能接手，四类齐全并经自检是基本要求。"},{"q":"交付包里 PR 描述的作用是？","opts":["凑数","让评审人快速理解变更并有效评审","替代测试","给 AI 看"],"a":1,"why":"PR 描述是评审的入口，帮助评审人快速理解改了什么、为什么、怎么验证。"}],"template":"【交付包】\n代码：____\n测试：____\n技术方案：____\nAPI 文档：____\nPR 描述：____\n知识条目：____","brief":"【本单元要点】把交付方法用在真实变更上，才算走完一个闭环\n【为什么重要】学员交付了一个包含四类交付物的完整变更\n【看完做一件事】为你的模块完成一次完整交付\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"}]},{"id":"M7","title":"M7 结业项目：端到端交付一个真实功能","dims":["strategy","workflow","dev"],"units":[{"id":"M7U1","tier":"core","step":"understand","title":"结业项目说明与选题","video":{"dur":"4.0min","script":["结业项目是什么","选题原则一：真实","选题原则二：范围可控"]},"ppt":{"method":"选题决定结业项目能不能做成","case":"学员选了一个过大题目，两周都做不完","demo":"选题立项卡"},"objective":"选一个真实可交付的功能作为结业项目","transfer":"能选出一个范围合适、可验收的结业项目","deliverable":{"type":"document","name":"选题立项卡","rubric":["题目","业务价值","范围","验收"],"acceptance":"一张卡：写清选题、业务价值、范围边界、验收标准。"},"task":"填一张选题立项卡并说明验收方式。","rubric":["题目真实","范围可控","验收可判定"],"vslides":[{"t":"结业项目是什么","n":"M7 是这门课的收官：你要端到端交付一个真实功能，走完从需求到交付的完整闭环。它不是练习题，而是你学习成果的集中证明。项目会贯穿这一章八节，最后有一场模拟评审答辩。结业项目不是练习题，是这门课唯一的「端到端证据」。前面每一章你都练了一段，只有这里把七段连起来——从一句模糊需求到一个能交接的完整产物。做完它，你才有资格说自己掌握了这套方法。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"选题\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"42.7\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"58.8\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">选题</tspan></text></g><g data-k=\"拆解\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"42.7\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"58.8\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">拆解</tspan></text></g><g data-k=\"生成\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"42.7\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"58.8\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">生成</tspan></text></g><g data-k=\"审查\"><rect x=\"18.0\" y=\"86.7\" width=\"109.3\" height=\"42.7\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"111.4\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">审查</tspan></text></g><g data-k=\"测试\"><rect x=\"145.3\" y=\"86.7\" width=\"109.3\" height=\"42.7\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"111.4\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">测试</tspan></text></g><g data-k=\"交付\"><rect x=\"272.7\" y=\"86.7\" width=\"109.3\" height=\"42.7\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"111.4\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">交付</tspan></text></g><g data-k=\"答辩\"><rect x=\"18.0\" y=\"139.3\" width=\"109.3\" height=\"42.7\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"164.1\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">答辩</tspan></text></g></svg>","d":43.1},{"t":"选题原则一：真实","n":"选一个你工作里真实需要的功能，最好是下周就要做的。真实意味着你有业务上下文、有人能验收、做完有价值。避免选纯虚构的练习题——那种做完了也没有成就感。真实有两个含义：需求来自你真在做的事，有人能验收它。虚构的例子做起来很顺，因为你早已知道答案；真实需求会带来你没有预料到的边界和历史包袱——那才是这套方法要接受检验的地方。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"来自真实工作\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">来自真实工作</tspan></text></g><g data-k=\"有业务上下文\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">有业务上下文</tspan></text></g><g data-k=\"有人能验收\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">有人能验收</tspan></text></g></svg>","d":37.5},{"t":"选题原则二：范围可控","n":"范围要控制在一个功能级：一个接口、一个模块、一个小工具。不要选「重构整个系统」这种。判断标准是：你能在合理的课时内做完并验证。拿不准就往小了选。范围可控是结业项目最容易失手的一关。选一个功能、一个模块、一个小工具，别碰整个系统。范围失控的表现是「做着做着发现还要改另外五个地方」——一旦出现，立刻收窄，不要硬撑。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"一个功能\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">一个功能</tspan></text></g><g data-k=\"一个模块\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">一个模块</tspan></text></g><g data-k=\"一个小工具\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">一个小工具</tspan></text></g><g data-k=\"不碰整个系统\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">不碰整个系统</tspan></text></g></svg>","d":35.8},{"t":"选题原则三：可验收","n":"项目要能明确判定完成。写出至少三条验收标准，覆盖正常、边界、异常情况。没有验收标准的项目做完了也不知道算不算成功。这一步呼应 M1 学的验收方法。可验收的意思是你能在开始前就写出三条可判定的标准。比如「实现订单导出接口，支持按日期筛选，导出结果字段与报表一致，异常时返回明确错误码」。写不出三条，说明选题还太模糊，需要再收一收。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"做个用户系统（模糊）\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">做个用户系统（模糊）</tspan></text></g><g data-k=\"实现订单导出接口，含三条验收\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"94.8\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">实现订单导出接口，含三</tspan><tspan x=\"295.0\" dy=\"15.600000000000001\">条验收</tspan></text></g></svg>","d":42.0},{"t":"填写立项卡","n":"把选题、业务价值、范围边界、验收标准写成立项卡。这张卡是项目的起点，后面每一节都会回到它。选好题，你就成功了一半。立项卡四栏——选题、价值、范围、验收——要写得让一个不了解你项目的人也能看懂。这张卡是后面所有工作的锚：每次想扩大范围时回头看一眼，它会提醒你当初答应交付的是什么。写不出这四栏，就说明选题还要再收一收。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"选题\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">选题</tspan></text></g><g data-k=\"价值\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">价值</tspan></text></g><g data-k=\"范围\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">范围</tspan></text></g><g data-k=\"验收\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">验收</tspan></text></g></svg>","d":38.9},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「结业项目说明与选题」。能选出一个范围合适、可验收的结业项目把今天最有价值的三点写进产出物「选题立项卡」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：填一张选题立项卡并说明验收方式。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":41.4}],"quiz":[{"q":"结业项目选题最重要的是？","opts":["越难越好","范围可控、真实、可验收","字数够多","用最炫的技术"],"a":1,"why":"选题要在能力范围内可完成、来自真实场景、结果可验收，否则无法结业。"},{"q":"选题过大时会怎样？","opts":["显得厉害","做不完、无法验收，反而失败","更容易通过","AI 会自动完成"],"a":1,"why":"范围失控会导致项目无法完成和验收，是选题最常见的失败模式。"}],"template":"【选题立项卡】\n题目：____\n业务价值：____\n范围边界：____\n验收标准：1____ 2____ 3____","brief":"【本单元要点】选题决定结业项目能不能做成\n【为什么重要】学员选了一个过大题目，两周都做不完\n【看完做一件事】填一张选题立项卡并说明验收方式。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M7U2","tier":"core","step":"todo","title":"需求拆解与验收定义","video":{"dur":"3.9min","script":["从立项卡到需求包","补需求五问","拆任务清单"]},"ppt":{"method":"把 M1 的方法用在结业项目上","case":"学员用五问和任务清单拆清了结业项目","demo":"项目需求包"},"objective":"为结业项目交付完整需求包","transfer":"能为自己的项目独立完成需求拆解","deliverable":{"type":"document","name":"项目需求包","rubric":["结构化需求","任务清单","验收标准"],"acceptance":"一份完整需求包，含结构化需求、任务清单、验收标准。"},"task":"为结业项目交付完整需求包。","rubric":["三部分齐全","验收可判定","任务可独立验证"],"vslides":[{"t":"从立项卡到需求包","n":"立项卡定了方向，现在要把方向变成可执行的需求包。这一步直接用 M1 学的方法：需求五问、任务拆解、验收标准。把当时学的东西真正用一次。从立项卡到需求包，是把四句话变成可执行工程的过程。立项卡定方向，需求包定细节；后面所有生成、审查、测试都直接消费这份需求包——它写得多清楚，后面的返工就有多少。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"五问\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">五问</tspan></text></g><g data-k=\"任务拆解\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">任务拆解</tspan></text></g><g data-k=\"验收标准\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">验收标准</tspan></text></g><g data-k=\"需求包\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">需求包</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":37.2},{"t":"补需求五问","n":"用谁用、场景、输入、输出、算好五问，把立项卡上的题目补成结构化需求。写具体，不要停留在「做一个导出功能」这种层面。补五问时，每一问都要写到具体。「谁用」要写岗位和权限，「场景」要写触发时机和频率，「输入输出」要写字段结构，「算好」要写可判定条件。哪一栏还是抽象的，就回去补，别带着模糊往下走。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"谁用\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">谁用</tspan></text></g><g data-k=\"场景\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">场景</tspan></text></g><g data-k=\"输入输出\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">输入输出</tspan></text></g><g data-k=\"算好\"><g><circle cx=\"30\" cy=\"154\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 154 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"158.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">算好</tspan></text></g></svg>","d":37.0},{"t":"拆任务清单","n":"用拆解指令让 AI 生成任务清单，每条含产出、验收、依赖。拆完检查粒度：每条能独立验证、能在一小段时间内完成。按依赖排好顺序。拆任务清单时，每条任务配产出物和验收口径，并标出依赖。你会发现有几条任务其实卡在同一个前置定义上——先把它挑出来做掉，后面的任务才能并行推进，顺序错了就会反复返工。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"产出\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">产出</tspan></text></g><g data-k=\"验收\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">验收</tspan></text></g><g data-k=\"依赖\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">依赖</tspan></text></g><g data-k=\"粒度\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">粒度</tspan></text></g></svg>","d":37.0},{"t":"定验收标准","n":"为整个项目写三到五条验收标准，覆盖正常、边界、异常。每条可判定。这些标准既是你的完成目标，也是答辩时评审的依据。定验收标准时，把「功能大概能用」换成三条可判定的句子。每条都要能被一个测试验证：正常路径什么结果、边界情况什么结果、异常时返回什么。写不出测试的标准，就不是标准。把三条标准贴进需求包开头，生成时 AI 会优先照顾。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"功能大概能用\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">功能大概能用</tspan></text></g><g data-k=\"三条可判定的验收标准\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">三条可判定的验收标准</tspan></text></g></svg>","d":44.6},{"t":"交付需求包","n":"把三部分合成需求包，用自检三问过一遍。这份包是结业项目的地基，后面所有工作都基于它。地基打牢，后面才顺。交付需求包前用三问自检：信息齐不齐、边界清不清、能不能验收。三问都过了，这份包就是后面所有环节的可靠输入；有一问不过，先补完再往下——这是整个结业项目最值得守的一道关。这份包也是答辩时的证据，留好别丢。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"五问\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">五问</tspan></text></g><g data-k=\"任务\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">任务</tspan></text></g><g data-k=\"验收\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">验收</tspan></text></g><g data-k=\"自检\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">自检</tspan></text></g></svg>","d":39.6},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「需求拆解与验收定义」。能为自己的项目独立完成需求拆解把今天最有价值的三点写进产出物「项目需求包」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：为结业项目交付完整需求包。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":39.8}],"quiz":[{"q":"结业项目需求拆解应交付？","opts":["只写一句需求","结构化需求+任务清单+验收标准","只画图","只写代码"],"a":1,"why":"完整需求包是后续所有工作的基础，三部分缺一不可。"},{"q":"验收标准在结业项目里的作用是？","opts":["可有可无","作为项目完成的判定依据","增加字数","给 AI 看"],"a":1,"why":"验收标准是判断项目是否完成的客观依据。"}],"template":"【项目需求包】\n结构化需求：____\n任务清单：____\n验收标准：____","brief":"【本单元要点】把 M1 的方法用在结业项目上\n【为什么重要】学员用五问和任务清单拆清了结业项目\n【看完做一件事】为结业项目交付完整需求包。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M7U3","tier":"core","step":"todo","title":"上下文与规则准备","video":{"dur":"4.0min","script":["为什么先备上下文","准备规则文件","准备代码库地图"]},"ppt":{"method":"上下文准备越充分，生成越顺利","case":"学员因没备规则文件，生成的代码风格全不对","demo":"项目上下文包"},"objective":"备好项目规则文件与代码库地图","transfer":"能为项目准备好完整的上下文材料","deliverable":{"type":"document","name":"项目上下文包","rubric":["规则文件","代码库地图","投喂清单"],"acceptance":"一份上下文包：含规则文件、代码库地图、投喂清单。"},"task":"为结业项目准备上下文包。","rubric":["三样齐全","规则含红线","清单可用"],"vslides":[{"t":"为什么先备上下文","n":"很多人拿到需求就直接开始生成，结果风格不对、文件放错、反复返工。M2 告诉我们：生成质量取决于上下文质量。结业项目开始前，先把上下文材料备齐，后面的生成会顺利得多。先备上下文再生成，是结业项目和日常随手写代码最大的区别。规则文件定标准、代码库地图给全貌、投喂清单定这次贴什么——三样准备好，AI 才知道在你的项目里该怎么写，而不是按通用习惯发挥。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"规则文件\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">规则文件</tspan></text></g><g data-k=\"代码库地图\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"76.4\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">代码库地</tspan><tspan x=\"152.8\" dy=\"16.900000000000002\">图</tspan></text></g><g data-k=\"投喂清单\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">投喂清单</tspan></text></g><g data-k=\"开始生成\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">开始生成</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":46.0},{"t":"准备规则文件","n":"把项目规则文件写好：技术栈、目录结构、命名规范、禁止项、验收要求。特别确认红线写进去了——数据不出域、密钥不硬编码、引用需核实。这份规则让 AI 从一开始就按你的约定生成。规则文件至少写四类：技术栈和版本、命名与目录约定、禁止项（尤其密钥不许硬编码）、验收要求。写的时候想想前面踩过的坑——那些最容易出错的地方，正是规则里最该写清楚的地方。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"技术栈\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">技术栈</tspan></text></g><g data-k=\"命名\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">命名</tspan></text></g><g data-k=\"禁止项\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">禁止项</tspan></text></g><g data-k=\"验收要求\"><g><circle cx=\"30\" cy=\"154\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 154 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"158.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">验收要求</tspan></text></g></svg>","d":43.6},{"t":"准备代码库地图","n":"为项目生成一份代码库地图：模块清单、职责、关键入口、依赖关系。如果项目很小，地图可以简单，但主干要清楚。它帮助 AI 快速定位该改哪里。代码库地图要写模块职责、关键入口和依赖关系。每个模块写清「负责什么、不负责什么」，AI 才不会把别人的逻辑塞进来。地图先让 AI 生成初稿，再由你校准——它对模块职责的猜测常常不准。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"模块\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">模块</tspan></text></g><g data-k=\"职责\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">职责</tspan></text></g><g data-k=\"入口\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">入口</tspan></text></g><g data-k=\"依赖\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">依赖</tspan></text></g></svg>","d":38.9},{"t":"准备投喂清单","n":"为项目的首个任务写投喂清单：要投喂哪些文件、什么顺序、重点标在哪。控制在最少必要。清单可以在后续任务中复用。投喂清单要按「目标文件→直接依赖→调用方」的顺序挑，并标出重点看哪里、哪里不许改。整库乱贴看似保险，实则把关键信号淹没了——最小必要加重点标注，才是稳定有效的做法。清单写清顺序，下次同类任务直接照着贴。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"整库乱贴（低效）\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">整库乱贴（低效）</tspan></text></g><g data-k=\"最小必要+重点标注\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">最小必要+重点标注</tspan></text></g></svg>","d":40.5},{"t":"交付上下文包","n":"把三样合成上下文包，检查一遍是否可用。这份包是结业项目顺利推进的保障，也是 M2 方法的一次实战检验。备好了，就可以进入生成环节。把三样合在一起交付，就是你的项目上下文包。后面每一次生成都从它开始；发现哪里写得不准就顺手更新——这个包会随着项目越用越准，也是你沉淀给团队的第一份资产。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"规则\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">规则</tspan></text></g><g data-k=\"地图\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">地图</tspan></text></g><g data-k=\"清单\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">清单</tspan></text></g><g data-k=\"交付\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">交付</tspan></text></g></svg>","d":35.3},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「上下文与规则准备」。能为项目准备好完整的上下文材料把今天最有价值的三点写进产出物「项目上下文包」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：为结业项目准备上下文包。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":34.2}],"quiz":[{"q":"结业项目上下文包应包含？","opts":["只有需求文档","规则文件+代码库地图+投喂清单","只有代码","只有截图"],"a":1,"why":"这三样是 M2 的核心方法，准备好才能让后续生成顺利。"},{"q":"规则文件里必须包含的是？","opts":["开发者的心情","技术栈、命名、禁止项、验收要求","AI 的名字","代码行数"],"a":1,"why":"这些是可执行的团队约定，尤其禁止项中的红线不可少。"}],"template":"【项目上下文包】\n规则文件：____\n代码库地图：____\n投喂清单：____","brief":"【本单元要点】上下文准备越充分，生成越顺利\n【为什么重要】学员因没备规则文件，生成的代码风格全不对\n【看完做一件事】为结业项目准备上下文包。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M7U4","tier":"core","step":"todo","title":"生成与审查","video":{"dur":"3.9min","script":["按规格生成","三问验收","安全初筛"]},"ppt":{"method":"生成和审查是一对动作，不能只做一半","case":"学员生成模块后跳过审查，评审时才发现安全问题","demo":"代码与审查报告"},"objective":"生成项目模块并完成结构审查","transfer":"能按规格生成模块并完成审查","deliverable":{"type":"document","name":"代码与审查报告","rubric":["生成代码","三问验收","安全初筛","审查报告"],"acceptance":"一份代码加审查报告，含三问验收和安全初筛结论。"},"task":"生成项目模块并完成结构审查。","rubric":["代码可运行","三问验收通过","有审查报告"],"vslides":[{"t":"按规格生成","n":"用你在 M7U2 写的需求和验收标准，结合 M7U3 的上下文包，按粒度从函数开始生成代码。用规格化指令，让 AI 一次给对。每个函数验证通过后再组合成模块。按规格生成，意味着你先把输入、输出、边界、验收写成一份规格，再让 AI 动手。规格来自前面的需求包和上下文包——它们准备了这么久，就是为了这一刻不用靠猜。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"规格\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">规格</tspan></text></g><g data-k=\"上下文\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">上下文</tspan></text></g><g data-k=\"生成\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">生成</tspan></text></g><g data-k=\"验证\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">验证</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":34.7},{"t":"三问验收","n":"对生成的代码做三问验收：正确性、安全性、可维护性。对照验收标准逐条检查，跑测试用例。任何一问不通过就定向优化，直到全过。三问验收逐项过：正确性对照需求、安全性扫注入密钥权限、可维护性看结构能不能接手。别因为「生成得挺快」就放松——生成速度恰恰是最容易让人跳过检查的诱饵。三问结果逐条写进审查报告，别只记结论。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"正确性\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">正确性</tspan></text></g><g data-k=\"安全性\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">安全性</tspan></text></g><g data-k=\"可维护性\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">可维护性</tspan></text></g></svg>","d":40.1},{"t":"安全初筛","n":"按安全初筛清单扫注入、密钥、权限三类高危，再检查性能和坏味道。AI 初筛后人工确认，特别是业务相关的判断。安全初筛扫四类：注入、密钥、权限、信息泄漏。前三类前面已经练过，这一轮要在真实项目里再跑一遍——你会发现真实代码里的风险点比练习时多，而且常常藏在「内部用」的地方。初筛发现的每一条，都要标出处理意见。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"注入\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">注入</tspan></text></g><g data-k=\"密钥\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">密钥</tspan></text></g><g data-k=\"权限\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">权限</tspan></text></g><g data-k=\"性能坏味道\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">性能坏味道</tspan></text></g></svg>","d":37.5},{"t":"生成审查报告","n":"把发现的问题按阻断、重要、建议分级，写进审查报告，每条有修复建议。阻断级问题必须修完才能继续。报告是这一节的产出之一。生成审查报告时，每条问题写清位置、级别、原因和修复方向。发现问题不记录，等于没发现——过两天你就忘了当时为什么觉得有问题，而那个问题还在代码里。报告写完再往下走，别带着未记录的问题进测试。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"发现问题不记录\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">发现问题不记录</tspan></text></g><g data-k=\"分级报告+修复建议\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">分级报告+修复建议</tspan></text></g></svg>","d":41.4},{"t":"进入测试环节","n":"代码通过审查后，就进入了测试环节。带着代码、审查报告和要求，进入下一节为它补齐测试。审查报告写完，就可以进入测试环节了。这里有一个判断：如果三问里有阻断级问题，先修再往下测——给一段正确性存疑的代码补测试，只会把错误固化成「已验证」。这一步的判断，决定了后面测的是可靠的东西还是隐患。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"生成\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">生成</tspan></text></g><g data-k=\"三问验收\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">三问验收</tspan></text></g><g data-k=\"安全初筛\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">安全初筛</tspan></text></g><g data-k=\"审查报告\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">审查报告</tspan></text></g></svg>","d":36.5},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「生成与审查」。能按规格生成模块并完成审查把今天最有价值的三点写进产出物「代码与审查报告」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：生成项目模块并完成结构审查。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":41.4}],"quiz":[{"q":"生成代码后，正确的下一步是？","opts":["直接进入交付","做三问验收和安全审查","再生成一遍","截图保存"],"a":1,"why":"生成与审查是一对动作，必须经过验收和审查才能进入后续环节。"},{"q":"审查报告里安全初筛的重点是？","opts":["注释是否好看","注入、密钥、权限三类高危","代码行数","命名风格"],"a":1,"why":"注入、密钥、权限是最高频且后果严重的安全问题，优先筛。"}],"template":"【代码与审查报告】\n模块代码：____\n三问验收：____\n安全初筛：____\n问题分级：____","brief":"【本单元要点】生成和审查是一对动作，不能只做一半\n【为什么重要】学员生成模块后跳过审查，评审时才发现安全问题\n【看完做一件事】生成项目模块并完成结构审查。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M7U5","tier":"core","step":"todo","title":"测试与重构","video":{"dur":"3.9min","script":["生成三类用例","生成测试代码","覆盖率补漏"]},"ppt":{"method":"测试是交付前的最后一道质量闸门","case":"学员的项目因缺测试，答辩时被质疑质量","demo":"项目测试集"},"objective":"为项目模块补齐测试并通过覆盖率","transfer":"能为自己的模块交付可靠测试","deliverable":{"type":"document","name":"项目测试集","rubric":["三类用例","测试代码","覆盖率报告","审查结论"],"acceptance":"一套可靠测试，含用例、代码、覆盖率报告、审查结论。"},"task":"为项目模块补齐测试并交付。","rubric":["三类用例齐全","覆盖率达标","测试经过审查"],"vslides":[{"t":"生成三类用例","n":"基于项目规格，让 AI 按正常、边界、异常三类生成用例，你补上业务特有的场景。为每个用例确认预期结果。生成三类用例：正常、边界、异常，再加业务特有场景。业务场景这一类是重点——它来自你的需求包，是别人替你想不到的部分。漏掉它，覆盖率再高也挡不住真实业务里的问题。四类用例分栏写，别混成一张流水账。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"正常\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">正常</tspan></text></g><g data-k=\"边界\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">边界</tspan></text></g><g data-k=\"异常\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">异常</tspan></text></g><g data-k=\"业务场景\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">业务场景</tspan></text></g></svg>","d":35.4},{"t":"生成测试代码","n":"让 AI 基于用例生成测试代码，运行并分析失败。对失败用 M5U4 的方法定位根因——是代码问题还是用例问题。修复后重跑。生成测试代码后立刻运行，对失败逐一分析：是代码问题还是用例问题？先判断再动手，别习惯性改代码。有些失败其实是用例期望写错了，改代码反而会把正确的实现改坏。判断理由写进记录，答辩时会被问到。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"生成\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">生成</tspan></text></g><g data-k=\"运行\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">运行</tspan></text></g><g data-k=\"分析失败\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">分析失败</tspan></text></g><g data-k=\"修复\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">修复</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":43.3},{"t":"覆盖率补漏","n":"看覆盖率报告，找出未覆盖的关键路径并补测。判断标准是影响大不大、后果严不严重。补到关键路径都有测试守住。看覆盖率报告找关键未覆盖路径，而不是盯着百分比。优先补涉及金额、权限和核心流程的分支；边缘的日志分支可以诚实标注「不补，原因如下」——有理由的省略和忘了测是两回事。补测后重跑全套，确认没有影响原有用例。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"看报告\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">看报告</tspan></text></g><g data-k=\"找关键未覆盖\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">找关键未覆盖</tspan></text></g><g data-k=\"补测复测\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">补测复测</tspan></text></g></svg>","d":40.8},{"t":"测试审查","n":"按测试审查清单检查：断言是否有效、覆盖是否真实、有没有过度拟合。修正不可靠的测试，确认测试经得起 QA 的质疑。测试审查三件套：断言是否有效、覆盖是否真实、是否过度拟合。AI 生成的测试是初稿，恒真断言和名实不符的用例要靠这三步挡住——它们制造的是虚假安全感，比没有测试更危险。审查记录也放进作品集，它是质量意识的证据。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"恒真断言（无效）\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">恒真断言（无效）</tspan></text></g><g data-k=\"有效断言（可靠）\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">有效断言（可靠）</tspan></text></g></svg>","d":38.2},{"t":"交付测试集","n":"把用例、代码、覆盖率报告、审查结论打包交付。这是结业项目的重要组成，也是你答辩时证明质量的依据。交付测试集时，用例、代码、覆盖率报告、审查记录四样齐全。别人拿到它，能看懂测了什么、为什么这么测、还有哪些没测——这就是可交接的测试集，也是作品集里最有说服力的一件。这套东西也是答辩时最有说服力的材料之一。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"用例\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">用例</tspan></text></g><g data-k=\"代码\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">代码</tspan></text></g><g data-k=\"覆盖率\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">覆盖率</tspan></text></g><g data-k=\"审查\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">审查</tspan></text></g></svg>","d":38.4},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「测试与重构」。能为自己的模块交付可靠测试把今天最有价值的三点写进产出物「项目测试集」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：为项目模块补齐测试并交付。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":37.5}],"quiz":[{"q":"交付测试集前必须确认？","opts":["测试数量","断言可靠、覆盖关键路径","运行速度","框架先进"],"a":1,"why":"测试的价值在可靠和有效覆盖关键路径，而非数量或速度。"},{"q":"覆盖率没达标时正确的做法是？","opts":["调低目标","补测未覆盖的关键路径","删除未覆盖代码","忽略"],"a":1,"why":"应补测关键路径，而不是调低目标或掩盖问题。"}],"template":"【项目测试集】\n用例数：____\n覆盖率：____\n审查结论：____","brief":"【本单元要点】测试是交付前的最后一道质量闸门\n【为什么重要】学员的项目因缺测试，答辩时被质疑质量\n【看完做一件事】为项目模块补齐测试并交付。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M7U6","tier":"core","step":"todo","title":"交付文档与 PR","video":{"dur":"3.6min","script":["用 AI 生成初稿","校准技术方案","校准 API 文档"]},"ppt":{"method":"文档让项目从「我做了」变成「大家懂」","case":"答辩时评审看不懂实现思路，因为没写方案","demo":"交付文档包"},"objective":"生成技术方案、API 文档与 PR 描述","transfer":"能为项目生成完整交付文档","deliverable":{"type":"document","name":"交付文档包","rubric":["技术方案","API 文档","PR 描述"],"acceptance":"一份文档包：技术方案、API 文档、PR 描述齐全。"},"task":"为项目生成完整交付文档。","rubric":["三样齐全","人工校准过","可支撑答辩"],"vslides":[{"t":"用 AI 生成初稿","n":"把代码和设计交给 AI，按模板生成技术方案、API 文档、PR 描述的初稿。明确的格式要求能得到结构规整的初稿，省下大量组织文字的时间。用 AI 生成文档初稿，先给它足够材料：需求包、代码、审查报告、测试集。材料越全，初稿越接近可用；只给代码就想要完整方案，它只能靠猜背景和意图——猜出来的东西你还得重写。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"给材料\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">给材料</tspan></text></g><g data-k=\"AI 生成\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">AI 生成</tspan></text></g><g data-k=\"人工校准\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">人工校准</tspan></text></g><g data-k=\"定稿\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">定稿</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":35.8},{"t":"校准技术方案","n":"技术方案里补充背景、目标、关键决策和权衡——这些 AI 不知道。确认架构描述准确、决策有理由、风险有说明。方案是答辩时讲设计思路的依据。校准技术方案时，重点看背景目标有没有写偏、关键决策有没有写清权衡、风险有没有如实说明。AI 常把「我们选了 A」写得理所当然，却漏掉「为什么没选 B」——那恰恰是评审最想看的部分。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"背景目标\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">背景目标</tspan></text></g><g data-k=\"关键决策\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">关键决策</tspan></text></g><g data-k=\"风险说明\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">风险说明</tspan></text></g></svg>","d":40.8},{"t":"校准 API 文档","n":"API 文档重点校准参数类型、必填性、错误码。让一个同事照着文档试着理解接口，如果他能看懂，文档就合格。校准 API 文档时，逐项核对参数类型、必填性、取值范围、枚举含义、错误码和示例。特别留意默认值和边界行为——调用方最容易踩的坑，就是文档里没写的那些默认行为。示例一定要真跑一遍，别照抄 AI 写的伪代码。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"参数类型\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">参数类型</tspan></text></g><g data-k=\"必填性\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">必填性</tspan></text></g><g data-k=\"错误码\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">错误码</tspan></text></g><g data-k=\"示例\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">示例</tspan></text></g></svg>","d":36.8},{"t":"完善 PR 描述","n":"PR 描述按四部分写清：改了什么、为什么、影响范围、怎么验证。假设评审人只读这段就要理解变更。写完自己读一遍，不通顺就改。完善 PR 描述时，把改了什么、为什么、影响范围、怎么验证四段补齐。别写成「修复 bug」——评审人看不懂的 PR，会变成三轮追问，省下的十分钟最后赔进去半小时。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"修复 bug（评审看不懂）\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">修复 bug（评审看不懂）</tspan></text></g><g data-k=\"四部分齐全的变更说明\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">四部分齐全的变更说明</tspan></text></g></svg>","d":33.3},{"t":"交付文档包","n":"把三样合成文档包，与代码、测试一起构成完整交付。文档是答辩的重要材料——它让评审看到你不只会写代码，还能讲清为什么这么写。把技术方案、API 文档、PR 描述合成交付文档包，和前面的代码、测试放一起。四样齐全，你的结业项目才算真正可交接——这也是作品集里区分「做过」和「交付过」的关键。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"技术方案\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">技术方案</tspan></text></g><g data-k=\"API 文档\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">API 文档</tspan></text></g><g data-k=\"PR 描述\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">PR 描述</tspan></text></g><g data-k=\"交付\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">交付</tspan></text></g></svg>","d":36.3},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「交付文档与 PR」。能为项目生成完整交付文档把今天最有价值的三点写进产出物「交付文档包」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：为项目生成完整交付文档。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":35.2}],"quiz":[{"q":"交付文档包应包含？","opts":["只有代码","技术方案+API 文档+PR 描述","只有截图","只有需求"],"a":1,"why":"这三样让评审和后来者理解设计、使用和变更，是完整交付的必要组成。"},{"q":"AI 生成的文档必须？","opts":["直接使用","人工校准业务背景与关键判断","删掉重写","打印出来"],"a":1,"why":"AI 不了解业务背景与设计权衡，这些部分必须人工补充校准。"}],"template":"【交付文档包】\n技术方案：____\nAPI 文档：____\nPR 描述：____\n校准结论：____","brief":"【本单元要点】文档让项目从「我做了」变成「大家懂」\n【为什么重要】答辩时评审看不懂实现思路，因为没写方案\n【看完做一件事】为项目生成完整交付文档。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M7U7","tier":"core","step":"spar","title":"陪练：模拟评审会","video":{"dur":"4.0min","script":["评审会说明","开场：讲清你的项目","产品经理的质疑"]},"ppt":{"method":"答辩是让成果被看见、被检验的时刻","case":"学员在评审会上被三个角色轮番追问，准备了依据所以扛住了","demo":"答辩记录"},"objective":"在三个角色追问下完成答辩","transfer":"能在多角色评审中清晰讲述并回应质疑","deliverable":{"type":"document","name":"答辩记录","rubric":["三个角色","质疑与回应","评审结论"],"acceptance":"一份记录：写下三个角色的质疑、你的回应、最终评审结论。"},"task":"完成一次三角色模拟评审并记录。","rubric":["覆盖三个角色","回应有依据","有评审结论"],"vslides":[{"t":"评审会说明","n":"这是结业前的模拟评审会。AI 会依次扮成三个角色：产品经理问需求是否兑现、Reviewer 问设计与代码质量、QA 问测试与质量证据。你要在短时间内讲清你的项目，然后回应每个角色的质疑。评审会是这门课最后一道关：三个角色从不同角度追问你的项目。产品经理问价值兑现，Reviewer 问设计质量，QA 问测试证据。他们合起来，模拟的是你回岗后真实要面对的评审现场。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"产品经理\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">产品经理</tspan></text></g><g data-k=\"Reviewer\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">Reviewer</tspan></text></g><g data-k=\"QA\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">QA</tspan></text></g><g data-k=\"结论\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">结论</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":37.5},{"t":"开场：讲清你的项目","n":"先用两分钟讲项目：解决了什么问题、做成了什么、怎么验证的。用你的立项卡、验收标准、测试报告作为依据。开场清楚，后面的质疑就好应对。开场两分钟讲清三件事：解决了什么问题、完成了哪些内容、有什么验证证据。证据要具体——覆盖率数字、测试结果、验收标准达成情况。开场立住事实，后面的追问才有底气。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"问题价值\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">问题价值</tspan></text></g><g data-k=\"完成内容\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">完成内容</tspan></text></g><g data-k=\"验证证据\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">验证证据</tspan></text></g></svg>","d":36.5},{"t":"产品经理的质疑","n":"产品经理会问：需求都实现了吗、边界考虑了没、能不能上线。用你的需求包和验收标准逐条回应，展示哪些已完成、哪些是已知限制。诚实说明限制，比含糊承诺更可信。产品经理质疑时，他会问需求有没有真正兑现、边界怎么处理、已知限制是什么。别把限制藏起来——主动说出「这一版不支持 X，因为 Y」，比被问出来更可信；承认边界是成熟的表现。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"需求兑现\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">需求兑现</tspan></text></g><g data-k=\"边界处理\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">边界处理</tspan></text></g><g data-k=\"已知限制\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"148.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"111.5\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">已知限制</tspan></text></g></svg>","d":41.8},{"t":"Reviewer 与 QA 的质疑","n":"Reviewer 问设计和代码质量：为什么这么设计、审查发现的问题改了没。QA 问测试证据：覆盖率多少、关键路径测了吗。用审查报告和测试报告回应。两个角色是最考验你准备程度的环节。Reviewer 和 QA 的质疑要用报告和数据回应，不能凭感觉。「我觉得没问题」在这里无效；「三问验收全过、安全初筛零阻断、覆盖率 85%、缺的是这两个边缘分支」——这样的回答才站得住。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"凭感觉回答\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">凭感觉回答</tspan></text></g><g data-k=\"用报告和数据回应\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">用报告和数据回应</tspan></text></g></svg>","d":45.0},{"t":"通过标准与记录","n":"通过标准是：三个角色的质疑中至少两轮有依据回应，且没有任何一轮答非所问。结束后写答辩记录。这场评审既是结业考核，也是你真实工作中评审会的预演。通过标准是开场陈述清楚、三个角色都能有据回应、最后有明确评审结论。无论结论是通过还是「需补几项后再评」，都把问答过程完整记录下来——这份答辩记录本身就是你沟通能力的证据。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"开场陈述\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">开场陈述</tspan></text></g><g data-k=\"三角色回应\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">三角色回应</tspan></text></g><g data-k=\"评审结论\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">评审结论</tspan></text></g><g data-k=\"记录\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">记录</tspan></text></g></svg>","d":37.7},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「陪练：模拟评审会」。能在多角色评审中清晰讲述并回应质疑把今天最有价值的三点写进产出物「答辩记录」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：完成一次三角色模拟评审并记录。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":39.6}],"quiz":[{"q":"模拟评审会通常不包括哪个角色？","opts":["产品经理","Reviewer 或安全专家","QA","无关的路人"],"a":3,"why":"评审角色来自真实项目相关方——产品、技术、质量、安全，不包括无关人员。"},{"q":"答辩时被质疑，最好的策略是？","opts":["用依据和演示回应","坚持己见不解释","回避问题","说这是 AI 做的"],"a":0,"why":"用需求、测试、演示作为依据回应，被问倒就诚实承认，是专业的答辩态度。"}],"template":"【答辩记录】\n产品经理质疑____ 回应____\nReviewer 质疑____ 回应____\nQA 质疑____ 回应____\n评审结论：____","brief":"【本单元要点】答辩是让成果被看见、被检验的时刻\n【为什么重要】学员在评审会上被三个角色轮番追问，准备了依据所以扛住了\n【看完做一件事】完成一次三角色模拟评审并记录。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"},{"id":"M7U8","tier":"core","step":"understand","title":"成果验收与复盘","video":{"dur":"4.2min","script":["对照 rubric 自评","汇集结业作品集","写一页成长复盘"]},"ppt":{"method":"结业不是终点，是下一段成长的起点","case":"学员对照 rubric 自评，发现自己已到「良好」但仍有短板","demo":"结业作品集 + 复盘"},"objective":"对照 rubric 自评并沉淀一页复盘","transfer":"能对照结业标准自评并规划后续成长","deliverable":{"type":"document","name":"结业作品集 + 复盘","rubric":["作品集","rubric 自评","成长复盘"],"acceptance":"一份结业作品集：汇集各章产出，附 rubric 自评和一页成长复盘。"},"task":"完成结业自评和一页复盘。","rubric":["作品集完整","自评有依据","复盘具体"],"vslides":[{"t":"对照 rubric 自评","n":"课程给了四级 rubric：未达标、入门、合格、良好、优秀。对照你的结业项目逐项评定：代码能不能跑、有没有测试、有没有审查报告、经验有没有沉淀。给自己一个诚实的位置，不要高估也不要低估。对照 rubric 自评时，别凭印象打勾，逐条拿作品集里的证据说话：需求包在哪、代码是否通过三问、测试集覆盖率多少、交付文档齐不齐。能指出证据的自评，才配得上那个等级。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"未达标\"><rect x=\"18.0\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">未达标</tspan></text></g><g data-k=\"入门\"><rect x=\"145.3\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">入门</tspan></text></g><g data-k=\"合格\"><rect x=\"272.7\" y=\"34.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"327.3\" y=\"72.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"327.3\">合格</tspan></text></g><g data-k=\"良好\"><rect x=\"18.0\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"72.7\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"72.7\">良好</tspan></text></g><g data-k=\"优秀\"><rect x=\"145.3\" y=\"113.0\" width=\"109.3\" height=\"69.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"200.0\" y=\"151.0\" font-size=\"11.5\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"200.0\">优秀</tspan></text></g></svg>","d":42.0},{"t":"汇集结业作品集","n":"把各章产出汇集起来：M1 需求包、M2 上下文包、M3 模块代码、M4 审查报告、M5 测试集、M6 交付包、M7 答辩记录。这份作品集是你学习成果的完整证据，也是可以展示给主管或同行的材料。汇集结业作品集，把需求包、代码与审查报告、测试集、交付包、答辩记录五样放在一起，按这个顺序排。它讲的是一个完整故事：从一句需求到一个可交接的产物——这正是这门课的全部。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">要点</tspan></text><g data-k=\"需求包\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">需求包</tspan></text></g><g data-k=\"代码与审查\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">代码与审查</tspan></text></g><g data-k=\"测试集\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">测试集</tspan></text></g><g data-k=\"交付包\"><g><circle cx=\"30\" cy=\"154\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 154 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"158.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">交付包</tspan></text></g></svg>","d":43.3},{"t":"写一页成长复盘","n":"用一页写下：学之前你用 AI 编码的状态、学完之后能做什么、哪个环节收获最大、还有哪些不足、下一步打算怎么用。这份复盘让学习从「上过课」变成「有改变」。写一页成长复盘：学之前你怎么用 AI、学之后有什么不同、最大的收获是什么、下一步打算怎么做。重点写「行为变了什么」，而不是「学到了哪些知识」——知识会忘，行为改变才是真结果。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"学之前\"><rect x=\"18.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"58.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"58.2\">学之前</tspan></text></g><g data-k=\"学之后\"><rect x=\"112.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"152.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"152.8\">学之后</tspan></text></g><g data-k=\"最大收获\"><rect x=\"207.0\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"247.2\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"247.2\">最大收获</tspan></text></g><g data-k=\"下一步\"><rect x=\"301.5\" y=\"42.0\" width=\"80.5\" height=\"78.0\" rx=\"10\" fill=\"#16204a\" stroke=\"#3b7bff\" stroke-width=\"2\"/><text x=\"341.8\" y=\"84.9\" font-size=\"13.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"341.8\">下一步</tspan></text></g><path d=\"M100.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M195.0 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><path d=\"M289.5 81.0 l8 0\" stroke=\"#3b7bff\" stroke-width=\"2\" marker-end=\"url(#arr)\"/><defs><marker id=\"arr\" orient=\"auto\" markerWidth=\"8\" markerHeight=\"8\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#3b7bff\"/></marker></defs></svg>","d":40.5},{"t":"回岗转化：48 小时动作","n":"选一个回工位 48 小时内就能做的动作：把你的规则文件分享给同组、用需求五问拆下一个真实任务、把一条经验写进团队知识库。行为的改变从一个具体动作开始。回岗转化靠 48 小时动作：找一件真实任务，用这套方法完整跑一遍，哪怕只是其中一个环节。学完不做到，一切都会在一周内归零；第一个真实动作，是把课程变成能力的关键一跃。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"105.0\" y=\"36.0\" font-size=\"12\" fill=\"#ff9bb0\" text-anchor=\"middle\"><tspan x=\"105.0\">踩红线</tspan></text><text x=\"295.0\" y=\"36.0\" font-size=\"12\" fill=\"#9be8b0\" text-anchor=\"middle\"><tspan x=\"295.0\">守红线</tspan></text><g data-k=\"学完就结束\"><rect x=\"30.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#3a1a0c\" stroke=\"#e11d48\" stroke-width=\"2\"/><text x=\"105.0\" y=\"102.6\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"105.0\">学完就结束</tspan></text></g><g data-k=\"48 小时内做一个真实动作\"><rect x=\"220.0\" y=\"46.0\" width=\"150.0\" height=\"106.0\" rx=\"10\" fill=\"#0f3d24\" stroke=\"#16a34a\" stroke-width=\"2\"/><text x=\"295.0\" y=\"94.8\" font-size=\"12.0\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\"><tspan x=\"295.0\">48 小时内做一个真实动</tspan><tspan x=\"295.0\" dy=\"15.600000000000001\">作</tspan></text></g></svg>","d":39.6},{"t":"课程结束，实践开始","n":"AI Coding 不是一个学完就结束的知识点，而是一种需要持续练习的工作方式。工具会变、模型会更新，但你在课程里建立的方法——定义问题、验收产出、承担责任——是长期有用的。带着作品集和复盘，回到真实工作里继续练。课程结束了，实践才刚开始。把作品集、复盘和 48 小时动作记录留好，一个月后回头看——那时你会发现，真正留下来的不是笔记，而是你已经改掉的工作方式。这才是这门课想给你的东西。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><g data-k=\"自评\"><g><circle cx=\"42\" cy=\"42.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"46.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">①</text></g><text x=\"70.0\" y=\"46.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">自评</tspan></text></g><g data-k=\"作品集\"><g><circle cx=\"42\" cy=\"74.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"78.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">②</text></g><text x=\"70.0\" y=\"78.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">作品集</tspan></text></g><g data-k=\"复盘\"><g><circle cx=\"42\" cy=\"106.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"110.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">③</text></g><text x=\"70.0\" y=\"110.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">复盘</tspan></text></g><g data-k=\"回岗行动\"><g><circle cx=\"42\" cy=\"138.0\" r=\"12\" fill=\"#1a5cff\"/><text x=\"42\" y=\"142.5\" font-size=\"12\" fill=\"#fff\" text-anchor=\"middle\">④</text></g><text x=\"70.0\" y=\"142.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"70.0\">回岗行动</tspan></text></g></svg>","d":46.1},{"t":"本节小结 · 带走什么","n":"这一节我们讲了「成果验收与复盘」。能对照结业标准自评并规划后续成长把今天最有价值的三点写进产出物「结业作品集 + 复盘」里，它会在结业项目里直接派上用场。回到工位后先做一件小事：完成结业自评和一页复盘。做的时候守住三条硬约束——数据不出域、结论有人复核、判断有依据。学完记得完成本节的通关测验，用它检验你能不能在情境里做对判断。","s":"<svg viewBox=\"0 0 400 200\" width=\"100%\" height=\"100%\" preserveAspectRatio=\"xMidYMid meet\"><text x=\"200.0\" y=\"26.0\" font-size=\"13\" fill=\"#7aa2ff\" text-anchor=\"middle\"><tspan x=\"200.0\">本节小结</tspan></text><g data-k=\"记住一个结论\"><g><circle cx=\"30\" cy=\"52\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 52 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"56.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">记住一个结论</tspan></text></g><g data-k=\"写进产出物\"><g><circle cx=\"30\" cy=\"86\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 86 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"90.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">写进产出物</tspan></text></g><g data-k=\"用于结业项目\"><g><circle cx=\"30\" cy=\"120\" r=\"10.5\" fill=\"none\" stroke=\"#3b7bff\" stroke-width=\"2\"/><path d=\"M25.5 120 l3.6 3.6 l6.4 -7.4\" stroke=\"#16a34a\" stroke-width=\"2.4\" fill=\"none\"/></g><text x=\"54.0\" y=\"124.5\" font-size=\"12.5\" fill=\"#eaf0ff\" text-anchor=\"start\"><tspan x=\"54.0\">用于结业项目</tspan></text></g></svg>","d":39.4}],"quiz":[{"q":"结业自评的依据是？","opts":["自我感觉","课程给出的 rubric 四级标尺","代码行数","用时长短"],"a":1,"why":"rubric 提供客观分级标准，让自评有据可依。"},{"q":"课程结束后，最应该做的一件事是？","opts":["再也不碰 AI","把方法用到下周的真实工作并持续沉淀","把所有资料删掉","只记住提示词"],"a":1,"why":"学习价值在于迁移到真实工作并持续迭代，而不是停留在课程里。"}],"template":"【结业复盘】\nrubric 自评级别：____\n最大收获：____\n继续练习的方向：____\n48 小时行动：____","brief":"【本单元要点】结业不是终点，是下一段成长的起点\n【为什么重要】学员对照 rubric 自评，发现自己已到「良好」但仍有短板\n【看完做一件事】完成结业自评和一页复盘。\n【硬约束】数据不出域 · 结论有人复核 · 判断有依据"}]}]};
